// /generated-from-filter-pattern-registry:TEST_CORRECTNESS_PATTERNS

// Port of _route_by_dimension. Returns "main", "suggestion", or null (fall
// through to agent-based routing in tagFindings).
function routeByDimension(finding) {
  const dimension = pyGet(finding, 'dimension', '').toLowerCase();
  if (!dimension) return null;

  if (MAIN_DIMENSIONS.has(dimension)) return 'main';
  if (SUGGESTION_DIMENSIONS.has(dimension)) return 'suggestion';

  if (CONDITIONAL_SUGGESTION_DIMENSIONS.has(dimension)) {
    const combined = `${asText(pyGet(finding, 'title', ''))}\n${asText(pyGet(finding, 'description', ''))}`;

    if (dimension === 'test_coverage') {
      return TEST_CORRECTNESS_PATTERNS.some((rx) => rx.test(combined)) ? 'main' : 'suggestion';
    }
    if (dimension === 'convention') {
      return FUNCTIONAL_VIOLATION_KEYWORDS.test(combined) ? 'main' : 'suggestion';
    }
    if (dimension === 'type_design') {
      return TYPE_SAFETY_BUG_KEYWORDS.test(combined) ? 'main' : 'suggestion';
    }
  }

  return null;
}

// Port of _is_test_correctness_finding.
function isTestCorrectnessFinding(finding) {
  const combined = `${asText(pyGet(finding, 'title', ''))}\n${asText(pyGet(finding, 'description', ''))}`;
  return TEST_CORRECTNESS_PATTERNS.some((rx) => rx.test(combined));
}

// --- Proximity grouping + cross-agent dedup ---------------------------------

// Port of group_by_proximity. Returns a Map keyed by JSON.stringify([file,
// bucket]) -- an internal grouping key with no Python equivalent string
// form; only consolidateCrossAgent (and, later, applyChallenges per the brief)
// consume the grouping, never its literal key shape.
function groupByProximity(findings, lineProximity = 5) {
  const groups = new Map();
  for (const finding of findings) {
    const key = JSON.stringify([pyGet(finding, 'file', ''), lineBucket(pyGet(finding, 'line_start', 0), lineProximity)]);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(finding);
  }
  return groups;
}

// Port of consolidate_cross_agent (#22 D1 -- replaces the old dedup_cross_agent
// eliminator). NOTHING is dropped: for each proximity group (same file, same
// 5-line bucket) that has 2+ findings from 2+ DIFFERENT agents, every member
// with a truthy "id" is stamped with a shared `consolidation_key` and exactly
// one of them gets `consolidation_primary: true` (the rest get `false`).
// Same-agent-only groups and singletons get no stamps at all. A finding
// without a truthy "id" is immune -- it passes through completely unstamped,
// mirroring the old eliminator's "no id, no dedup" immunity.
//
// Primary selection reuses the OLD winner key (isCore, confidence,
// description.length), all DESCENDING via one stable composite comparator --
// this is deliberately origin-blind (#22 D3): since consolidation never drops
// anything, origin cannot cost delivery here, unlike rankKey/detectDisagreement
// which do gate on origin. Matches Python's `sorted(group, key=_winner_key,
// reverse=True)`, which for tied keys preserves original relative order
// (Python sort stability + reverse=True keeps ties in forward order, not
// reversed) -- V8's sort is equally stable, so a single multi-key comparator
// reproduces this without a second pass. The primary is the first RANKED
// member that actually has a truthy id (an id-less top-ranked member cannot
// carry the stamp, so ranking is walked until one does).
//
// EXPORTED for reuse by applyChallenges — keep this a standalone plain
// function with no closure over filterFindings-only state.
function consolidateCrossAgent(findings) {
  const LINE_PROXIMITY = 5;

  // Clear any stamps from a prior pass first: a re-run (applyChallenges, after
  // a group's primary is eliminated) must not leave survivors carrying a
  // consolidation_key/consolidation_primary from a group that no longer
  // qualifies.
  for (const f of findings) {
    if (f && typeof f === 'object') {
      delete f.consolidation_key;
      delete f.consolidation_primary;
    }
  }

  const winnerKey = (f) => {
    const dim = pyGet(f, 'dimension', '').toLowerCase();
    const isCore = CORE_DIMENSIONS.has(dim) ? 1 : 0;
    const conf = asConfidence(pyGet(f, 'confidence', 0));
    const descLen = asText(pyGet(f, 'description', '')).length;
    return [isCore, conf, descLen];
  };

  const compareWinnerDesc = (a, b) => {
    const ka = winnerKey(a);
    const kb = winnerKey(b);
    for (let i = 0; i < ka.length; i += 1) {
      if (ka[i] !== kb[i]) return kb[i] - ka[i];
    }
    return 0; // tie -> preserve original order (stable sort)
  };

  const groups = groupByProximity(findings, LINE_PROXIMITY);

  let consolidatedCount = 0;

  for (const group of groups.values()) {
    const agentsInGroup = new Set(group.map((f) => pyGet(f, 'agent', '').toLowerCase()));
    if (group.length < 2 || agentsInGroup.size < 2) continue; // no stamps

    const file = pyGet(group[0], 'file', '');
    const bucket = lineBucket(pyGet(group[0], 'line_start', 0), LINE_PROXIMITY);
    const consolidationKey = `${file}:${bucket}`;

    const ranked = [...group].sort(compareWinnerDesc);
    const primary = ranked.find((f) => pyGet(f, 'id', ''));

    for (const f of group) {
      if (!pyGet(f, 'id', '')) continue; // id-less findings stay unstamped
      f.consolidation_key = consolidationKey;
      f.consolidation_primary = f === primary;
      consolidatedCount += 1;
    }
  }

  return { findings, consolidatedCount };
}

// --- Tagging -----------------------------------------------------------

const MAIN_REPORT_AGENTS = new Set(['bug-detector', 'security-reviewer', 'cross-file-impact', 'type-design-analyzer']);
const SUGGESTION_AGENTS = new Set(['test-analyzer', 'code-simplifier']);
const CONVENTIONS_AGENT = 'conventions-and-intent';
const COMMENT_ACCURACY_DIMENSIONS = new Set(['comment-accuracy', 'documentation', 'doc-accuracy']);

// Port of tag_findings. Step 1 (cross-agent consolidation, D1 -- stamps,
// never drops) -> reachability routing -> dimension routing -> agent fallback.
// Returns { tagged, consolidatedCount, mainCount, suggestionCount }.
function tagFindings(findings) {
  const { findings: tagged, consolidatedCount } = consolidateCrossAgent(findings);

  let mainCount = 0;
  let suggestionCount = 0;

  for (const finding of tagged) {
    const agent = pyGet(finding, 'agent', '').toLowerCase();
    // Truthy check (not `'dimension' in finding`) on purpose -- mirrors the
    // established `finding.dimension ? [...] : []` idiom already used by
    // applyThresholdFilter above, which in turn mirrors Python's
    // `if finding.get("dimension")` (truthy, not presence) guard.
    const dimensions = finding.dimension ? new Set([String(finding.dimension).toLowerCase()]) : new Set();

    let destination;
    if (finding.demoted_by === 'reachability') {
      destination = 'suggestion';
      finding.routed_by = 'reachability';
    } else {
      const dimRoute = routeByDimension(finding);
      if (dimRoute !== null) {
        destination = dimRoute;
        if (dimRoute === 'suggestion') finding.routed_by = 'dimension';
      } else if (MAIN_REPORT_AGENTS.has(agent)) {
        destination = 'main';
      } else if (agent === CONVENTIONS_AGENT) {
        destination = [...dimensions].some((d) => COMMENT_ACCURACY_DIMENSIONS.has(d)) ? 'suggestion' : 'main';
      } else if (SUGGESTION_AGENTS.has(agent)) {
        if (agent === AGENT_TEST_ANALYZER && isTestCorrectnessFinding(finding)) {
          destination = 'main';
          finding.promoted_from = 'test-analyzer';
          finding.promotion_reason =
            'test-analyzer finding describes a functional correctness issue that exists today ' +
            '(not a missing-coverage gap)';
        } else {
          destination = 'suggestion';
        }
      } else {
        // Unknown agent -- conservative fallback: route to main.
        destination = 'main';
      }
    }

    finding.report_destination = destination;
    finding.report_tag = destination; // backward-compat alias
    if (destination === 'main') mainCount += 1;
    else suggestionCount += 1;
  }

  return { tagged, consolidatedCount, mainCount, suggestionCount };
}

// --- Pipeline composition ----------------------------------------------

// Port of main()'s filter pipeline composition (filter_findings.py:1296-1376),
// minus argparse/file I/O -- config and exclusionPatterns are passed in
// directly (already parsed by parseReviewMd/loadExclusions upstream), and
// generatedAt is injected (never `new Date()`/`Date.now()` -- workflow JS
// has no wall clock; see the Global Constraints "No wall-clock" rule).
function applyFilterPipeline(findings, config, exclusionPatterns, generatedAt) {
  const total = findings.length;

  normalizeFieldNames(findings);

  applyReachabilityDemotion(findings);

  // Python: `exclusion_patterns = config.get("ignore", []) + load_exclusions(...)`.
  const allExclusions = [...(config.ignore || []), ...(exclusionPatterns || [])];

  const allEliminated = [];

  const { kept: afterThreshold, eliminated: elimThreshold, contestedCount } = applyThresholdFilter(findings, config);
  allEliminated.push(...elimThreshold);
  const passedThreshold = afterThreshold.length;

  const { kept: afterExclusions, eliminated: elimExclusions } = applyExclusions(afterThreshold, allExclusions);
  allEliminated.push(...elimExclusions);
  const exclusionsRemoved = elimExclusions.length;

  const { kept: afterInjection, eliminated: elimInjection } = applyInjectionFilter(afterExclusions);
  allEliminated.push(...elimInjection);
  const injectionsRemoved = elimInjection.length;
  // One `{field}s_removed` stat per INJECTION_STRIPPED_PROSE_FIELDS entry --
  // looping the shared list (rather than one hardcoded .filter() per field)
  // means adding a field to the list is the only edit a future extension
  // needs (#213).
  const proseFieldsRemoved = Object.fromEntries(
    INJECTION_STRIPPED_PROSE_FIELDS.map((field) => [
      `${field}s_removed`,
      afterInjection.filter((f) => f[`${field}_removed_by`] === 'injection').length,
    ]),
  );
  const suggestedFixCodesRemoved = afterInjection.filter(
    (f) => f.suggested_fix_code_removed_by === 'injection',
  ).length;

  const { active, suppressed: elimSuppressed, boostedCount: consensusBoosted } = detectDisagreement(afterInjection);
  allEliminated.push(...elimSuppressed);

  const { tagged, consolidatedCount, mainCount, suggestionCount } = tagFindings(active);

  const promotedCount = tagged.filter((f) => f.promoted_from === 'test-analyzer').length;
  const dimensionRouted = tagged.filter((f) => f.routed_by === 'dimension').length;
  const reachabilityDemoted = [...tagged, ...allEliminated]
    .filter((f) => f.demoted_by === 'reachability').length;
  const singletonPenalized = [...tagged, ...allEliminated].filter((f) => f.singleton_penalty).length;

  return {
    filtered: tagged,
    eliminated: allEliminated,
    stats: {
      total,
      passed_threshold: passedThreshold,
      contested_count: contestedCount,
      exclusions_removed: exclusionsRemoved,
      injections_removed: injectionsRemoved,
      // Spliced, not hand-listed: proseFieldsRemoved's keys/order are exactly
      // INJECTION_STRIPPED_PROSE_FIELDS's (Object.fromEntries over the list, in
      // order), so adding a field to that list is the only edit a future stat needs
      // -- no second key to add here.
      ...proseFieldsRemoved,
      suggested_fix_codes_removed: suggestedFixCodesRemoved,
      consensus_boosted: consensusBoosted,
      singleton_penalized: singletonPenalized,
      dimension_routed: dimensionRouted,
      reachability_demoted: reachabilityDemoted,
      cross_agent_consolidated: consolidatedCount,
      test_analyzer_promoted: promotedCount,
      tagged_main: mainCount,
      tagged_suggestion: suggestionCount,
    },
    generated_at: generatedAt,
  };
}

// Port of apply_exclusions. First pattern (in list order) whose literal,
// case-insensitive substring appears in "title\ndescription\nsuggestion" wins.
// suggestion is included because it is rendered into posted PR/MR comments same
// as description -- user-authored ignore patterns are the user's kill-switch
// over everything that gets rendered (#62).
//
// claude_md_rule/spec_text are also rendered into posted comments (#213 gives
// them the same seven-set injection scan as suggestion), but are deliberately
// NOT added here: the actual discriminator is not "gets rendered" (true of
// all three) but cost. A `suggestion` exclusion match costs only that one
// agent-authored field; claude_md_rule/spec_text quote the user's own repo
// text, and a common CLAUDE.md phrasing (e.g. "MUST") would, via this
// whole-finding elimination, mass-eliminate the conventions dimension for an
// unbounded recall cost that the field-strip mechanism above does not carry.
// A user kill-switch reaching rendered citation text was declined on the
// #247 measurement (2026-08-31): the natural CLAUDE.md pattern eliminates 0
// findings today and widens 12 via model boilerplate, not user repo text.
function applyExclusions(findings, exclusionPatterns) {
  if (!exclusionPatterns || !exclusionPatterns.length) return { kept: findings, eliminated: [] };

  const kept = [];
  const eliminated = [];

  for (const finding of findings) {
    const title = asText(finding.title);
    const description = asText(finding.description);
    const suggestion = typeof finding.suggestion === 'string' ? finding.suggestion : '';
    const combined = `${title}\n${description}\n${suggestion}`;

    let matchedPattern = null;
    for (const pattern of exclusionPatterns) {
      const rx = new RegExp(escapeRegExp(pattern), 'i');
      if (rx.test(combined)) {
        matchedPattern = pattern;
        break;
      }
    }

    if (matchedPattern) {
      eliminated.push({
        ...finding,
        eliminated_by: 'exclusion',
        elimination_reason: `matched exclusion pattern: ${JSON.stringify(matchedPattern)}`,
      });
    } else {
      kept.push(finding);
    }
  }

  return { kept, eliminated };
}

// --- mergeFindings.js ---
// mergeFindings.js — JS twin of scripts/merge_findings.py (Phase 3->4 merge).
// Faithful port: parse two channels (NDJSON primary, text fallback), inject the
// agent field, validate dimension + required fields, dedup by id (NDJSON wins),
// detect truncation, assemble the Phase 4 envelope with methodology diagnostics.
//
// The Python original is disk-based (reads files under findings_dir/text_dir).
// This twin is fed the raw file CONTENTS keyed by agent instead, so an absent
// key mirrors a non-existent file (empty parse, no warning). Everything after
// the read boundary is a line-for-line port.

const KNOWN_DIMENSIONS = new Set([
  'bug',
  'security',
  'cross_file_impact',
  'test_coverage',
  'convention',
  'intent',
  'comment_accuracy',
  'type_design',
  'simplification',
]);

// Fixed array (Object.keys-deterministic). Python is a set; JS iteration order is
// irrelevant here — only "a missing-field warning exists per rejected finding" is
// asserted, and rejection breaks on the first missing field regardless of order.
const REQUIRED_FIELDS = ['id', 'file', 'line_start', 'title', 'description', 'severity', 'confidence'];

// --- Channel 1: NDJSON parsing ---------------------------------------------

// Port of parse_ndjson_file: one JSON object per non-blank line; a malformed line
// or a non-object becomes a warning, never a throw. `text === undefined/null`
// mirrors the Python `os.path.exists` false branch (no file -> empty, no warning).
function parseNdjson(text, agent) {
  const findings = [];
  const warnings = [];
  if (text === undefined || text === null) return { findings, warnings };

  let lineno = 0;
  for (const rawLine of text.split('\n')) {
    lineno += 1;
    const line = rawLine.trim();
    if (!line) continue;
    let obj;
    try {
      obj = JSON.parse(line);
    } catch (exc) {
      warnings.push(`[${agent}] NDJSON line ${lineno}: invalid JSON — ${exc.message}`);
      continue;
    }
    if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
      warnings.push(`[${agent}] NDJSON line ${lineno}: expected object, got ${jsonTypeName(obj)}`);
      continue;
    }
    findings.push(obj);
  }
  return { findings, warnings };
}

function jsonTypeName(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

// --- Channel 2: text fallback parsing --------------------------------------

// Port of _extract_json_blocks + _try_parse_json_at + _find_end_of_json: an
// escape-aware, balanced-brace char scanner (NOT a regex). Walks the text; at
// each '{' it tries to parse a balanced object and captures it only when the
// parse succeeds AND the object has an 'id' key, then skips past its end.
//
// UTF-16 note: JS indexes/`.length` by code unit (astral chars are surrogate
// pairs) where Python indexes by code point. The scanner only branches on the
// ASCII chars { } " \ — none of which a surrogate code unit can equal — and
// slices at ASCII brace boundaries, so the structural parse is identical across
// runtimes even with emoji/CJK inside string values.
function extractJsonBlocks(text) {
  const results = [];
  let i = 0;
  while (i < text.length) {
    if (text[i] !== '{') {
      i += 1;
      continue;
    }
    const obj = tryParseJsonAt(text, i);
    if (obj !== null && obj !== undefined && typeof obj === 'object' && !Array.isArray(obj) && 'id' in obj) {
      results.push(obj);
      i = findEndOfJson(text, i);
    } else {
      i += 1;
    }
  }
  return results;
}

function scanJsonObject(text, start) {
  let depth = 0;
  let inString = false;
  let escapeNext = false;
  let i = start;
  while (i < text.length) {
    const ch = text[i];
    if (escapeNext) {
      escapeNext = false;
      i += 1;
      continue;
    }
    if (ch === '\\' && inString) {
      escapeNext = true;
      i += 1;
      continue;
    }
    if (ch === '"') {
      inString = !inString;
      i += 1;
      continue;
    }
    if (inString) {
      i += 1;
      continue;
    }
    if (ch === '{') {
      depth += 1;
    } else if (ch === '}') {
      depth -= 1;
      if (depth === 0) return i + 1;
    }
    i += 1;
  }
  return -1;
}

function tryParseJsonAt(text, start) {
  const end = scanJsonObject(text, start);
  if (end < 0) return null;
  try {
    return JSON.parse(text.slice(start, end));
  } catch {
    return null;
  }
}

function findEndOfJson(text, start) {
  const end = scanJsonObject(text, start);
  if (end < 0) return text.length + 1;
  return end;
}

// Port of parse_text_file. Returns id-bearing JSON blocks plus prose/skip flags.
// The brace-stripping regex below is deliberately NOT unified with the balanced-brace
// scanner above: stripping uses the LOOSER one-level-nested pattern (the Python
// `re.DOTALL` flag is a no-op there because [^{}] already matches newlines).
function parseTextFile(text, agent) {
  const findings = [];
  const warnings = [];
  let hasProse = false;
  let hasSkip = false;

  if (text === undefined || text === null) return { findings, warnings, hasProse, hasSkip };
  if (text.trim() === '') return { findings, warnings, hasProse, hasSkip };

  if (/^\s*SKIP\s*:/im.test(text)) hasSkip = true;

  for (const obj of extractJsonBlocks(text)) {
    if ('id' in obj) findings.push(obj);
  }

  let stripped = text.replace(/\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}/g, '');
  stripped = stripped.replace(/^\s*SKIP\s*:.*$/gim, '');
  stripped = stripped.trim();
  // .length counts UTF-16 units where Python len() counts code points, so an astral
  // char shifts this threshold by one vs Python. Accepted: has_prose is diagnostics
  // only (truncation heuristic), and parity fixtures keep prose ASCII where it is load-bearing.
  if (stripped.replace(/\s+/g, '').length > 20) hasProse = true;

  return { findings, warnings, hasProse, hasSkip };
}

// --- Agent field injection --------------------------------------------------

// Port of the per-list slice of inject_agent_field: sets f.agent on each finding.
// The pipeline calls this text-first then ndjson-second (matching the Python
// ordering), though the two channels hold distinct objects so no real overwrite
// occurs.
function injectAgentField(findings, agent) {
  for (const f of findings) f.agent = agent;
}

// --- Validation -------------------------------------------------------------

// Port of validate_findings: reject on the first missing required field (===''
// mirrors Python's `== ""`, which — unlike JS `==` — never coerces 0/false);
// warn-but-keep on a missing or unknown dimension.
function validateFindings(findings) {
  const valid = [];
  const warnings = [];

  for (const f of findings) {
    const fid = 'id' in f ? f.id : '<no id>';
    let reject = false;

    for (const field of REQUIRED_FIELDS) {
      const v = f[field];
      if (!(field in f) || v === null || v === undefined || v === '') {
        warnings.push(`[${fid}] Missing required field '${field}' — finding rejected`);
        reject = true;
        break;
      }
    }

    if (reject) continue;

    const dim = 'dimension' in f ? f.dimension : undefined;
    if (dim === null || dim === undefined) {
      warnings.push(`[${fid}] Missing 'dimension' field — finding kept with warning`);
    } else if (!KNOWN_DIMENSIONS.has(dim)) {
      warnings.push(`[${fid}] Unknown dimension '${dim}' — finding kept with warning`);
    }

    valid.push(f);
  }

  return { valid, warnings };
}

// --- Truncation detection ---------------------------------------------------

// Port of detect_truncation. Reads PRE-validation NDJSON raw counts and
// PRE-validation text findings so validation-rejected findings (M4) and
// text-fallback JSON blocks (M5) do not produce false positives. Iterating the
// ndjsonRaw keys mirrors Python's iteration over `agents` (same set + order,
// since the caller builds ndjsonRaw by iterating agents).
function detectTruncation(ndjsonRaw, textPre, hasProse, hasSkip) {
  const warnings = [];
  for (const agent of Object.keys(ndjsonRaw)) {
    const ndjsonEmpty = (ndjsonRaw[agent] || 0) === 0;
    const textEmpty = (textPre[agent] || []).length === 0;
    const prose = hasProse[agent] || false;
    const skip = hasSkip[agent] || false;
    if (ndjsonEmpty && textEmpty && prose && !skip) {
      warnings.push(
        `[${agent}] Possible truncation: no structured findings, ` +
          'prose present in text output, no SKIP lines detected',
      );
    }
  }
  return warnings;
}

// --- Output assembly --------------------------------------------------------

function assembleOutput(
  findings,
  agents,
  ndjsonCount,
  textFallbackCount,
  duplicatesResolved,
  droppedNoId,
  truncationWarnings,
  validationWarnings,
  baseBranch,
  headSha,
  prNumber,
  owner,
  repo,
) {
  return {
    findings,
    base_branch: baseBranch,
    head_sha: headSha,
    pr_number: prNumber,
    owner,
    repo,
    methodology: {
      agents_dispatched: agents,
      findings_per_channel: {
        ndjson: ndjsonCount,
        text_fallback: textFallbackCount,
      },
      duplicates_resolved: duplicatesResolved,
      dropped_no_id: droppedNoId,
      truncation_warnings: truncationWarnings,
      validation_warnings: validationWarnings,
    },
  };
}

// --- Main merge pipeline ----------------------------------------------------

// Port of merge(). `ndjsonContents`/`textContents` are {agent: rawFileString};
// `meta` = {base_branch, head_sha, pr_number, owner, repo, agents}. Runs the
// sub-functions in the Python main() order and returns the Phase 4 envelope.
function merge(ndjsonContents, textContents, meta) {
  const M = typeof meta === 'string' ? JSON.parse(meta) : meta;
  const agents = M.agents;
  const nd = ndjsonContents || {};
  const tx = textContents || {};
  const allWarnings = [];

  // Channel 1: NDJSON.
  const ndjsonFindings = {};
  for (const agent of agents) {
    const { findings, warnings } = parseNdjson(nd[agent], agent);
    ndjsonFindings[agent] = findings;
    for (const w of warnings) allWarnings.push(w);
  }

  // Channel 2: text fallback.
  const textFindings = {};
  const textHasProse = {};
  const textHasSkip = {};
  for (const agent of agents) {
    const { findings, warnings, hasProse, hasSkip } = parseTextFile(tx[agent], agent);
    textFindings[agent] = findings;
    textHasProse[agent] = hasProse;
    textHasSkip[agent] = hasSkip;
    for (const w of warnings) allWarnings.push(w);
  }

  // Pre-validation raw counts (for truncation detection only).
  const ndjsonRawCounts = {};
  for (const agent of Object.keys(ndjsonFindings)) ndjsonRawCounts[agent] = ndjsonFindings[agent].length;

  // Inject agent fields (text first, ndjson second — matches Python ordering).
  for (const [agent, findings] of Object.entries(textFindings)) injectAgentField(findings, agent);
  for (const [agent, findings] of Object.entries(ndjsonFindings)) injectAgentField(findings, agent);

  // Validate the combined flat list (pre-dedup) so warnings cover all raw findings.
  const allNdjsonFlat = Object.values(ndjsonFindings).flat();
  const allTextFlat = Object.values(textFindings).flat();
  const { warnings: preValWarnings } = validateFindings(allNdjsonFlat.concat(allTextFlat));

  // Real dropped_no_id: PRE-validation, per-occurrence (id-less findings are
  // stripped before dedup, so the production count must come from here). Matches
  // Python's `f.get("id") in (None, "")` — absent, null, or empty-string id.
  let droppedNoId = 0;
  for (const f of allNdjsonFlat.concat(allTextFlat)) {
    const fid = f.id;
    if (fid === undefined || fid === null || fid === '') droppedNoId += 1;
  }

  // Filter each channel to only valid findings.
  const filterValid = (dict) => {
    const out = {};
    for (const [agent, findings] of Object.entries(dict)) {
      out[agent] = validateFindings(findings).valid;
    }
    return out;
  };

  const ndjsonValid = filterValid(ndjsonFindings);
  // Snapshot pre-validation text findings for truncation detection before filtering.
  const textFindingsPreValidation = {};
  for (const [agent, findings] of Object.entries(textFindings)) textFindingsPreValidation[agent] = findings.slice();
  const textValid = filterValid(textFindings);

  // Deduplicate (NDJSON wins on id collision). dedup's own dropped_no_id is 0
  // here because filterValid already removed id-less findings.
  const { merged, duplicatesResolved } = dedupById(ndjsonValid, textValid);

  // Channel counts: both post-validation, post-dedup, via the ndjson-source id set.
  const ndjsonIds = new Set();
  for (const findings of Object.values(ndjsonValid)) {
    for (const f of findings) if ('id' in f) ndjsonIds.add(f.id);
  }
  let ndjsonCount = 0;
  let textFallbackCount = 0;
  for (const f of merged) {
    if (ndjsonIds.has(f.id)) ndjsonCount += 1;
    else textFallbackCount += 1;
  }

  // Truncation detection uses pre-validation counts + pre-validation text findings.
  const truncationWarnings = detectTruncation(
    ndjsonRawCounts,
    textFindingsPreValidation,
    textHasProse,
    textHasSkip,
  );

  const validationWarnings = allWarnings.concat(preValWarnings);

  return assembleOutput(
    merged,
    agents,
    ndjsonCount,
    textFallbackCount,
    duplicatesResolved,
    droppedNoId,
    truncationWarnings,
    validationWarnings,
    M.base_branch,
    M.head_sha,
    M.pr_number,
    M.owner,
    M.repo,
  );
}

// --- applyValidations.js ---
// applyValidations.js — JS twin of scripts/apply_validations.py:154-226
// (apply_validations). Merges validator confidence adjustments into a list
// of findings in place: matches by id, clamps confidence to [0, 100], sets
// original_confidence once (first validation only), and copies a truthy
// justification plus a known reachability classification.

// Replicate Python int(): accepts a JS number (truncate toward zero, matching
// Python's int(float) truncation direction -- confirmed against the running
// interpreter: int(72.9) == 72, int(-0.5) == 0), an integer-valued decimal
// string (Python strips surrounding whitespace and accepts a leading sign --
// int(" 72 ") == int("+72") == 72), or a JS boolean (Python's bool is an int
// subclass, so int(True) == 1 and int(False) == 0 -- verified against the
// running interpreter; apply_validations.py:196-204 calls int() with no type
// gate, so a validator emitting `"confidence": true` is applied as 1 in
// Python and must be too here). REJECTS decimal strings like "72.9" and
// non-numeric strings (Python int("72.9") / int("abc") / int("") all raise
// ValueError). Returns null on reject; the caller skips the validation entry,
// mirroring Python's `except (TypeError, ValueError): ... continue`.
function pyIntStrict(v) {
  if (typeof v === 'boolean') return v ? 1 : 0;
  if (typeof v === 'number') return Number.isFinite(v) ? Math.trunc(v) : null;
  if (typeof v === 'string') {
    const s = v.trim();
    if (/^[+-]?\d+$/.test(s)) return parseInt(s, 10); // int-string only
    return null; // "72.9", "abc", "" all rejected
  }
  return null; // None/object -> skip (int(None) raises TypeError in Python;
  // a plain object has no int() coercion path either).
}

const REACHABILITY_VALUES = ['current', 'future_change_only', 'uncertain'];

function applyValidations(findings, validations) {
  // Build id -> finding index for O(n) lookup (matches Python's finding_by_id).
  const findingById = new Map();
  for (const finding of findings) {
    const fid = 'id' in finding ? finding.id : undefined;
    if (fid !== null && fid !== undefined) findingById.set(fid, finding);
  }

  let adjustedCount = 0;
  const unmatchedIds = [];

  for (const validation of validations) {
    const vid = 'id' in validation ? validation.id : undefined;
    if (vid === null || vid === undefined) continue; // missing id -- skipped (warning)

    const rawConf = 'confidence' in validation ? validation.confidence : undefined;
    if (rawConf === null || rawConf === undefined) continue; // missing confidence -- skipped (warning)

    const parsed = pyIntStrict(rawConf);
    if (parsed === null) continue; // non-integer confidence -- skipped (warning)

    const newConf = Math.max(0, Math.min(100, parsed));

    const finding = findingById.get(vid);
    if (finding === undefined) {
      unmatchedIds.push(vid);
      continue;
    }

    // Save original_confidence before updating (only on first validation).
    if (!('original_confidence' in finding)) {
      finding.original_confidence = 'confidence' in finding ? finding.confidence : 0;
    }
    finding.validator_confidence = newConf;
    finding.confidence = newConf;

    const justification = 'justification' in validation ? validation.justification : undefined;
    if (justification) finding.validation_justification = justification;
    const reachability = 'reachability' in validation ? validation.reachability : undefined;
    if (REACHABILITY_VALUES.includes(reachability)) finding.reachability = reachability;

    adjustedCount += 1;
  }

  return { adjustedCount, unmatchedIds };
}

// --- applyChallenges.js ---
// applyChallenges.js — JS twin of scripts/apply_challenges.py:94-398 (Phase
// 7->8 bridge). Applies blind-challenge scores to Phase 6 findings, re-runs
// cross-agent dedup, ranks the final set. File I/O (load_filtered/
// load_challenges) and CLI argparse/stdout wiring stay in the SKILL/stage
// layer -- not ported here, matching filterFindings.js's applyFilterPipeline
// (config/exclusions passed in already-parsed, no disk access).


// SEVERITY_ORDER is imported from filterFindings.js (its single owner) — see the
// note there. A second top-level `const SEVERITY_ORDER` here collided in the
// concatenated bundle after build.js strips the `export` keyword.

// Deep clone via JSON round-trip. The workflow runtime sandbox does NOT provide
// structuredClone (a node/browser global, absent here — it crashed the live smoke
// run at the call site below). Findings are JSON-safe by construction (strings,
// numbers, booleans, null, plain arrays/objects — no Date/Map/Set/undefined/
// functions), so a JSON round-trip is a faithful deep copy. See CLAUDE.md
// (Workflow runtime section — only JSON-safe globals are guaranteed here).
function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

// Port of _downgrade_severity: "critical" -> "high" -> "medium" -> "low" ->
// null. Non-string input (Python's severity.lower() raising AttributeError
// on a non-str) and unknown severities both fall through to null, exactly
// like Python's `except (ValueError, AttributeError): return None`.
function downgradeSeverity(severity) {
  const idx = typeof severity === 'string' ? SEVERITY_ORDER.indexOf(severity.toLowerCase()) : -1;
  if (idx < 0 || idx + 1 >= SEVERITY_ORDER.length) return null;
  return SEVERITY_ORDER[idx + 1];
}

// Port of _rank_key. 4-tuple (sevIdx, degraded, -confidence, tertiary):
// tertiary is -risk_level when risk_level is present, non-null, and
// numeric (Number.isFinite(Number(rl))) -- the explicit `rl !== null` guard
// matters because Number(null) === 0 is finite, which would otherwise
// silently treat an explicit `risk_level: null` as risk_level 0 instead of
// falling back to -description.length (see the
// rank_risk_level_absent_falls_back_to_description_length fixture, which
// pins this exact null-vs-zero distinction against the authoritative
// Python: `if risk_level is not None: ... else: tertiary = -len(description)`).
//
// `degraded` (origin === 'unknown' -> 1, else 0) sits right after severity
// (#22 D3b): within a severity tier, a finding the pipeline actually
// verified always outranks one it could not verify. On a UNIFORM-origin run
// (every finding verified, or every finding degraded) this component is
// constant across the whole set, so ranking order is unchanged from before
// this extension.
function rankKey(finding) {
  const sev = (finding.severity ?? 'low').toLowerCase();
  let sevIdx = SEVERITY_ORDER.indexOf(sev);
  if (sevIdx < 0) sevIdx = SEVERITY_ORDER.length;
  const degraded = finding.origin === 'unknown' ? 1 : 0;
  const conf = finding.confidence ?? 0;
  let tertiary;
  const rl = finding.risk_level;
  if (rl !== undefined && rl !== null && Number.isFinite(Number(rl))) tertiary = -Number(rl);
  else tertiary = -((finding.description ?? '').length);
  return [sevIdx, degraded, -conf, tertiary];
}

// Port of rank_findings. ONE composite comparator built from rankKey's
// 4-tuple -- not chained `.sort()` calls -- so severity, verification
// status, confidence, and risk_level/description-length are decided
// together in a single stable pass (see the
// rank_by_severity_then_confidence_then_risk_level fixture).
function rankFindings(findings) {
  return [...findings].sort((a, b) => {
    const ka = rankKey(a);
    const kb = rankKey(b);
    return ka[0] - kb[0] || ka[1] - kb[1] || ka[2] - kb[2] || ka[3] - kb[3];
  });
}

// Port of apply_challenges (scripts/apply_challenges.py:219-391) plus the
// dedup-rerun + rank composition from main() (:449-480). Bridges Phase 6
// output through blind-challenge thresholds:
//   score < 25   non-security -> remove; security -> downgrade (already
//                "low" -> remove)
//   score 25-49  downgrade one step + re-route to suggestion; already
//                "low" -> remove with eliminated_by="challenge:downgraded"
//   score 50-74  contest (kept); origin="surfaced" -> re-route to suggestion
//   score >= 75  survive unchanged
// Findings with no matching challenge entry pass through untouched (by
// reference -- not cloned, mirroring Python's aliasing of unmatched dict
// objects). Findings WITH a matching entry are deep-cloned (deepClone, a
// JSON round-trip) before any mutation, so the caller's input array/objects
// are never mutated (see the deep_copy_no_mutation_of_input fixture).
function applyChallenges(findings, challenges) {
  // Build id -> challenge entry map (O(n) lookup). An entry is registered
  // only when it has both a truthy id and an int-coercible score -- matches
  // Python's challenge_by_id build loop, which `continue`s (silently, past
  // a stderr warning not reproduced here) on either failure.
  const challengeById = new Map();
  for (const entry of challenges) {
    const cid = 'id' in entry ? entry.id : undefined;
    if (cid === undefined || cid === null) continue;
    const rawScore = 'score' in entry ? entry.score : undefined;
    if (rawScore === undefined || rawScore === null) continue;
    if (pyIntStrict(rawScore) === null) continue;
    challengeById.set(cid, entry);
  }

  const active = [];
  const eliminated = [];
  const stats = {
    challenge_removed: 0,
    challenge_downgraded: 0,
    challenge_contested: 0,
    challenge_survived: 0,
    unchallenged: 0,
  };

  for (let finding of findings) {
    const fid = 'id' in finding ? finding.id : undefined;
    const entry = challengeById.get(fid);

    if (entry === undefined) {
      // No challenge result -- pass through unchanged (no clone: matches
      // Python's aliasing of the original dict when no entry matches).
      stats.unchallenged += 1;
      active.push(finding);
      continue;
    }

    // Re-derive score from the entry (mirrors Python's second `int()` call
    // at apply time; guaranteed to succeed since the map-build loop above
    // already validated int-coercibility for this same entry).
    const rawScore = 'score' in entry ? entry.score : 0;
    const score = pyIntStrict(rawScore);
    const justification = 'justification' in entry ? entry.justification : undefined;

    // Deep-clone before mutation -- no aliasing of the caller's finding.
    finding = deepClone(finding);
    finding.challenge_score = score;
    if (justification) finding.challenge_justification = justification;

    const isSurfaced = ('origin' in finding ? finding.origin : '').toLowerCase() === 'surfaced';
    const isSecurity = ('dimension' in finding ? finding.dimension : '').toLowerCase() === 'security';

    if (score < 25) {
      if (isSecurity) {
        const currentSev = ('severity' in finding ? finding.severity : 'low').toLowerCase();
        const newSev = downgradeSeverity(currentSev);
        finding.challenge_contested = false;
        if (newSev === null) {
          eliminated.push({
            ...finding,
            eliminated_by: 'challenge:removed',
            elimination_reason:
              `challenge score ${score} < 25; security finding severity already ` +
              `'${currentSev}' (lowest) — finding removed`,
          });
          stats.challenge_removed += 1;
        } else {
          finding.severity = newSev;
          finding.severity_downgraded = true;
          finding.original_severity = currentSev;
          finding.report_destination = 'suggestion';
          finding.report_tag = 'suggestion';
          active.push(finding);
          stats.challenge_downgraded += 1;
        }
      } else {
        // Hard remove for non-security findings. NOTE: challenge_contested
        // is intentionally never set on this branch's finding -- Python
        // never sets it here either (only the security sub-branch above and
        // the 25-49/50-74/>=75 branches below set it).
        eliminated.push({
          ...finding,
          eliminated_by: 'challenge:removed',
          elimination_reason: `challenge score ${score} < 25; finding does not survive blind challenge`,
        });
        stats.challenge_removed += 1;
      }
    } else if (score < 50) {
      const currentSev = ('severity' in finding ? finding.severity : 'low').toLowerCase();
      const newSev = downgradeSeverity(currentSev);
      finding.challenge_contested = false;
      if (newSev === null) {
        eliminated.push({
          ...finding,
          eliminated_by: 'challenge:downgraded',
          elimination_reason:
            `challenge score ${score} in 25-49 range; severity already ` +
            `'${currentSev}' (lowest) — finding removed`,
        });
        stats.challenge_downgraded += 1;
      } else {
        finding.severity = newSev;
        finding.severity_downgraded = true;
        finding.original_severity = currentSev;
        finding.report_destination = 'suggestion';
        finding.report_tag = 'suggestion';
        active.push(finding);
        stats.challenge_downgraded += 1;
      }
    } else if (score < 75) {
      finding.challenge_contested = true;
      if (isSurfaced) {
        finding.report_destination = 'suggestion';
        finding.report_tag = 'suggestion';
      }
      active.push(finding);
      stats.challenge_contested += 1;
    } else {
      finding.challenge_contested = false;
      active.push(finding);
      stats.challenge_survived += 1;
    }
  }

  const totalInput = findings.length;

  // Cross-agent consolidation re-run (filterFindings' consolidateCrossAgent,
  // reused not reimplemented) + rank -- mirrors main()'s post-challenge
  // composition. Nothing is dropped here (#22 D1); it re-stamps the
  // surviving active set now that challenge scoring may have changed which
  // findings are co-located and eligible.
  const { findings: consolidatedActive, consolidatedCount } = consolidateCrossAgent(active);
  const ranked = rankFindings(consolidatedActive);

  return {
    findings: ranked,
    eliminated,
    stats: {
      total_input: totalInput,
      challenge_removed: stats.challenge_removed,
      challenge_downgraded: stats.challenge_downgraded,
      challenge_contested: stats.challenge_contested,
      challenge_survived: stats.challenge_survived,
      unchallenged: stats.unchallenged,
      cross_agent_consolidated: consolidatedCount,
      final_count: ranked.length,
    },
  };
}

// --- registry.js ---
// registry.js — single point of extension. Adding a dimension = one entry here + one agent .md.
//
// `promptExtra` is an optional per-agent prompt-extension string appended verbatim to that
// agent's discoverPrompt (see stages.js). It is scoped by agentType, not by dimension —
// every DIMENSIONS row for a multi-dimension agent (conventions-and-intent) must carry the
// SAME value (agentSpecs() unions them; a mismatch would make the dispatched prompt depend
// on dimension iteration order). Hill-climb iter 5 uses it for two discovery-breadth
// sweeps grounded in the subset diagnosis (~21 never-discovered goldens): a security sweep
// on security-reviewer, and a typo/naming sweep on bug-detector and conventions-and-intent.
const SECURITY_SWEEP_PROMPT_EXTRA = 'Additionally sweep explicitly for: SSRF and unvalidated-URL fetches (user-influenced URLs reaching http/request/fetch clients without allowlist validation); frame and embedding policy gaps (missing X-Frame-Options or frame-ancestors, clickjacking exposure); postMessage handlers that do not validate event.origin or check it with weak substring matching; and string-matching bypass patterns where a security decision uses containment checks (indexOf/includes/startsWith/contains) on a host, origin, path, or scheme instead of exact parsing — these are bypassable (e.g. a host "evil.com/trusted.com" still contains "trusted.com").';
const TYPO_NAMING_SWEEP_PROMPT_EXTRA = 'Additionally run an explicit typo and naming sweep: identifier misspellings; typos in user-facing strings, messages, and log output; case-sensitivity mistakes in string comparisons (comparing mixed-case values without normalizing case); and copy-paste plural/singular or off-by-one naming mismatches (a field, key, or variable named for one thing but holding another).';

// `conditionalFlag` is the SCOPE-GATING key for a dimension (consumed by agentActive in
// stages.js). Semantics are OPT-OUT, never opt-in, so the default full-scope run is
// unchanged when the caller stamps no flags:
//   - null   => UNGATEABLE. The dimension is always on and cannot be disabled by any
//               agentFlags entry. The two CORE dimensions (bug, security) carry null so a
//               light-scope run always still includes them ("bugs+security only").
//   - 'name' => gated on agentFlags['name']. agentActive treats a MISSING key or any value
//               other than the literal `false` as ON — so absent/empty agentFlags leaves
//               every gated dimension enabled (byte-identical to the pre-flag behavior).
//               A light-scope run disables the dimension by stamping agentFlags['name'] = false.
// The seven extended dimensions share the single 'deep' flag: light scope stamps
// { deep: false } to drop them, full scope stamps {} (or omits the key) to keep them.
// Finer scopes later = introduce additional flag tokens here; no agentActive change needed.
const DEEP = 'deep';

// --- The canonical finding schema ------------------------------------------
//
// FINDING_PROP_TYPES + FINDING_REQUIRED + each DIMENSIONS row's `schemaExtra` are, together,
// the WHOLE declaration of what a finding may carry. They live in this one file on purpose
// (issue #47): the canonical half used to sit in stages.js, the per-dimension half here, and
// `cross_file_refs` was a third hardcoded special case inside findingItemSchema — three places
// to add a finding field, which is how `suggestion`/`claude_md_rule` (instructed by all 7
// discovery contracts) and `spec_text`/`criticality`/`failure_scenario` (one contract each)
// went years declared by no schema and silently dropped at the StructuredOutput boundary.
// Adding a finding field is now ONE entry here plus the owning agent's .md output contract,
// and tests/test_dimensions_registry.py fails the build when those two drift apart.
//
// A value is EITHER a type-name shorthand string ('string'/'number', expanded by
// findingItemSchema to { type: <name> }) OR a full JSON-Schema fragment used verbatim — which
// is how array-valued fields (cross_file_refs, cross_file_impact's affected_consumers) are
// declared, since the platform's schema validator requires `items` on an array.
//
// `origin` is the one canonical field NO agent emits: verify_findings.py stamps it during
// blame classification. Everything else here must appear in every discovery contract's output
// block, and the lockstep test asserts exactly that (declared − instructed == {origin}).
const FINDING_PROP_TYPES = {
  // confidence is a NUMBER end-to-end: agents emit a numeric 0-100 score per their .md
  // contracts, so declaring it `number` here makes StructuredOutput return the number at
  // EVERY by-value boundary (discovery included) — the string form "85" the schema used to
  // declare simply never exists, so the filter's consensus `+` boost can never
  // string-concatenate ("85"+10 -> "8510"). pinNumericFields stays as defense-in-depth for
  // legacy/checkpoint-resume findings that predate this pin.
  id: 'string', file: 'string', line_start: 'number', line_end: 'number',
  title: 'string', description: 'string', severity: 'string', confidence: 'number',
  dimension: 'string', origin: 'string', evidence: 'string',
  // Instructed by all 7 discovery contracts, declared by none of them until issue #47.
  // `suggestion` is the prose fix advice report-format.md renders and post_review.py posts;
  // `claude_md_rule` is the cited project rule that justifies a finding (REQUIRED non-null
  // for convention findings per agents/conventions-and-intent.md — prompt-enforced, see the
  // FINDING_REQUIRED note below). Both are OPTIONAL here and NOT nullable: a not-applicable
  // value must be OMITTED, never emitted as null (see the nullability note under DIMENSIONS).
  suggestion: 'string', claude_md_rule: 'string',
  // Instructed by all 7 discovery contracts (issue #63). OPTIONAL and NOT nullable, same
  // OMIT-not-null discipline as suggestion/claude_md_rule above: a not-applicable value is
  // omitted, never null. Declaring it here is only half the story — delivery
  // (scripts/post_review.py) runs a deterministic apply-check before ever rendering it as a
  // committable ```suggestion fence, and downgrades to the prose `suggestion` on any failure
  // (non-string, stale/no-op, wrong range, wrong anchor, oversized, ...). A finding surviving
  // to delivery with this field set is not a guarantee the fence ships. The pipeline also
  // excludes the field itself through reportExtraFields in renderReport.js, so delivery
  // is the only surface it is ever rendered on. The read-only
  // report-side apply-check (scripts/report_patches.py) renders the KEPT patches into a
  // sibling artifact instead — see report-format.md.
  suggested_fix_code: 'string',
  cross_file_refs: { type: 'array', items: { type: 'string' } },
};

// FINDING_REQUIRED stays the flat canonical list shared by every dispatch schema — it names
// only fields every dimension emits, so it can never itself carry a single-dimension name.
// Per-dimension requirements live one level down, on each DIMENSIONS row's `requiredExtra`
// (issue #66): agentSpecs() intersects across a multi-dimension agent's rows, so a field
// required for only ONE dimension of a shared dispatch (conventions-and-intent mixes
// convention/intent/comment_accuracy in one schema) can never be enforced there — union
// semantics would force fabrication on the sibling dimensions. A TOP-LEVEL
// `oneOf`/`allOf`/`anyOf` in input_schema is rejected outright (API 400, measured
// 2026-08-18); `if`/`then` nested inside `items` was accepted AND enforced by the retry loop
// in that same measurement, but only on the first-party API — unmeasured on
// Bedrock/Vertex/Foundry, so requiredExtra sticks to the provider-portable flat `required`
// list only. So the promotion rule for requiredExtra is narrow: only a field whose owning
// contract emits it UNCONDITIONALLY (no "OMIT this field" branch) may be listed there; a
// genuinely conditional field (hidden_errors, invalid_state_example) stays contract-enforced
// everywhere, the same retry-storm-avoidance class the OMIT-not-null rule already governs.
// claude_md_rule and spec_text are a THIRD case — conditional across dimensions but
// unconditional WITHIN their own dimension — and go through `requiredWhenDimension` below,
// which does spend the measured nested if/then construct, gated behind
// conditionalSchemaActive so it never reaches an unmeasured provider.
const FINDING_REQUIRED = ['id', 'file', 'line_start', 'title', 'description', 'severity', 'confidence', 'dimension'];

// `schemaExtra` declares the per-dimension finding fields BEYOND the canonical schema above —
// the extras each agent's .md output contract actually emits (findingItemSchema in stages.js
// unions them onto that agent's discovery item schema — the only boundary that carries finding
// items by value; the verify executor echoes per-id deltas, never findings). Each row MUST
// match its contract (agents/<agent>.md output block): the item schema is CLOSED
// (`additionalProperties: false`), so an extra a contract instructs but no row declares is
// rejected at dispatch and costs a schema retry: bug -> hidden_errors,
// security -> attack_vector, cross_file_impact -> affected_consumers (ARRAY), intent ->
// spec_text, test_coverage -> criticality (NUMBER, a 1-10 impact scale distinct from
// confidence's 0-100 certainty) + failure_scenario, type_design -> invalid_state_example,
// simplification -> behavior_preserved. The pre-reconciliation declarations (type_design
// encapsulation/invariants/enforcement/usefulness; simplification before/after) named fields
// no agent ever emitted top-level and no code consumes — pure schema noise now removed.
// Extras are optional by default — a row promotes one to dispatch-required only through
// `requiredExtra` below, never by touching FINDING_REQUIRED — and NOT nullable: the
// platform schema contract pins `type` to a single string (no union types), so a
// not-applicable extra must be OMITTED, never emitted as null — the agent contracts say
// "OMIT this field", and a null here is the same retry-storm class as string confidence.
// A multi-dimension agent (conventions-and-intent) dispatches ONCE with the UNION of its
// rows' extras (agentSpecs in stages.js), so scoping spec_text to the `intent` row still
// makes it declarable on that agent's convention and comment_accuracy findings — the
// per-dimension scoping is documentation of ownership, not an emission restriction.
//
// `requiredExtra` (issue #66) names the subset of a row's OWN `schemaExtra` — never a
// canonical FINDING_PROP_TYPES field — that dimension's owning contract emits UNCONDITIONALLY —
// no OMIT branch — so the schema can safely require them without ever rejecting a compliant
// finding. Narrowed to schemaExtra deliberately: a canonical field, by definition, is one every
// dimension emits unconditionally already, so its unconditional-ness belongs in
// FINDING_REQUIRED directly, not re-declared piecemeal on a row-by-row requiredExtra — a
// canonical promotion routed through here would be documented nowhere the Canonical fields
// table's Required-column lockstep test looks. Populated by a full audit of
// the seven contracts: security -> attack_vector, cross_file_impact -> affected_consumers,
// test_coverage -> criticality + failure_scenario, simplification -> behavior_preserved. Every
// other row is `[]`: bug's hidden_errors, conventions-and-intent's claude_md_rule/spec_text,
// and type_design's invalid_state_example all carry an explicit OMIT branch in their contract
// (conventions-and-intent additionally can't promote a single-dimension field at all — see the
// agentSpecs comment in stages.js), so they stay contract-enforced. findingItemSchema
// (stages.js) appends a spec's effective requiredExtra onto FINDING_REQUIRED per dispatch.
// `requiredWhenDimension` (issue #218) names fields the owning contract emits
// UNCONDITIONALLY within THIS row's dimension while every sibling dimension on the same
// agentType is told to OMIT them — the exact shape `requiredExtra` cannot hold (its
// sibling-parity guard demands every row of an agentType agree, and its intersection would
// either force every sibling to fabricate the field or silently drop it). Each entry is
// EITHER a key of this row's OWN schemaExtra (spec_text on the intent row) OR a canonical
// FINDING_PROP_TYPES field that is not in FINDING_REQUIRED (claude_md_rule on the convention
// row) — never a canonical field already unconditional everywhere, which belongs in
// FINDING_REQUIRED directly. `[]` on every other row.
//
// Unlike requiredExtra this cannot become a flat `required` entry on the dispatch schema: a
// TOP-LEVEL oneOf/allOf/anyOf in input_schema is rejected outright (API 400, measured
// 2026-08-18), but the same if/then nested inside `items` was accepted AND enforced on that
// same measurement — first-party only, unmeasured on Bedrock/Vertex/Foundry. So
// findingItemSchema (stages.js) emits the nested allOf/if/then construct ONLY when
// conditionalSchemaActive(policy) is true (first-party-direct, no gateway) — third-party
// providers and gateway sessions keep today's flat schema, contract prose is the floor
// everywhere. See agentSpecs' conditionalRequired derivation in stages.js.
const DIMENSIONS = [
  { dimension: 'bug', agentType: 'code-gauntlet:bug-detector', conditionalFlag: null, schemaExtra: { hidden_errors: 'string' }, requiredExtra: [], requiredWhenDimension: [], modelOverride: null, promptExtra: TYPO_NAMING_SWEEP_PROMPT_EXTRA },
  { dimension: 'security', agentType: 'code-gauntlet:security-reviewer', conditionalFlag: null, schemaExtra: { attack_vector: 'string' }, requiredExtra: ['attack_vector'], requiredWhenDimension: [], modelOverride: 'opus', promptExtra: SECURITY_SWEEP_PROMPT_EXTRA },
  { dimension: 'cross_file_impact', agentType: 'code-gauntlet:cross-file-impact', conditionalFlag: DEEP,
    schemaExtra: { affected_consumers: { type: 'array', items: { type: 'string' } } }, requiredExtra: ['affected_consumers'], requiredWhenDimension: [], modelOverride: null, promptExtra: null },
  { dimension: 'test_coverage', agentType: 'code-gauntlet:test-analyzer', conditionalFlag: DEEP,
    // criticality is a 1-10 IMPACT scale (agents/test-analyzer.md); bound it in the schema
    // fragment so StructuredOutput rejects 0/-5/999 the same way items is required on arrays.
    // confidence stays unbound here and is clamped later — validators adjust it at runtime.
    schemaExtra: { criticality: { type: 'number', minimum: 1, maximum: 10 }, failure_scenario: 'string' },
    requiredExtra: ['criticality', 'failure_scenario'], requiredWhenDimension: [], modelOverride: null, promptExtra: null },
  { dimension: 'convention', agentType: 'code-gauntlet:conventions-and-intent', conditionalFlag: DEEP, schemaExtra: {}, requiredExtra: [], requiredWhenDimension: ['claude_md_rule'], modelOverride: null, promptExtra: TYPO_NAMING_SWEEP_PROMPT_EXTRA },
  { dimension: 'intent', agentType: 'code-gauntlet:conventions-and-intent', conditionalFlag: DEEP,
    schemaExtra: { spec_text: 'string' }, requiredExtra: [], requiredWhenDimension: ['spec_text'], modelOverride: null, promptExtra: TYPO_NAMING_SWEEP_PROMPT_EXTRA },
  { dimension: 'comment_accuracy', agentType: 'code-gauntlet:conventions-and-intent', conditionalFlag: DEEP, schemaExtra: {}, requiredExtra: [], requiredWhenDimension: [], modelOverride: null, promptExtra: TYPO_NAMING_SWEEP_PROMPT_EXTRA },
  { dimension: 'type_design', agentType: 'code-gauntlet:type-design-analyzer', conditionalFlag: DEEP,
    schemaExtra: { invalid_state_example: 'string' }, requiredExtra: [], requiredWhenDimension: [], modelOverride: null, promptExtra: null },
  { dimension: 'simplification', agentType: 'code-gauntlet:code-simplifier', conditionalFlag: DEEP,
    schemaExtra: { behavior_preserved: 'string' }, requiredExtra: ['behavior_preserved'], requiredWhenDimension: [], modelOverride: null, promptExtra: null },
];

const AGENTS = [...new Set(DIMENSIONS.map((d) => d.agentType))];

// Per-agent display label for the Review Dimensions Summary table (issue #89):
// dimensionsSummaryTable (renderReport.js) renders ONE row per discovery agent — a
// multi-dimension agent (conventions-and-intent) gets a single label for its whole
// aggregated row, not one per dimension — so this is keyed by agentType directly
// rather than living on DIMENSIONS rows, which would force every one of a
// multi-dimension agent's rows to repeat the identical value (the trap promptExtra's
// comment above already documents for a genuinely per-agent value). This map is the
// single source of truth for the display strings — the renderer appends the table as
// the report's last section. Extending: one
// entry here when AGENTS gains a member — registry.test.js pins the key set to AGENTS.
const AGENT_LABELS = {
  'code-gauntlet:bug-detector': 'Correctness & Error Handling',
  'code-gauntlet:security-reviewer': 'Security',
  'code-gauntlet:cross-file-impact': 'Cross-file Impact',
  'code-gauntlet:test-analyzer': 'Test Coverage',
  'code-gauntlet:conventions-and-intent': 'Conventions & Intent',
  'code-gauntlet:type-design-analyzer': 'Type Design',
  'code-gauntlet:code-simplifier': 'Code Simplification',
};

// --- Product identity -------------------------------------------------------
// The ONE hand-authored copy of the brand mark, the display name, and the severity
// emoji map. Every other copy is GENERATED from here by
// scripts/generate_contract_requirements.py (--check in CI): the Python mirror in
// scripts/post_review.py and the legends in references/report-format.md and
// references/delivery-guide.md. Do not hand-edit a mirror.
//
// PRODUCT ("code-gauntlet", scripts/review_marker.py:89) is deliberately NOT here and is
// NOT a mirror of BRAND_NAME: that is a machine-parsed wire slug pinned by
// docs/machine-parsed-strings.md; this is presentation. A product rename moves both,
// separately, on purpose.
const BRAND_MARK = '\u2694\uFE0F';   // CROSSED SWORDS U+2694 + VS16 U+FE0F
const BRAND_NAME = 'Code Gauntlet';
const SEVERITY_EMOJI = {
  critical: '\u{1F534}', high: '\u{1F7E0}', medium: '\u{1F7E1}', low: '\u{1F4A1}',
};
// The mark rendered for a severity the schema does not forbid (`severity` is declared
// `string`, not an enum) — a constant, not a repeated literal. Pinned by
// tests/test_post_review.py::test_unknown_severity_falls_back_to_bulb.
const SEVERITY_EMOJI_FALLBACK = SEVERITY_EMOJI.low;

// The stage agents' models, restating each one's `model:` frontmatter explicitly so a
// dispatch pins a full model ID instead of inheriting the session variant (see MODEL_IDS
// below). No entry currently deviates from its frontmatter, and all four match
// resolvePolicy's own 'sonnet' fallback — this is the one place to change when one should.
// Keys are matched against `agentType.split(':').pop()`, so they must be the FULL
// suffix — 'artifact-writer', not 'artifact' — or the tunable never binds.
const STAGE_DEFAULTS = {
  validator: 'sonnet', challenger: 'sonnet', executor: 'sonnet',
  'artifact-writer': 'sonnet',
};

// Explicit full model IDs. Aliases like 'sonnet' resolve against the SESSION's model
// variant at dispatch time — a child session pinned to 'sonnet[1m]' cascades the [1m]
// variant into every agent whose policy says 'sonnet' (measured: cache reads 15.6M→28.7M,
// zero plain-sonnet rows). Pinning full IDs makes agent pins immune to the orchestrator's
// session model. Model migrations update this one map.
//
// FIRST-PARTY ONLY. These are Anthropic API model names; Bedrock / Vertex / Foundry use
// provider-specific deployment IDs and pass any other string through UNCHECKED to the
// provider, where these names 400 as invalid model identifiers (observed live: a Bedrock
// run degraded all discovery dimensions in 2s). On those providers the bare alias is the
// only provider-portable spelling — the harness resolves 'sonnet'/'opus' through the
// deployment mapping (ANTHROPIC_DEFAULT_*_MODEL). The [1m]-cascade the pin exists to stop
// was measured on first-party variants; on a third-party provider alias resolution is the
// correct behavior, not the bug. So: pin full IDs first-party, emit bare aliases elsewhere.
const MODEL_IDS = { sonnet: 'claude-sonnet-5', opus: 'claude-opus-4-8', haiku: 'claude-haiku-4-5-20251001' };
// policy.provider === 'firstParty' (or absent — older waists predate the field) pins;
// ANY other value emits the alias untouched. Unknown values are deliberately not an error
// here: the alias is the one spelling that resolves on every provider, so alias-through is
// the safe arm, and the waist (args.js) enum-rejects a typo'd provider before dispatch.
const pinsModelIds = (provider) => provider === undefined || provider === null || provider === 'firstParty';
const toModelId = (m, provider) => (pinsModelIds(provider) ? (MODEL_IDS[m] || m) : m);

// conditionalSchemaActive(policy) -> whether the nested allOf/if/then conditional-required
// block (findingItemSchema, stages.js) may ride the conventions-and-intent dispatch (issue
// #218). NOT an alias for pinsModelIds: a gateway (policy.gateway, stamped from
// ANTHROPIC_BASE_URL) still gets the first-party model-ID pin — a gateway proxies the
// Anthropic API and expects standard Claude model names — but forwards input_schema verbatim
// to whatever backend it fronts, so the unmeasured-third-party risk the schema gate exists to
// avoid survives a gateway hop even though the model-pin risk does not. So this predicate
// takes its own compound signal (first-party provider AND no gateway) rather than being read
// off the model-pin predicate alone.
const conditionalSchemaActive = (policy) => {
  const p = policy || {};
  return pinsModelIds(p.provider) && !p.gateway;
};

function resolvePolicy(agentType, opts = {}) {
  if (opts.subagentModelEnv) { // sourced from args.policy.subagentModel by the pipeline dispatch sites (see args.js)
    // The override maps through the same full-ID pin: a bare alias pins the plain full ID
    // (it can no longer inherit the session variant — intended; see headless-mode.md).
    // On a third-party provider it passes through untouched — an explicit deployment ID
    // (us.anthropic.…) is exactly what the operator escaped to this knob for.
    // Override provenance is carried structurally by the run envelope's
    // resolvedPolicy.subagentModel (null = no override), not restated here.
    return { model: toModelId(opts.subagentModelEnv, opts.provider) };
  }
  const dim = DIMENSIONS.find((d) => d.agentType === agentType);
  // Single benchmarked policy: discovery on sonnet with security-reviewer's opus
  // override, stage agents per STAGE_DEFAULTS. Alternate model modes (fable) are
  // roadmap work (issue #17 V3.2) and land behind their own paired measurement.
  const model = toModelId(dim?.modelOverride || STAGE_DEFAULTS[agentType.split(':').pop()] || 'sonnet', opts.provider);
  return { model };
}

// --- renderReport.js ---
// renderReport.js — deterministic report.md renderer (issues #36, #67).
// Keep every import on ONE line: workflows/build.js deliberately rejects imports its
// line-based bundle stripper cannot remove safely.

// Fields the report renderer never emits. suggested_fix_code itself (no apply-check oracle
// exists at report time) plus the two stamps filterFindings.js/filter_findings.py leave
// behind when IT stripped suggested_fix_code earlier in the pipeline
// (suggested_fix_code_removed_by / _removal_reason) are dangling metadata for a field the
// report renderer never sees either way (#220 review). A list, not a single field check, so
// adding a future report-excluded field is a one-line edit here.
const REPORT_EXCLUDED_FIELDS = [
  'suggested_fix_code',
  'suggested_fix_code_removed_by',
  'suggested_fix_code_removal_reason',
];

// dimensionsSummaryTable({ dispatched, degraded, findings, unverified }) -> markdown string
//
// Computes the Review Dimensions Summary table (report-format.md) in CODE, as a pure
// function of pipeline stats, instead of asking a model to classify each dimension
// itself (issue #89). Before this, the table was never rendered at all: report inputs
// did not carry discoverOut.degraded / discoverOut.dispatched. One row per DISCOVERY AGENT (registry AGENTS order), not per
// dimension — a multi-dimension agent (conventions-and-intent) aggregates all of its
// dimensions' findings into one row. Output starts at the header row (no leading
// `## Review Dimensions Summary` heading) — heading placement is the caller's concern.
//
// Row classification (N = high-confidence finding count for the agent, M = unverified
// count, evaluated in this fixed priority order so at most one rule ever fires):
//   1. not dispatched (scope-skipped, e.g. light-scope agentFlags.deep=false) -> Skipped
//   2. degraded (one of its dimensions is in `degraded`) with N+M==0 -> agent never
//      returned usable coverage
//   3. degraded with N+M>0 -> partial coverage
//   4. dispatched, not degraded, N+M==0 -> clean run, genuinely zero findings
//   5. N>0, not degraded -> the normal case; Notes carries a severity breakdown
//   6. N==0, M>0, not degraded -> every finding this agent produced was routed to the
//      unverified/pipeline-degraded bucket
//
// SEVERITY_ORDER is imported from filterFindings.js (its single owner, per that file's
// own note — a second top-level declaration collides at bundle time).

// Findings with a missing/unknown `dimension` are silently excluded from every row's
// count: the discovery contracts pin `dimension` to one of the nine registry names, so
// an unmapped value here is belt-and-braces, never a live path.
function dimensionOwnerMap() {
  const owner = {};
  for (const d of DIMENSIONS) owner[d.dimension] = d.agentType;
  return owner;
}

// "2 high, 1 low" — counted over the agent's HIGH-CONFIDENCE findings only, in a fixed
// severity order (critical, high, medium, low first; any other value the schema does not
// forbid — `severity` is declared `string`, not an enum — trails in first-seen order so
// no finding is silently dropped from the count). Empty string when no finding in the row
// carries a severity value at all. Severity is normalized with the same one-line rule as
// its report heading, so a row cannot be injected into this table.
function severityBreakdown(rowFindings) {
  const counts = new Map();
  for (const f of rowFindings) {
    if (!f || !f.severity) continue;
    const severity = oneLine(f.severity).toLowerCase();
    counts.set(severity, (counts.get(severity) || 0) + 1);
  }
  if (counts.size === 0) return '';
  const known = SEVERITY_ORDER.filter((s) => counts.has(s));
  const rest = [...counts.keys()].filter((s) => !SEVERITY_ORDER.includes(s));
  return [...known, ...rest].map((s) => `${counts.get(s)} ${s}`).join(', ');
}

function dimensionsSummaryTable(input) {
  const inp = input || {};
  const dispatchedSet = new Set((Array.isArray(inp.dispatched) ? inp.dispatched : []).map(reportAsText));
  const degradedSet = new Set((Array.isArray(inp.degraded) ? inp.degraded : []).map(reportAsText));
  const owner = dimensionOwnerMap();

  const byAgent = new Map(AGENTS.map((a) => [a, []]));
  const unverifiedByAgent = new Map(AGENTS.map((a) => [a, []]));
  for (const f of (inp.findings || [])) {
    const agentType = owner[f && f.dimension];
    if (agentType && byAgent.has(agentType)) byAgent.get(agentType).push(f);
  }
  for (const f of (inp.unverified || [])) {
    const agentType = owner[f && f.dimension];
    if (agentType && unverifiedByAgent.has(agentType)) unverifiedByAgent.get(agentType).push(f);
  }

  const rows = AGENTS.map((agentType) => {
    const rowFindings = byAgent.get(agentType);
    const rowUnverified = unverifiedByAgent.get(agentType);
    const n = rowFindings.length;
    const m = rowUnverified.length;
    const dims = DIMENSIONS.filter((d) => d.agentType === agentType).map((d) => d.dimension);
    const isDegraded = dims.some((d) => degradedSet.has(d));
    const isDispatched = dispatchedSet.has(agentType);
    const label = AGENT_LABELS[agentType] || agentType;
    const agentShort = agentType.split(':').pop();

    let findingsCell;
    let notes;
    if (!isDispatched) {
      findingsCell = '—';
      notes = 'Skipped — not dispatched in this run';
    } else if (isDegraded && n + m === 0) {
      findingsCell = '—';
      notes = 'No results — agent did not complete';
    } else if (isDegraded) {
      findingsCell = m > 0 ? `${n} (+${m} unverified)` : `${n}`;
      notes = 'Partial — agent may not have completed';
    } else if (n + m === 0) {
      findingsCell = '0';
      notes = 'Clean — no findings returned';
    } else if (n > 0) {
      findingsCell = m > 0 ? `${n} (+${m} unverified)` : `${n}`;
      notes = severityBreakdown(rowFindings);
    } else {
      findingsCell = `0 (+${m} unverified)`;
      notes = 'Unverified findings only — see secondary section';
    }

    return `| ${label} | ${agentShort} | ${findingsCell} | ${notes} |`;
  });

  return ['| Dimension | Agent | Findings | Notes |', '|-----------|-------|----------|-------|', ...rows].join('\n');
}

// Groups findings by `consolidation_key` before they reach the report renderer — #22 D2,
// same grouping rule `consolidate_delivery` applies to the posted comment payload,
// applied here to the report's findings list instead: non-primary group members are
// folded into the primary's `corroborations` array rather than listed as separate
// top-level findings. A finding with no (falsy) `consolidation_key` passes through
// unchanged — older artifacts / pre-consolidation findings render exactly as before.
function consolidateForReport(findings) {
  const list = findings || [];
  const groups = [];
  const keyToGroup = new Map();
  for (const f of list) {
    const key = f && f.consolidation_key;
    if (!key) {
      groups.push({ primary: f, corroborators: [] });
      continue;
    }
    let group = keyToGroup.get(key);
    if (!group) {
      group = { primary: null, corroborators: [] };
      keyToGroup.set(key, group);
      groups.push(group);
    }
    if (f.consolidation_primary) {
      if (!group.primary) group.primary = f;
      else group.corroborators.push(f);
    } else group.corroborators.push(f);
  }
  return groups.map((group) => {
    // Reachable only for hand-assembled payloads: filterFindings.js always
    // stamps exactly one consolidation_primary per group. If a caller's data
    // has none, fall back to the first-seen member rather than surfacing `null`.
    const primary = group.primary || group.corroborators.shift();
    if (!group.corroborators.length) return primary;
    return {
      ...primary,
      corroborations: group.corroborators.map((c) => ({
        agent: c.agent,
        dimension: c.dimension,
        confidence: c.confidence,
        title: c.title,
        description: c.description,
      })),
    };
  });
}

// Fields with a dedicated placement below. Every other registry-declared field is
// rendered through reportExtraFields, so declared-but-unrendered cannot recur.
const REPORT_PLACED_FIELDS = new Set([
  'id', 'file', 'line_start', 'line_end', 'title', 'description', 'severity',
  'confidence', 'dimension', 'origin', 'evidence', 'suggestion',
  'claude_md_rule', 'spec_text', 'cross_file_refs',
]);

function reportExtraFields() {
  const declared = new Set(Object.keys(FINDING_PROP_TYPES));
  for (const dimension of DIMENSIONS) {
    for (const key of Object.keys(dimension.schemaExtra || {})) declared.add(key);
  }
  return [...declared]
    .filter((key) => !REPORT_PLACED_FIELDS.has(key) && !REPORT_EXCLUDED_FIELDS.includes(key))
    .sort();
}

// Replayed checkpoints are object-shaped but may predate the finding schema's field types.
// Coerce at this renderer boundary so every downstream report read sees the same safe view:
// text fields stringify non-null values, null/undefined text is omitted, and confidence keeps
// only finite numbers. The catch arms make even hostile object coercion total.
function reportAsText(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  try {
    return String(value);
  } catch {
    return '';
  }
}

function reportOptionalText(value) {
  return value === undefined || value === null ? undefined : reportAsText(value);
}

function reportAsConfidence(value) {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function reportRiskLevel(value) {
  if (value === undefined || value === null) return undefined;
  if (typeof value === 'number' || typeof value === 'string') return value;
  const text = reportAsText(value);
  return text || undefined;
}

function reportCorroboration(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const out = {};
  for (const key of ['agent', 'dimension', 'title', 'description']) {
    let raw;
    try {
      raw = value[key];
    } catch {
      continue;
    }
    const text = reportOptionalText(raw);
    if (text !== undefined) out[key] = text;
  }
  let confidence;
  try {
    confidence = reportAsConfidence(value.confidence);
  } catch {
    confidence = undefined;
  }
  if (confidence !== undefined) out.confidence = confidence;
  return out;
}

function coerceReportFinding(finding) {
  const out = {};
  let keys;
  try {
    keys = Object.keys(finding);
  } catch {
    return out;
  }
  for (const key of keys) {
    let raw;
    try {
      raw = finding[key];
    } catch {
      continue;
    }
    let value;
    if (key === 'confidence') {
      value = reportAsConfidence(raw);
    } else if (key === 'corroborations') {
      value = Array.isArray(raw) ? raw.map(reportCorroboration) : undefined;
    } else if (key === 'consolidation_primary' || key === 'challenge_contested') {
      value = raw;
    } else if (key === 'risk_level') {
      value = reportRiskLevel(raw);
    } else {
      value = reportOptionalText(raw);
    }
    if (value !== undefined) out[key] = value;
  }
  return out;
}

// Exported for the run seam that ranks the selected delivery before invoking renderReport.
// Keeping this projection here means replayed malformed findings cannot reach a raw rankKey.
function coerceReportFindings(value) {
  if (!Array.isArray(value)) return [];
  return value.map((finding) => (
    finding && typeof finding === 'object' && !Array.isArray(finding)
      ? coerceReportFinding(finding)
      : {}
  ));
}

// 'failure_scenario' -> 'Failure scenario'
function fieldLabel(key) {
  const words = String(key).replaceAll('_', ' ');
  return words.charAt(0).toUpperCase() + words.slice(1);
}

// A fence at least one backtick longer than the longest run inside text, minimum 3.
function fenceFor(text) {
  let longest = 0;
  for (const match of reportAsText(text).matchAll(/`+/g)) longest = Math.max(longest, match[0].length);
  return '`'.repeat(Math.max(3, longest + 1));
}

// Bullet values, heading interpolations and the identity line are single-line positions.
function oneLine(value) {
  return reportAsText(value).replace(/\r?\n+/g, ' ').replace(/ +/g, ' ').trim();
}

function isPresent(value) {
  if (value == null) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === 'string') return value.trim() !== '';
  return true;
}

const severityMark = (severity) => SEVERITY_EMOJI[reportAsText(severity).toLowerCase()] || SEVERITY_EMOJI_FALLBACK;

function normalizeFindings(value) {
  return coerceReportFindings(value);
}

// Collect protected evidence offsets while composing, then neutralize comment openers
// in one final pass everywhere else. Evidence must preserve source bytes verbatim.
function reportBuilder() {
  let text = '';
  const evidenceRanges = [];
  const add = (line = '') => {
    if (text.length) text += '\n';
    text += reportAsText(line);
  };
  const addEvidence = (evidence) => {
    const fence = fenceFor(evidence);
    const start = text.length + (text.length ? 1 : 0);
    add(fence);
    add(reportAsText(evidence));
    add(fence);
    evidenceRanges.push([start, text.length]);
  };
  const finish = () => {
    let out = '';
    let cursor = 0;
    while (true) {
      const index = text.indexOf('<!--', cursor);
      if (index < 0) break;
      out += text.slice(cursor, index);
      const protectedEvidence = evidenceRanges.some(([start, end]) => index >= start && index < end);
      out += protectedEvidence ? '<!--' : '&lt;!--';
      cursor = index + 4;
    }
    return out + text.slice(cursor);
  };
  return { add, addEvidence, finish };
}

function location(finding) {
  if (!isPresent(finding.file)) return '';
  const file = oneLine(finding.file);
  if (!isPresent(finding.line_start)) return file;
  const start = oneLine(finding.line_start);
  if (!isPresent(finding.line_end) || String(finding.line_end) === String(finding.line_start)) {
    return `${file}:${start}`;
  }
  return `${file}:${start}-${oneLine(finding.line_end)}`;
}

function unverifiedReason(finding) {
  const reasons = [];
  if (finding.origin === 'unknown') {
    reasons.push('the verify slice could not be proven against the dispatched document');
  }
  if (finding.challenge === 'skipped') {
    reasons.push('the challenge cap was reached, so this finding was not challenge-verified');
  }
  return reasons.length ? reasons.join('; ') : 'a pipeline stage was skipped or failed';
}

function renderFinding(builder, finding, unverified) {
  const blocks = [];
  blocks.push(() => builder.add(`#### ${oneLine(finding.title)}`));

  const bullets = [];
  const where = location(finding);
  if (where) bullets.push(`- **Location:** \`${where}\``);
  const classification = [];
  if (isPresent(finding.dimension)) classification.push(`**Dimension:** ${oneLine(finding.dimension)}`);
  if (isPresent(finding.confidence)) classification.push(`**Confidence:** ${oneLine(finding.confidence)}%`);
  if (classification.length) bullets.push(`- ${classification.join(' · ')}`);
  if (finding.origin === 'surfaced') {
    bullets.push('- **Origin:** surfaced — pre-existing, surfaced by this change');
  }
  if (unverified) bullets.push(`- **Unverified because:** ${unverifiedReason(finding)}`);
  if ((finding.report_tag ?? finding.report_destination) === 'suggestion') {
    bullets.push('- **Routing:** improvement suggestion');
  }
  if (finding.demoted_by === 'reachability') {
    bullets.push('- **Reachability:** only under a future change (severity demoted to low)');
  }
  if (finding.challenge_contested === true) {
    bullets.push('- **Contested:** the challenger could not confirm the cited location');
  }
  if (bullets.length) blocks.push(() => bullets.forEach(builder.add));

  if (isPresent(finding.description)) blocks.push(() => builder.add(reportAsText(finding.description)));
  if (isPresent(finding.evidence)) {
    blocks.push(() => {
      builder.add('**Evidence:**');
      builder.add();
      builder.addEvidence(finding.evidence);
    });
  }

  const extras = reportExtraFields()
    .filter((key) => isPresent(finding[key]))
    .map((key) => `- **${fieldLabel(key)}:** ${oneLine(finding[key])}`);
  if (extras.length) blocks.push(() => extras.forEach(builder.add));

  if (isPresent(finding.suggestion)) {
    blocks.push(() => {
      builder.add('**Suggested fix:**');
      builder.add();
      builder.add(reportAsText(finding.suggestion));
    });
  }

  const citedRule = isPresent(finding.claude_md_rule) ? finding.claude_md_rule : finding.spec_text;
  if (isPresent(citedRule)) {
    blocks.push(() => {
      builder.add('**Cited rule:**');
      builder.add();
      builder.add(reportAsText(citedRule).split(/\r?\n/).map((line) => `> ${line}`).join('\n'));
    });
  }

  if (isPresent(finding.cross_file_refs)) {
    blocks.push(() => builder.add(`- **Cross-file refs:** ${oneLine(finding.cross_file_refs)}`));
  }

  if (Array.isArray(finding.corroborations) && finding.corroborations.length) {
    blocks.push(() => {
      for (const corroboration of finding.corroborations) {
        const agent = oneLine(corroboration.agent);
        const dimension = oneLine(corroboration.dimension);
        const confidence = oneLine(corroboration.confidence);
        const title = oneLine(corroboration.title);
        builder.add(`- **Corroborated by** \`${agent}\` (\`${dimension}\`, confidence ${confidence}) — ${title}`);
        if (isPresent(corroboration.description)) {
          builder.add(reportAsText(corroboration.description).split(/\r?\n/).map((line) => `  ${line}`).join('\n'));
        }
      }
    });
  }

  blocks.forEach((block, index) => {
    if (index) builder.add();
    block();
  });
}

function severityKey(finding) {
  return (oneLine(finding.severity) || 'unknown').toLowerCase();
}

function severityView(findings) {
  const ranked = rankFindings(findings);
  const buckets = new Map();
  for (const finding of ranked) {
    const key = severityKey(finding);
    if (!buckets.has(key)) buckets.set(key, []);
    buckets.get(key).push(finding);
  }
  const known = SEVERITY_ORDER.filter((severity) => buckets.has(severity));
  const rest = [...buckets.keys()].filter((severity) => !SEVERITY_ORDER.includes(severity));
  return { buckets, order: [...known, ...rest] };
}

function renderSeverityBuckets(builder, view, unverified) {
  for (const severity of view.order) {
    builder.add();
    builder.add(`### ${severityMark(severity)} ${fieldLabel(severity)}`);
    for (const finding of view.buckets.get(severity)) {
      builder.add();
      renderFinding(builder, finding, unverified);
    }
  }
}

function countsSentence(findings, rawCount, unverified, view) {
  const count = findings.length;
  let sentence = count === rawCount
    ? `${count} finding(s) after the gauntlet`
    : `${count} reported issue(s) from ${rawCount} finding(s) after the gauntlet`;
  const breakdown = view.order.map((severity) => `${view.buckets.get(severity).length} ${severity}`);
  sentence += count > 0 && breakdown.length ? ` — ${breakdown.join(', ')}.` : '.';
  const suggestions = findings.filter((finding) => (finding.report_tag ?? finding.report_destination) === 'suggestion').length;
  if (suggestions) sentence += ` ${suggestions} routed as improvement suggestion(s).`;
  if (unverified.length) sentence += ` ${unverified.length} unverified / pipeline-degraded.`;
  return sentence;
}

// Complete report.md with no trailing newline. Pure and total for absent/empty input:
// no clock, dispatch, prompt, schema, segmentation or fallback participates.
function renderReport(input) {
  const inp = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  const rawFindings = normalizeFindings(inp.findings);
  const rawUnverified = normalizeFindings(inp.unverified);
  const findings = consolidateForReport(rawFindings);
  const unverified = consolidateForReport(rawUnverified);
  const findingsView = severityView(findings);
  const unverifiedView = severityView(unverified);
  const identity = inp.prIdentity && typeof inp.prIdentity === 'object' && !Array.isArray(inp.prIdentity)
    ? inp.prIdentity
    : null;

  let subject = 'local changes';
  if (identity && typeof identity.title === 'string' && identity.title.trim()) {
    subject = oneLine(identity.title);
  } else if (
    identity
    && isPresent(identity.owner)
    && isPresent(identity.repo)
    && isPresent(identity.pr_number)
  ) {
    subject = `\`${oneLine(identity.owner)}/${oneLine(identity.repo)}#${oneLine(identity.pr_number)}\``;
  }

  const identityParts = ['Reviewed'];
  if (isPresent(inp.headShaShort)) identityParts.push(`head \`${oneLine(inp.headShaShort)}\``);
  if (isPresent(inp.generatedAt)) identityParts.push(`at ${oneLine(inp.generatedAt)}`);
  identityParts.push(`by ${BRAND_NAME}.`);

  const builder = reportBuilder();
  builder.add(`# ${BRAND_MARK} ${BRAND_NAME}: ${subject}`);
  builder.add();
  builder.add(identityParts.join(' '));
  builder.add();
  builder.add('## Summary');
  builder.add();
  if (isPresent(inp.summary)) {
    builder.add(reportAsText(inp.summary));
    builder.add();
  }
  builder.add(countsSentence(findings, rawFindings.length, unverified, findingsView));

  if (findings.length) {
    builder.add();
    builder.add('## Findings');
    renderSeverityBuckets(builder, findingsView, false);
  }

  if (unverified.length) {
    builder.add();
    builder.add('## Unverified / pipeline-degraded findings');
    builder.add();
    builder.add('These did not clear the full pipeline (a stage was skipped or failed) and carry lower confidence. They are not confirmed findings.');
    renderSeverityBuckets(builder, unverifiedView, true);
  }

  const dimensionsTable = dimensionsSummaryTable({
    ...(inp.dimensions && typeof inp.dimensions === 'object' ? inp.dimensions : {}),
    findings: rawFindings,
    unverified: rawUnverified,
  });
  builder.add();
  builder.add('## Review Dimensions Summary');
  builder.add();
  builder.add(dimensionsTable);
  return builder.finish();
}

// --- args.js ---

// args.js — the pipeline args waist: ARGS_VERSION, normalizeArgs, validateArgs.
// Single producer of the waist shape that bench and the pipeline entry both consume.
//
// policy shape: { tier, subagentModel, provider, gateway } — tier records the resolved
// model_tier knob (its only valid value today is "optimized"; alternate modes are roadmap
// #17 V3.2).
//   - policy.subagentModel is passed to registry.js's resolvePolicy() as opts.subagentModelEnv.
//     This is a RENAME, not a passthrough — dispatch sites must map the field name.
//   - policy.tier is carried through the waist but is not read by resolvePolicy today.
//   - policy.provider (optional; POLICY_PROVIDERS) is the skill's Phase 2 capture of which
//     API provider the session runs on (the workflow cannot read process.env, so this
//     capture is the only path). resolvePolicy pins full first-party model IDs only for
//     'firstParty'/absent; any other provider dispatches bare aliases, which the harness
//     resolves through the provider's deployment mapping — first-party IDs like
//     claude-sonnet-5 are passed through unchecked on Bedrock/Vertex/Foundry and 400.
//   - policy.gateway (optional boolean; issue #218) is the skill's Phase 2 capture of
//     whether ANTHROPIC_BASE_URL is set — an LLM gateway proxies the Anthropic API, so it
//     does not change policy.provider (see POLICY_PROVIDERS below), but it DOES gate off
//     registry.js's conditionalSchemaActive: a gateway forwards input_schema verbatim to
//     whatever backend it fronts, which could be an unmeasured third-party surface even
//     while the session itself reads as firstParty.
const ARGS_VERSION = 1;
// changedFiles/changedLines feed summarize bucketing and the agent-count guard, so they're
// REQUIRED because they're consumed. `mode` is NOT read anywhere in workflows/src beyond a
// re-check against its own enum below — it is provenance/telemetry the skill always stamps.
// `repoRoot` is also unread by every stage: it is provenance-only by measurement (issue #81
// comment 2026-08-07: 15 completed runs / 30 security-reviewer + cross-file-impact agents —
// ambient cwd is the reviewed repo; zero relative path-bearing Read/Grep/Glob). It stays
// REQUIRED so the skill's `git rev-parse --show-toplevel` stamp remains in the persisted
// waist for forensics, not because any stage consumes it. changedFilesPath is on-disk
// provenance the workflow never opens.
const REQUIRED = ['mode', 'repoRoot', 'outputDir', 'headShaShort', 'nonce', 'generatedAt', 'diffPath', 'changedFiles', 'changedLines', 'riskTable', 'policy', 'limits'];

// The nonce is interpolated into the verify executor command argv (the verify stage
// derives one per slice as `${nonce}.${i}`), so it must be a single AST-safe,
// non-splitting token: word chars plus `.` `_` `-` only — no whitespace or shell
// metacharacters that could split argv or break AST-safe emission.
const NONCE_RE = /^[A-Za-z0-9._-]+$/;

// The optional Phase 8 delivery selector: { tier }. Absent is fine (the workflow defaults
// the tier to 'all' — post every challenge-survivor). A present tier must be a known value.
const DELIVERY_TIERS = ['all', 'main_only'];

// Known values for policy.provider. The enum exists because the two arms diverge silently:
// a typo ('first-party', 'aws') would flip a first-party session onto bare aliases —
// reintroducing the measured [1m] session-variant cascade the full-ID pin exists to stop —
// with no error anywhere. Fail loud at the waist instead. No 'gateway' value: an LLM
// gateway (ANTHROPIC_BASE_URL) proxies the Anthropic API and expects standard Claude model
// names, so gateway sessions are firstParty; non-standard gateway names go through the
// subagentModel escape hatch. A gateway session is instead marked by the separate
// policy.gateway BOOLEAN (issue #218, validated below) — it rides alongside provider rather
// than inside this enum because it answers a different question (does input_schema reach an
// unmeasured backend verbatim?), not which model-ID arm resolvePolicy takes.
const POLICY_PROVIDERS = ['firstParty', 'bedrock', 'vertex', 'foundry'];

// Shared with PATH_CONTROL_RE further down (declared locally there because it sits inside
// validateArgs); duplicated at module scope here so the reviewMd[].path guard above — which
// runs earlier in validateArgs, before that local const is declared in source order — can
// reuse the identical charset without a forward reference.
const REVIEW_MD_PATH_CONTROL_RE = /[\u0000-\u001F\u007F]/;

// Issue #38 A1 (measured): a dispatch was rejected solely because reviewConfig arrived as a
// stamped `null` rather than absent — a wasted model round trip. These five top-level
// optional fields have no meaning as `null` (only "absent" or "a well-formed object/array"),
// so a literal null is equivalent to omission and gets dropped before validateArgs ever sees
// it. This allowlist is intentionally narrow: do NOT extend the null-tolerance treatment to
// any other field. In particular, limits.deliveryCap: null means "uncapped" and
// policy.subagentModel: null means "no override" — both are load-bearing DATA, not omitted-
// field stand-ins, and must survive this step untouched.
//
// `persist` is on the list for the same reason its siblings are (its null means "take the
// legacy by-value writer path", exactly what absence means); leaving it off was a hole that
// hard-rejected a whole run over a stamped null — the very cost this allowlist exists to
// remove.
//
// TOLERATED IS NOT SILENT. Dropping a stamped null removes a fail-loud guard: a mis-stamped
// `reviewConfig: null` would otherwise review under the Filter stage's config-absent
// defaults instead of the operator's REVIEW.md thresholds — a silent change to the DELIVERED
// findings, which issue #38 forbids. So every drop that ACTUALLY removed a guard is REPORTED
// (stripNullOptionalsReport -> nullToleranceRejectedKeys -> runWith -> an envelope gap via
// nullToleranceGap): degraded-but-disclosed, the contract this pipeline uses everywhere else.
// A drop that validateArgs would have accepted anyway (`checkpoints`) tolerated nothing and
// is deliberately NOT disclosed — see nullToleranceRejectedKeys.
const NULLABLE_TOP_LEVEL = ['reviewConfig', 'exclusionPatterns', 'reviewMd', 'exclusionsText', 'delivery', 'checkpoints', 'persist', 'scopeAnswer'];

// Issue #24 req 1/4 (PR3): the scope decision itself. 'light'/'full' mirror the
// $CODE_GAUNTLET_TRIVIAL_SCOPE / interactive Light-review-vs-Full-review answer verbatim — the
// orchestrator's only scope job is to produce riskTable (below) and echo whichever answer the
// gate asked for, when it asked. Absent means the gate was never asked (not every-file-low-risk-
// and-<50-lines) and 'full' is not a value the orchestrator needs to fabricate for that case.
const SCOPE_ANSWERS = ['light', 'full'];

// Issue #24 req 1/2 (PR3): the risk classification a plain string. Matches the three-tier
// scale documented in skills/code-gauntlet/references/phase2-triage.md 2e — that table is now
// the single contract for these literals; riskTable values must stay in lockstep with it.
const RISK_LEVELS = ['low', 'medium', 'high'];

// Issue #24 req 7: the ONE place the benchmarked-default limits live. Every stage that
// used to hand-roll `Math.max(1, limits.X || <literal>)` (stages.js summarize/verify/
// validate/challenge) and the worstCaseAgentCount/coarsenLimits helpers now read a limits
// object normalizeArgs has already filled from this constant — the literal default exists
// in exactly one place, not triplicated across stage bodies, helpers, and prose tables.
//
// deliveryCap and discoveryCap are DELIBERATELY ABSENT from this table: their null/absent
// state is meaningful DATA (uncapped delivery / no per-agent discovery ceiling), not a
// value waiting on a default — see the "meaningful nulls" note above (limits.deliveryCap:
// null means "uncapped"). Defaulting either here would silently cap a caller who asked for
// none.
const LIMIT_DEFAULTS = {
  summarizeBucketSize: 20,
  validateBatch: 25,
  challengeCap: 40,
  verifySliceSize: 200,
  maxLineSpan: 100,
};

// computeLightEligible(riskTable, changedLines) -> boolean (issue #24 req 5, PR3).
// The ONE place the light-scope eligibility rule lives — behavior-preserving copy of the
// prose rule SKILL.md used to state at assembly time (phase2-triage.md 2e "Light Review for
// Trivial PRs"): every riskTable entry classified 'low' AND total changedLines < 50. Exported
// so validateArgs (below, for the pre-dispatch coherence guard) and stages.js's
// deriveAgentFlags (the actual flag derivation) call the SAME rule rather than each carrying
// its own copy that could drift. Pure — no host globals.
function computeLightEligible(riskTable, changedLines) {
  if (!Array.isArray(riskTable)) return false;
  if (typeof changedLines !== 'number' || !(changedLines < 50)) return false;
  // .every on an empty array is vacuously true — a PR with zero changed files/lines is
  // trivially "every file is low risk" and is eligible for light scope, same as one file.
  return riskTable.every((entry) => entry && entry.risk === 'low');
}

// What the operator actually loses when a stamped null is treated as absent, per key. Used
// only to word the disclosure gap — no control flow reads it.
const NULL_TOLERANCE_CONSEQUENCE = {
  reviewConfig: 'the review runs on the Filter stage built-in thresholds (non-security 55, security 70) with no ignore list, NOT your REVIEW.md configuration, so the delivered findings can differ',
  exclusionPatterns: 'no exclusion patterns are applied, so the delivered findings can differ',
  reviewMd: 'the review runs on the Filter stage built-in thresholds (non-security 55, security 70) with no ignore list, NOT your REVIEW.md configuration, so the delivered findings can differ',
  exclusionsText: 'no exclusion patterns are applied, so the delivered findings can differ',
  delivery: 'delivery falls back to tier "all" with no PR identity',
  'delivery.tier': 'delivery falls back to tier "all", so a narrowing intent is lost',
  'delivery.prIdentity': 'the post-review artifact is persisted as a bare findings array instead of the post_review-ready wrapper',
  'delivery.prIdentity.title': 'the report title falls back to owner/repo#N (or "local changes")',
  checkpoints: 'no resume state is replayed — every phase re-runs from scratch',
  persist: 'the artifact-writer takes the legacy full by-value persist path',
  scopeAnswer: 'the scope gate is treated as never having been asked, so deriveAgentFlags cannot honour a light answer',
};

// nullToleranceGap(key) -> the operator-actionable gap line for one dropped null. Names the
// field, states it was treated as ABSENT, states the consequence, and says to omit it.
// Pure string building — no host globals (the workflow sandbox has no console/process).
function nullToleranceGap(key) {
  const why = NULL_TOLERANCE_CONSEQUENCE[key] || 'the run proceeds as if the field had not been supplied';
  return `null_arg: args.${key} arrived as a literal null and was treated as ABSENT — ${why}. Omit ${key} entirely (or stamp a well-formed value); do not stamp null.`;
}

// nullToleranceRejectedKeys(cleanArgs, dropped) -> the subset of `dropped` whose stamped null
// validateArgs would ACTUALLY have rejected — i.e. the keys where the tolerance changed the
// outcome and there is therefore something to disclose.
//
// `checkpoints` is why this exists (issue #38 F4-3): validateArgs has never carried a
// checkpoints shape check, so a stamped `checkpoints: null` was ALWAYS equivalent to absence.
// Nothing was tolerated and nothing was lost, so a gap there announced a degradation that
// never happened — and noise in the gap channel is corrosive precisely because gaps are how
// this pipeline stays honest about the degradations that DID happen.
//
// The subset is COMPUTED, not listed: one differential validateArgs call per dropped key (the
// stripped waist, vs the same waist with that null put back). A second hand-maintained list
// would drift the moment someone adds or removes a shape check. Pure — validateArgs is pure,
// and the probe objects are shallow copies, so the caller's waist is untouched.
function nullToleranceRejectedKeys(cleanArgs, dropped) {
  if (!Array.isArray(dropped) || dropped.length === 0) return [];
  const baseline = validateArgs(cleanArgs).errors.length;
  return dropped.filter((key) => validateArgs(withNullAt(cleanArgs, key)).errors.length > baseline);
}

// The stripped waist with ONE dropped null put back, addressed by the same full dotted
// path spelling stripNullOptionalsReport reports. Every traversed level is shallow-copied,
// so an arbitrarily deep optional can be probed without mutating the caller's waist.
function withNullAt(args, key) {
  const base = (args && typeof args === 'object' && !Array.isArray(args)) ? args : {};
  const parts = key.split('.');
  const out = { ...base };
  let source = base;
  let target = out;
  for (const part of parts.slice(0, -1)) {
    const value = source && typeof source === 'object' && !Array.isArray(source)
      ? source[part]
      : undefined;
    const copy = value && typeof value === 'object' && !Array.isArray(value) ? { ...value } : {};
    target[part] = copy;
    target = copy;
    source = value;
  }
  target[parts.at(-1)] = null;
  return out;
}

// stripNullOptionalsReport(args) -> { args, dropped }
// Drops a literal top-level null for the narrow NULLABLE_TOP_LEVEL allowlist (and, inside a
// present `delivery` object, a literal null for its `prIdentity`/`tier` sub-fields), and
// names every key it dropped so the caller can DISCLOSE the substitution.
// Non-mutating: the returned waist is a fresh shallow copy and a touched `delivery` is
// itself copied, so a caller holding the original object sees no change (its stamped nulls
// are still there). Non-object input (undefined, null, a string) passes through as-is with
// an empty `dropped`; there is nothing to strip.
function stripNullOptionalsReport(args) {
  if (!args || typeof args !== 'object' || Array.isArray(args)) return { args, dropped: [] };
  const dropped = [];
  const out = { ...args };
  for (const k of NULLABLE_TOP_LEVEL) {
    if (out[k] === null) { delete out[k]; dropped.push(k); }
  }
  if (out.delivery && typeof out.delivery === 'object' && !Array.isArray(out.delivery)) {
    const delivery = { ...out.delivery };
    if (delivery.prIdentity === null) { delete delivery.prIdentity; dropped.push('delivery.prIdentity'); }
    if (
      delivery.prIdentity
      && typeof delivery.prIdentity === 'object'
      && !Array.isArray(delivery.prIdentity)
      && delivery.prIdentity.title === null
    ) {
      const id = { ...delivery.prIdentity };
      delete id.title;
      delivery.prIdentity = id;
      dropped.push('delivery.prIdentity.title');
    }
    if (delivery.tier === null) { delete delivery.tier; dropped.push('delivery.tier'); }
    out.delivery = delivery;
  }
  // Fill ONLY absent LIMIT_DEFAULTS keys — never overwrite a caller-provided value, and
  // never fill deliveryCap/discoveryCap (both absent from LIMIT_DEFAULTS on purpose; see
  // its comment). A provided `challengeCap: 0` is a real cap of zero and must survive
  // untouched, which `=== undefined` (not falsy) guarantees. A non-object `limits` (or one
  // missing entirely) is left for validateArgs to reject — this step does not repair shape.
  if (out.limits && typeof out.limits === 'object' && !Array.isArray(out.limits)) {
    const limits = { ...out.limits };
    for (const [k, v] of Object.entries(LIMIT_DEFAULTS)) {
      if (limits[k] === undefined) limits[k] = v;
    }
    out.limits = limits;
  }
  return { args: out, dropped };
}

function normalizeArgsReport(raw) {
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  return stripNullOptionalsReport(parsed);
}

function normalizeArgs(raw) {
  return normalizeArgsReport(raw).args;
}

// --- Issue #27: classified entry refusals ------------------------------------------------
//
// Two live incidents motivate this section, both from naked `Workflow` invocations that
// skipped the code-gauntlet skill (which is the only producer of a valid waist):
//   L1 — a raw string ("PR 310") died in JSON.parse with a native stack and no guidance.
//   #27 — the caller passed a review-target reference (a PR URL, a bare number, "PR 310")
//         WHERE THE WAIST BELONGED. The old generic message didn't say that, so the fix
//         a human reaches for is "paste the PR number", which is exactly the wrong fix —
//         the workflow doesn't consume a PR reference at all; Phases 1-2 of the skill do,
//         and build the waist FROM it.
// classifyReviewTarget recognizes that shape so the refusal can name it and echo it back
// in the exact skill invocation to run instead.

// `<n>` everywhere: PR/MR numbers start at 1; a leading zero or an 8-digit run is not a
// PR reference (spec table, rule 4). No nested quantifiers anywhere below — every pattern
// is one quantified group followed by a literal or an anchor, so a pathological input
// (verified: 200 chars of "a/") returns in microseconds, not a ReDoS hang the workflow has
// no per-call timeout to recover from.
const REVIEW_TARGET_N = '[1-9]\\d{0,6}';
// host is `[\w.-]+` (not just known hosts) so a GitHub Enterprise or self-hosted GitLab
// domain still matches; owner/repo segments are `[^\s/]+` so they stop at the next `/`
// without needing a nested quantifier. Trailing `/…`, `?…`, `#…` cover GitHub's own
// `/files`, `/commits` suffixes and query/fragment noise without being required.
const PR_URL_RE = new RegExp(`^(?:https?://)?[\\w.-]+/[^\\s/]+/[^\\s/]+/pull/(${REVIEW_TARGET_N})(?:/[^\\s?#]*)?(?:\\?[^\\s#]*)?(?:#\\S*)?$`);
// The literal `/-/merge_requests/` segment is the same discriminator
// references/phase1-preflight.md:98 already documents in prose for telling a GitLab MR
// URL apart from anything else GitLab hosts at a path. The path before it is lazy (`\S+?`)
// so a subgroup ("group/subgroup/project") matches without knowing its depth up front.
const MR_URL_RE = new RegExp(`^(?:https?://)?[\\w.-]+/\\S+?/-/merge_requests/(${REVIEW_TARGET_N})(?:/[^\\s?#]*)?(?:\\?[^\\s#]*)?(?:#\\S*)?$`);
const REPO_REF_RE = new RegExp(`^[^\\s/]+/[^\\s/]+#(${REVIEW_TARGET_N})$`);
const PR_NUMBER_RE = new RegExp(`^(${REVIEW_TARGET_N})$`);
const PR_SHORTHAND_HASH_RE = new RegExp(`^[#!](${REVIEW_TARGET_N})$`);
// Longest alternatives first (`pull request`/`merge request` before `pull`) purely to
// avoid a redundant backtrack on the common phrase — anchoring makes the order
// non-load-bearing for correctness. Case-insensitive: "pr 310" is as real a caller typo
// as "PR 310".
const PR_SHORTHAND_WORD_RE = new RegExp(`^(?:pull request|merge request|PR|MR|pull)[ ]?[#!]?(${REVIEW_TARGET_N})$`, 'i');

// classifyReviewTarget(raw) -> { kind, number, ref } | null
// Cheap, deterministic, pure — no host globals (sandbox: language builtins and JSON only).
// `ref` is always the caller's OWN text, trimmed — never a reconstruction — because it is
// echoed verbatim into the recovery line so the caller recognizes their own input.
function classifyReviewTarget(raw) {
  if (typeof raw === 'number') {
    // A JS number input classifies exactly like its string form would (waist fields never
    // arrive this way, but a caller passing `Workflow(..., 45)` is a plausible slip).
    if (Number.isSafeInteger(raw) && raw >= 1 && raw <= 9999999) {
      return { kind: 'pr_number', number: String(raw), ref: String(raw) };
    }
    return null;
  }
  if (typeof raw !== 'string') return null;
  const s = raw.trim();
  // A review reference is short; a truncated waist JSON is long. The 200-char bound keeps
  // the classifier cheap and its echo bounded — it is checked BEFORE any regex runs.
  if (s === '' || s.length > 200) return null;
  let m;
  if ((m = PR_URL_RE.exec(s))) return { kind: 'pr_url', number: m[1], ref: s };
  if ((m = MR_URL_RE.exec(s))) return { kind: 'mr_url', number: m[1], ref: s };
  if ((m = REPO_REF_RE.exec(s))) return { kind: 'repo_ref', number: m[1], ref: s };
  if ((m = PR_NUMBER_RE.exec(s))) return { kind: 'pr_number', number: m[1], ref: s };
  if ((m = PR_SHORTHAND_HASH_RE.exec(s))) return { kind: 'pr_shorthand', number: m[1], ref: s };
  if ((m = PR_SHORTHAND_WORD_RE.exec(s))) return { kind: 'pr_shorthand', number: m[1], ref: s };
  return null;
}

const REVIEW_TARGET_LABEL = {
  pr_url: 'a GitHub PR URL',
  mr_url: 'a GitLab MR URL',
  repo_ref: 'an owner/repo PR reference',
  pr_number: 'a bare PR/MR number',
  pr_shorthand: 'a PR/MR reference',
};

const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

// How many JSON layers to peel looking for the waist. The documented "session tool-call
// form" wraps it once; the harness quirk this file already guards for wraps it twice.
// Bounded because peeling is free work a caller could hand us without limit, and because an
// unbounded peel would accept a payload no downstream hop could have produced.
const MAX_JSON_UNWRAP = 4;

// unwrapWaist(raw) -> { waist, terminal }
//   waist    — the plain object the pipeline should run on, or null if there isn't one.
//   terminal — the fully-decoded value we stopped at (the unparseable string, the decoded
//              scalar, the array). What the refusal classifies and echoes.
//
// This exists as ONE explicit loop because the two-layer case used to work only by
// accident: parseEntryArgs parsed once and runWith's normalizeArgsReport parsed again, so
// two hops happened to peel two layers between them. Refusing at the entry removes the
// second hop, and with it that accidental recovery — a valid, double-encoded waist would
// have been hard-rejected, breaking issue #27's own "no valid waist newly rejected"
// constraint. Peeling here, to completion, also decouples the accepted depth from how many
// parse hops happen to follow: parseEntryArgs returns the finished object either way.
function unwrapWaist(raw) {
  let value = raw;
  for (let depth = 0; depth <= MAX_JSON_UNWRAP; depth++) {
    if (isPlainObject(value)) return { waist: value, terminal: value };
    if (typeof value !== 'string' || depth === MAX_JSON_UNWRAP) break;
    let next;
    try { next = JSON.parse(value); } catch { break; }
    value = next;
  }
  return { waist: null, terminal: value };
}

// describeShape(raw) -> the `<desc>` half of message C (spec 1c) for a value that is
// neither an acceptable waist shape nor a classified review target. Truncated to 80 chars
// for a string — long enough to recognize, short enough that a stray multi-KB payload
// doesn't blow out the refusal message itself.
function describeShape(raw) {
  if (typeof raw === 'string') {
    const s = raw.length > 80 ? `${raw.slice(0, 80)}…` : raw;
    // JSON.stringify, not manual quoting: it is a TOTAL escape over every control
    // character, so the echo cannot break the single-physical-line invariant no matter
    // what the caller passed. Truncating alone did not — a truncated pretty-printed waist
    // carries its own newlines, and they landed raw in the message on both seams.
    return `a raw string: ${JSON.stringify(s)}`;
  }
  if (Array.isArray(raw)) return 'an array';
  if (typeof raw === 'boolean') return `a boolean: ${raw}`;
  if (typeof raw === 'number') return `a number: ${raw}`;
  return 'an unrecognized value';
}

// refusalFrom(raw, unwrapped) -> string | null. The wording and the accept/refuse decision,
// taking the ALREADY-unwrapped result so a caller that needs both the verdict and the waist
// (parseEntryArgs, runWith) peels the payload once rather than twice. Both seams reach this
// through `entryArgs` — `parseEntryArgs` throws the message, `runWith` returns it inside
// the envelope — so the two cannot say different things about the same input (pinned by
// entry_guard.test.js's "one message, two signals" test). `null` means the value may
// proceed to normalizeArgsReport/validateArgs.
function refusalFrom(raw, unwrapped) {
  if (raw === undefined || raw === null) {
    const got = raw === undefined ? 'undefined' : 'null';
    return `args never arrived: the code-gauntlet workflow was invoked with no args at all (got ${got}). `
      + 'This workflow builds nothing itself — Phases 1-2 of the code-gauntlet skill resolve and check '
      + 'out the target, write the diff and shared context, and assemble the argsVersion:1 waist object '
      + 'it consumes. Run the skill instead: Skill("code-gauntlet:code-gauntlet", args="<PR number or URL '
      + '— omit to auto-detect this branch\'s PR, else local changes>"). To resume an interrupted run, '
      + 're-invoke with the SAME args object plus resumeFromRunId.';
  }

  const { waist, terminal } = unwrapped;
  if (waist !== null) return null;

  // Classify the RAW value first, before any JSON.parse: '310' is valid JSON (the number
  // 310), so classifying only the decoded value would let a bare PR number parse clean and
  // fall through to the generic shape message with no recovery line at all (spec 1b).
  // Then the fully-decoded terminal value — the double-encoded case
  // ('"https://github.com/o/r/pull/45"', quotes and all), where no review-reference pattern
  // matches the raw quoted form but every one matches the decoded value. Echo whichever
  // value actually classified, so the recovery line carries a reference the caller can use.
  const target = classifyReviewTarget(raw) || classifyReviewTarget(terminal);
  // A classified ref containing a `"` or a `\` would corrupt the copy-paste `args="<ref>"`
  // line, and both are reachable: the repo_ref/URL owner-repo segments are `[^\s/]+` and
  // the URL patterns' optional path/query/fragment groups are `[^\s?#]*`/`\S*`, none of
  // which exclude either character. The quote closes the argument early; a ref ending in an
  // ODD number of backslashes leaves a bare `\` abutting the closing quote, escaping it in
  // every double-quoted-string grammar a consumer might re-parse this line with. Escaping
  // them here would make the line technically valid but no longer literally copy-pasteable,
  // which defeats the point — fall back to the generic message instead (spec 1c, pinned by
  // two tests). Checked as a set, not by parity: a lone `\` anywhere is already a smell.
  //
  // Both messages below lead with what WENT WRONG, not with what is required. The platform
  // reports this run as <status>completed</status> either way, so a session skimming the
  // notification has only the first clause to tell a refusal from a result — and "args must
  // be the assembled waist object…" reads as a spec statement until several words in.
  // "args was X, not Y" reads as a complaint immediately, matching the absent-class shape.
  if (target && !/["\\]/.test(target.ref)) {
    return `args was ${REVIEW_TARGET_LABEL[target.kind]} (${target.ref}), not the assembled argsVersion:1 `
      + 'waist object — do not invoke this workflow directly; run the code-gauntlet skill (Phases 1-2 '
      + `build the args). Run this instead: Skill("code-gauntlet:code-gauntlet", args="${target.ref}")`;
  }

  return `args was ${describeShape(raw)}, not the assembled argsVersion:1 waist object — do not invoke `
    + 'this workflow directly; run the code-gauntlet skill (Phases 1-2 build the args). Run this '
    + 'instead: Skill("code-gauntlet:code-gauntlet", args="<your PR number or URL>")';
}

// The recovery line for an args failure that has NO caller reference to echo — the
// validateArgs cascade in runWith (a plain object that is not a waist: `{}`, or a waist
// assembled by hand with fields missing). The entry's own refusals build the same call with
// the caller's reference in it; this is the referenceless form, so both paths end by naming
// the skill rather than only the defect.
//
// Why the cascade needs one at all: a plain object is accepted by the entry ON PURPOSE — a
// near-miss waist gets validateArgs's field-by-field list, which is far better diagnostics
// than "not a waist" — but that list says nothing about WHERE the fields come from, which
// is exactly the inference issue #27 exists to remove. `Workflow(scriptPath, args={})` is as
// plausible a naive call as a bare PR number and used to land here with no way out.
const SKILL_RECOVERY_LINE = 'The code-gauntlet skill assembles this object in Phases 1-2 — '
  + 'run it instead of invoking the workflow directly: '
  + 'Skill("code-gauntlet:code-gauntlet", args="<PR number or URL>")';

// makeArgsRejectEnvelope(message, gaps) -> the ONE args-failure envelope shape.
// Used by entryArgs (entry refusal) and by runWith's validateArgs-reject arm, so a
// caller downstream sees one shape for every args failure — not two hand-built literals
// that a comment claims match. `gaps` is the full gap list for that path (entry refusal:
// `[message]`; validateArgs reject: `[...nullArgGaps, ...check.errors]`).
function makeArgsRejectEnvelope(message, gaps) {
  return {
    ok: false,
    error: message,
    phaseReached: 'args',
    failingPhase: 'args',
    artifactPaths: {},
    stats: {},
    gaps,
  };
}

// entryArgs(raw) -> { ok:true, waist } | { ok:false, envelope }
// The one seam-agnostic entry check: unwraps ONCE, decides, and hands back either the waist
// the pipeline should run on or the refusal already wrapped in an envelope. Both callers use
// it, so neither can drift on how deeply it unwraps — runWith accepting a double-encoded
// waist and then re-normalizing from the raw string would peel one layer fewer and hand
// validateArgs a string, an accept-then-fail cascade worse than either clean outcome.
function entryArgs(raw) {
  const unwrapped = unwrapWaist(raw);
  const message = refusalFrom(raw, unwrapped);
  if (message === null) return { ok: true, waist: unwrapped.waist };
  // This refusal has nothing else to report, so the message IS the (sole) gap.
  return { ok: false, envelope: makeArgsRejectEnvelope(message, [message]) };
}

// The bundle entry's args guard (live-run L1 / issue #27): a direct Workflow invocation
// with a raw string ("PR 310") used to die in JSON.parse with a native stack and no
// guidance. The entry cannot be unit-tested itself (its body ends in a top-level
// `return`), so the guard lives here and the entry calls it.
//
// KEEPS THROWING, on purpose (spec R3, verified — do not "fix" this to a return): a
// returned `{ok:false, ...}` is reported to the naked-call caller as
// `<status>completed</status>`, identical to a successful run (recorded bench runs in this
// repo; anthropics/claude-code#66745, still open) — so the caller least likely to parse a
// return value (it branches on status) would read a refused review as a finished one. A
// throw is the only signal this platform renders as a visible failure. runWith's own seam
// is throw-free by contract and RETURNS the identical refusal, via the shared entryArgs,
// instead (stages.js) — two signals, ONE refusalFrom wording, so the wording cannot drift
// between them.
//
// Refuses three classes now, not just an unparseable string: absent (undefined/null), a
// classified review target, and any other non-object shape. `parseEntryArgs(undefined)`
// no longer returns `undefined` silently (requirement 5) — that silence used to leave the
// naked-call caller, again the one least likely to check a return value, to fall through
// to a generic downstream validateArgs rejection with no recovery line at all.
//
// PARSE ONLY — deliberately does NOT strip stamped nulls. runWith re-normalizes anyway, and
// it is the only place that can attach the disclosure gaps to the returned envelope; if the
// entry stripped first, runWith would see an already-clean waist and the substitution would
// go unreported on exactly the live path that matters.
function parseEntryArgs(raw) {
  const entry = entryArgs(raw);
  if (!entry.ok) throw new Error(entry.envelope.error);
  // The FULLY unwrapped object, not a fresh JSON.parse: entryArgs already peeled to it, and
  // re-parsing here would duplicate that work and re-open the depth coupling unwrapWaist
  // exists to close.
  return entry.waist;
}

function validateArgs(args) {
  const errors = [];
  if (!args || typeof args !== 'object') return { ok: false, errors: ['args is not an object'] };
  if (args.argsVersion !== ARGS_VERSION) errors.push(`unsupported argsVersion ${args.argsVersion} (expected ${ARGS_VERSION})`);
  for (const k of REQUIRED) if (args[k] === undefined) errors.push(`missing required field: ${k}`);
  if (args.mode && !['interactive', 'headless'].includes(args.mode)) errors.push(`invalid mode: ${args.mode}`);
  // Only charset-check a present nonce (absence is already a REQUIRED error above).
  if (args.nonce !== undefined && (typeof args.nonce !== 'string' || !NONCE_RE.test(args.nonce))) {
    errors.push(`invalid nonce: must match ${NONCE_RE} (AST-safe, non-splitting — interpolated into the verify command argv per slice)`);
  }
  // Path-bearing waist fields (requirement 6, issue #27). Per-field reachability:
  //   - outputDir / headShaShort → shared-context path
  //     (`${outputDir}/code-gauntlet-context-${headShaShort}.md`, built in stages.js), which
  //     reaches every discovery prompt
  //   - headShaShort / diffPath → verify executor argv (--head-sha, --diff-file) — the same
  //     argv-splitting hazard NONCE_RE already guards against above
  //   - repoRoot → provenance-only, unread by every stage (see REQUIRED at the top of this
  //     file); absolute-shape-checked for honesty of the skill's stamp
  // A present-but-garbage value on a consumed path field would otherwise render a junk path
  // into every paid dispatch instead of failing here, at the waist. Absence is already a
  // REQUIRED-field error above; these fire only when the field is PRESENT.
  // outputDir and repoRoot must be absolute: the waist rejects a non-absolute value rather
  // than resolving it (the workflow has no reliable cwd). Phase 1's ensure_output_dir.py is
  // the only layer that resolves outputDir; absolute here means a POSIX `/`-prefix — the
  // rest of the tree does not honor Windows drive paths, so inventing that support in a
  // guard nothing else honors would be dishonest. No existence / isDirectory probe: the
  // waist validates shape, not filesystem state. The skill stamps
  // `git rev-parse --show-toplevel`, the absolute output dir from ensure_output_dir.py,
  // `git rev-parse --short=8 HEAD`, and a `{output_dir}/….patch` path.
  const PATH_CONTROL_RE = /[\u0000-\u001F\u007F]/;
  for (const field of ['repoRoot', 'outputDir', 'headShaShort', 'diffPath']) {
    const v = args[field];
    if (v === undefined) continue;
    if (typeof v !== 'string' || v.trim() === '') {
      errors.push(`${field} must be a non-empty string when present`);
      continue;
    }
    if (PATH_CONTROL_RE.test(v)) {
      errors.push(`${field} must not contain a control character`);
      continue;
    }
    // headShaShort reaches the verify executor's --head-sha argv (verifyCommand). Path
    // fields are quoted at that construction site (issue #75) because a legitimate path
    // may hold a space; a real short SHA never needs one, and never needs `;`, `$` or a
    // backtick either — so the waist keeps it to the same AST-safe charset NONCE_RE
    // already enforces above, and the command carries it as a bare word.
    if (field === 'headShaShort' && !NONCE_RE.test(v)) {
      errors.push(`headShaShort must match ${NONCE_RE} (AST-safe, non-splitting — interpolated into the verify command argv)`);
    }
    // Issues #86 / #81: reject relative outputDir / repoRoot. Fail loud — do not resolve;
    // do not probe the filesystem (shape only; repoRoot is unread provenance).
    if ((field === 'outputDir' || field === 'repoRoot') && !v.startsWith('/')) {
      errors.push(`${field} must be an absolute path (POSIX /-prefix)`);
    }
  }
  // Single authority (issue #24 req 4, PR3): the orchestrator-stamped `agentFlags` path is
  // RETIRED, not left as a second half-authority alongside riskTable/scopeAnswer. A caller
  // that still stamps agentFlags is a stale producer (an un-migrated skill build, a bench
  // fixture) — refuse loud rather than silently honour or silently ignore its scope intent.
  if (args.agentFlags !== undefined) {
    errors.push('agentFlags is no longer accepted — the pipeline derives dimension flags itself from riskTable/scopeAnswer (issue #24). Stamp riskTable (the Phase 2e per-file risk classification) and, only when the light/full gate asked, scopeAnswer; do not stamp agentFlags.');
  }
  // riskTable is the orchestrator's Phase 2e per-file risk classification, REQUIRED (see
  // REQUIRED above) so deriveAgentFlags (stages.js) has a deterministic input instead of a
  // hand-stamped agentFlags map. Malformed or missing NEVER silently resolves to full scope —
  // it refuses the run (req 2). The path set must equal changedFiles' set EXACTLY: a missing
  // path means a file was reviewed with no risk classification (silently under-scoped), an
  // extra path means the table describes a file that was not in the diff (stale/wrong table).
  if (args.riskTable !== undefined) {
    if (!Array.isArray(args.riskTable)) {
      errors.push('riskTable must be an array of {path, risk} objects');
    } else {
      const seenPaths = new Set();
      for (let i = 0; i < args.riskTable.length; i++) {
        const entry = args.riskTable[i];
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
          errors.push(`riskTable[${i}] must be an object of the form {path, risk}`);
          continue;
        }
        const keys = Object.keys(entry).sort();
        const extra = keys.filter((k) => k !== 'path' && k !== 'risk');
        if (extra.length > 0) {
          errors.push(`riskTable[${i}] has unexpected key(s): ${extra.join(', ')} (only path and risk are allowed)`);
        }
        if (typeof entry.path !== 'string' || entry.path === '') {
          errors.push(`riskTable[${i}].path must be a non-empty string`);
        } else {
          seenPaths.add(entry.path);
        }
        if (!RISK_LEVELS.includes(entry.risk)) {
          errors.push(`riskTable[${i}].risk must be one of ${RISK_LEVELS.join(', ')} (got ${JSON.stringify(entry.risk)})`);
        }
      }
      if (Array.isArray(args.changedFiles)) {
        const changedSet = new Set(args.changedFiles);
        const missing = args.changedFiles.filter((p) => !seenPaths.has(p));
        const extraPaths = [...seenPaths].filter((p) => !changedSet.has(p));
        if (missing.length > 0) {
          errors.push(`riskTable is missing risk classification for changed file(s): ${missing.join(', ')}`);
        }
        if (extraPaths.length > 0) {
          errors.push(`riskTable classifies file(s) not present in changedFiles: ${extraPaths.join(', ')}`);
        }
      }
    }
  }
  // scopeAnswer: the light/full answer, echoed ONLY when the trivial-scope gate actually
  // asked (absent otherwise — see NULL_TOLERANCE_CONSEQUENCE above for why a stamped null is
  // treated the same as absent here).
  if (args.scopeAnswer !== undefined && !SCOPE_ANSWERS.includes(args.scopeAnswer)) {
    errors.push(`invalid scopeAnswer: ${args.scopeAnswer} (expected one of ${SCOPE_ANSWERS.join(', ')})`);
  }
  // Fail-loud coherence (issue #24 req 4/5, PR3): scopeAnswer and riskTable/changedLines must
  // agree BEFORE dispatch, not merely be individually well-shaped. Both arms only evaluate once
  // riskTable/changedLines/scopeAnswer are themselves well-formed (the errors pushed above would
  // otherwise be duplicated by a garbage-in eligibility computation here).
  const riskTableWellFormed = Array.isArray(args.riskTable)
    && args.riskTable.every((e) => e && typeof e === 'object' && RISK_LEVELS.includes(e.risk) && typeof e.path === 'string' && e.path !== '');
  const scopeAnswerWellFormed = args.scopeAnswer === undefined || SCOPE_ANSWERS.includes(args.scopeAnswer);
  if (riskTableWellFormed && scopeAnswerWellFormed && typeof args.changedLines === 'number') {
    const lightEligible = computeLightEligible(args.riskTable, args.changedLines);
    if (args.scopeAnswer === 'light' && !lightEligible) {
      errors.push('scopeAnswer is "light" but the riskTable/changedLines are not light-eligible (not every file is low risk, or changedLines >= 50) — the orchestrator answered a light/full question the gate never asked');
    }
    if (lightEligible && args.scopeAnswer === undefined) {
      errors.push('riskTable/changedLines are light-eligible but scopeAnswer is missing — the light/full gate must have asked, and its answer must be stamped as scopeAnswer');
    }
  }
  // policy.provider drives which arm of registry.js's model resolution runs (full-ID pin
  // vs bare alias — see POLICY_PROVIDERS above for why a typo must not resolve silently).
  // Only the provider field is shape-checked here: tier/subagentModel predate this guard
  // and keep their existing tolerance. Absent provider means 'firstParty' (older waists).
  if (args.policy && typeof args.policy === 'object' && !Array.isArray(args.policy)
    && args.policy.provider !== undefined && args.policy.provider !== null
    && !POLICY_PROVIDERS.includes(args.policy.provider)) {
    errors.push(`invalid policy.provider: ${args.policy.provider} (expected one of ${POLICY_PROVIDERS.join(', ')})`);
  }
  // policy.gateway gates registry.js's conditionalSchemaActive (issue #218) — a non-boolean
  // would silently coerce (e.g. the string "false" is truthy), so shape-check it the same
  // way provider is above. Absent/null both mean "no gateway", same tolerance as provider.
  if (isPlainObject(args.policy)
    && args.policy.gateway !== undefined && args.policy.gateway !== null
    && typeof args.policy.gateway !== 'boolean') {
    errors.push(`invalid policy.gateway: ${args.policy.gateway} (expected a boolean)`);
  }
  // Type-check the consumed by-value fields (absence is already a REQUIRED error above).
  if (args.changedFiles !== undefined && !Array.isArray(args.changedFiles))
    errors.push('changedFiles must be an array of repo-relative paths');
  if (args.changedLines !== undefined && typeof args.changedLines !== 'number')
    errors.push('changedLines must be a number');
  // Optional shared-context file size, measured by the skill immediately after it writes
  // {output_dir}/code-gauntlet-context-{head_sha_short}.md. The workflow has no disk, so
  // this is the only path for it. contextReadPlan (stages.js) turns the pair into the
  // exact Read calls the discovery/validate/summarize prompts enumerate — issue #48,
  // where an unmeasurable file left the agent to guess whether it had read all of it.
  //
  // OPTIONAL and independently so. Not for old callers: SKILL.md is the only producer of
  // this waist (bench invokes the skill rather than assembling args) and it ships with the
  // bundle, so there is no real skew window. It is optional because Phase 2 is
  // MODEL-EXECUTED and can skip the measurement step in a live run, and hard-failing there
  // would trade a partial read for a dead review. runWith emits a context_unmeasured gap so
  // the degradation is disclosed rather than silent. Absent contextChars just means the
  // line cap binds the chunk size alone. Both are shape-checked when present, because a
  // zero/negative/fractional value would produce a plan that either misses the file's
  // tail or names a nonsense offset — a silent under-read is exactly what this exists to
  // prevent, so a malformed value fails loud at the waist instead.
  // The MAX bounds are memory safety, not taste. contextReadPlan allocates one entry per
  // chunk; handed Number.MAX_SAFE_INTEGER it OOM-kills the node process with a V8 fatal
  // error — uncatchable, so runWith's top-level catch never runs, no gap is recorded and
  // nothing is dispatched. contextReadPlan carries its own chunk ceiling as the last line
  // of defence; this is the fail-loud one, at the waist, where a nonsense measurement is
  // still attributable to the producer that stamped it.
  const CONTEXT_SIZE_MAX = { contextLines: 5000000, contextChars: 500000000 };
  for (const k of ['contextLines', 'contextChars']) {
    if (args[k] === undefined) continue;
    if (!Number.isSafeInteger(args[k]) || args[k] <= 0) {
      errors.push(`${k} must be a positive safe integer (the measured size of the shared context file) when present`);
    } else if (args[k] > CONTEXT_SIZE_MAX[k]) {
      errors.push(`${k} is ${args[k]}, above the ${CONTEXT_SIZE_MAX[k]} ceiling — that is not a review context, it is a mis-measurement`);
    }
  }
  if (args.contextChars !== undefined && args.contextLines === undefined) {
    errors.push('contextChars requires contextLines — chars alone cannot size a line-offset read plan');
  }
  // Optional reviewConfig (the parsed REVIEW.md shape, see parseReviewMd in
  // filterFindings.js). Its `ignore` list feeds escapeRegExp in the Filter stage, which
  // assumes flat strings — a session that assembles entries as {pattern, reason} objects
  // crashes there AFTER five paid stages (observed live, PR-310 run). Same
  // present-then-shape-checked pattern as `delivery`: absent is fine, malformed fails loud
  // at the waist before anything is dispatched.
  if (args.reviewConfig !== undefined) {
    if (args.reviewConfig === null || typeof args.reviewConfig !== 'object' || Array.isArray(args.reviewConfig)) {
      errors.push('reviewConfig must be an object (the parseReviewMd output shape) when present');
    } else if (args.reviewConfig.ignore !== undefined) {
      if (!Array.isArray(args.reviewConfig.ignore)) {
        errors.push('reviewConfig.ignore must be an array of flat pattern strings');
      } else {
        for (let i = 0; i < args.reviewConfig.ignore.length; i++) {
          if (typeof args.reviewConfig.ignore[i] !== 'string') {
            errors.push(`reviewConfig.ignore[${i}] must be a flat pattern string (got ${typeof args.reviewConfig.ignore[i]}) — parseReviewMd emits strings, never objects`);
          }
        }
      }
    }
  }
  // Optional exclusionPatterns (the parsed exclusion-pattern list threaded alongside
  // reviewConfig). It feeds the same escapeRegExp path as reviewConfig.ignore — both are
  // concatenated in applyFilterPipeline (filterFindings.js) before the Filter stage builds
  // its regexes — so it is exposed to the same crash class (same live-run L2) and gets the
  // identical present-then-shape-checked treatment: absent is fine, malformed fails loud.
  if (args.exclusionPatterns !== undefined) {
    if (!Array.isArray(args.exclusionPatterns)) {
      errors.push('exclusionPatterns must be an array of flat pattern strings');
    } else {
      for (let i = 0; i < args.exclusionPatterns.length; i++) {
        if (typeof args.exclusionPatterns[i] !== 'string') {
          errors.push(`exclusionPatterns[${i}] must be a flat pattern string (got ${typeof args.exclusionPatterns[i]})`);
        }
      }
    }
  }
  // Optional reviewMd (issue #24 PR2): the raw, ORDERED discovery of REVIEW.md files —
  // root-first, increasing directory depth — as [{path, text}]. This is the RAW-text
  // counterpart to the pre-parsed `reviewConfig` above: resolveReviewConfig (below) turns it
  // into the same shape reviewConfig has always had by calling parseReviewMd per entry and
  // merging in array order. An empty array is a legal, authoritative "discovery ran and found
  // nothing" signal — distinct from the field being absent entirely (see resolveReviewConfig's
  // reviewConfigSource). `path` is repo-relative (must NOT start with '/', the opposite
  // convention from repoRoot/outputDir above, which must) and reuses PATH_CONTROL_RE below via
  // a local copy since this guard runs before that regex is declared in file order... — see
  // REVIEW_MD_PATH_CONTROL_RE just below, same pattern.
  if (args.reviewMd !== undefined) {
    if (!Array.isArray(args.reviewMd)) {
      errors.push('reviewMd must be an array of {path, text} objects when present');
    } else {
      for (let i = 0; i < args.reviewMd.length; i++) {
        const entry = args.reviewMd[i];
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
          errors.push(`reviewMd[${i}] must be an object of the form {path, text}`);
          continue;
        }
        const keys = Object.keys(entry).sort();
        const extra = keys.filter((k) => k !== 'path' && k !== 'text');
        if (extra.length > 0) {
          errors.push(`reviewMd[${i}] has unexpected key(s): ${extra.join(', ')} (only path and text are allowed)`);
        }
        if (typeof entry.path !== 'string' || entry.path === '') {
          errors.push(`reviewMd[${i}].path must be a non-empty string`);
        } else {
          if (REVIEW_MD_PATH_CONTROL_RE.test(entry.path)) {
            errors.push(`reviewMd[${i}].path must not contain a control character`);
          }
          if (entry.path.startsWith('/')) {
            errors.push(`reviewMd[${i}].path must be repo-relative (must not start with /)`);
          }
        }
        if (typeof entry.text !== 'string') {
          errors.push(`reviewMd[${i}].text must be a string`);
        }
      }
    }
  }
  // Optional exclusionsText (issue #24 PR2): the raw text of whatever exclusions source the
  // skill discovered (e.g. .reviewignore), consumed by loadExclusions (filterFindings.js) in
  // resolveReviewConfig below. Empty string is legal (an exclusions file that exists but is
  // empty).
  if (args.exclusionsText !== undefined && typeof args.exclusionsText !== 'string') {
    errors.push('exclusionsText must be a string when present');
  }
  // Single-authority guards (issue #24 req 4 analog): a caller must pass EITHER the raw
  // discovery (reviewMd/exclusionsText) OR the pre-parsed shape (reviewConfig/
  // exclusionPatterns), never both for the same axis — two authorities for one piece of
  // config is exactly the silent-substitution hazard this waist exists to refuse loudly.
  if (args.reviewMd !== undefined && args.reviewConfig !== undefined) {
    errors.push('reviewMd and reviewConfig are both present — pass raw reviewMd or pre-parsed reviewConfig, not both (single authority)');
  }
  if (args.exclusionsText !== undefined && args.exclusionPatterns !== undefined) {
    errors.push('exclusionsText and exclusionPatterns are both present — pass raw exclusionsText or pre-parsed exclusionPatterns, not both (single authority)');
  }
  // Optional delivery selector. Absence is fine; when present it must be an object, and a
  // present tier must be a known value — an unknown tier would otherwise fall through to the
  // 'all' default in selectDelivery, silently ignoring an operator's narrowing intent.
  if (args.delivery !== undefined) {
    if (args.delivery === null || typeof args.delivery !== 'object' || Array.isArray(args.delivery)) {
      errors.push('delivery must be an object of the form { tier } when present');
    } else {
      if (args.delivery.tier !== undefined && !DELIVERY_TIERS.includes(args.delivery.tier)) {
        errors.push(`invalid delivery.tier: ${args.delivery.tier} (expected one of ${DELIVERY_TIERS.join(', ')})`);
      }
      // Optional PR identity (live-run L3): when present, the artifact-writer persists the
      // post_review-ready wrapper { owner, repo, pr_number, sha, review_body, findings }
      // instead of the bare findings array — Phase 8 consumes it without hand-assembly.
      // ABSENT for local-diff reviews (the waist stays target-agnostic).
      const id = args.delivery.prIdentity;
      if (id !== undefined) {
        if (id === null || typeof id !== 'object' || Array.isArray(id)) {
          errors.push('delivery.prIdentity must be an object { owner, repo, pr_number, sha_full[, title] } when present');
        } else {
          if (typeof id.owner !== 'string' || !id.owner) errors.push('delivery.prIdentity.owner must be a non-empty string');
          if (typeof id.repo !== 'string' || !id.repo) errors.push('delivery.prIdentity.repo must be a non-empty string');
          if (typeof id.pr_number !== 'number') errors.push('delivery.prIdentity.pr_number must be a number');
          if (typeof id.sha_full !== 'string' || !id.sha_full) errors.push('delivery.prIdentity.sha_full must be a non-empty string');
          if (id.title !== undefined && (typeof id.title !== 'string' || !id.title.trim())) {
            errors.push('delivery.prIdentity.title must be a non-empty string when present');
          }
        }
      }
    }
  }
  // Optional persist waist (issue #38, D3.4): { assembleScriptPath }. When present, the
  // artifact-writer persists only the UNIQUE content (findings.json, report.md, the
  // persist plan) and the executor runs that script to DERIVE the post-review and
  // checkpoint artifacts on disk. When ABSENT, writeArtifacts takes the legacy full
  // by-value path and records no gap — a clean, documented degradation for older callers
  // (bench included). Same present-then-shape-checked pattern as `delivery`: a malformed
  // object fails loud at the waist rather than mid-persist, after every paid stage.
  // (A literal `persist: null` never reaches here — it is on NULLABLE_TOP_LEVEL and is
  // dropped, and disclosed, by stripNullOptionalsReport. The `=== null` arm below is the
  // guard for a caller that skipped normalization entirely.)
  if (args.persist !== undefined) {
    if (args.persist === null || typeof args.persist !== 'object' || Array.isArray(args.persist)) {
      errors.push('persist must be an object of the form { assembleScriptPath, returnPrimaries } when present');
    } else {
      if (args.persist.assembleScriptPath !== undefined
        && (typeof args.persist.assembleScriptPath !== 'string' || !args.persist.assembleScriptPath)) {
        errors.push('persist.assembleScriptPath must be a non-empty string path to scripts/assemble_artifacts.py');
      }
      // `returnPrimaries: true` routes the primaries home in the workflow's RETURN instead
      // of through the artifact-writer's transcription, and Phase 8 materializes them with
      // scripts/materialize_artifacts.py. It is checked for a BOOLEAN rather than
      // truthiness because writeArtifacts gates on `=== true`: a caller that stamped the
      // string "false" would otherwise read as opting in here and out there.
      if (args.persist.returnPrimaries !== undefined && typeof args.persist.returnPrimaries !== 'boolean') {
        errors.push('persist.returnPrimaries must be a boolean when present');
      }
    }
  }
  // limits (REQUIRED — see REQUIRED above; the skill always stamps {} at worst, and
  // normalizeArgs fills the LIMIT_DEFAULTS keys before validateArgs ever runs on a
  // real waist). Every OTHER key is a hard error: issue #24's motivating incident was a
  // silent typo (`verifySclieSize: 50`) that never reached the stage it was meant to size
  // and just as silently fell back to a different default — this closes that class by
  // refusing any key this waist does not know about, rather than ignoring it.
  const LIMIT_KEYS = ['summarizeBucketSize', 'validateBatch', 'challengeCap', 'verifySliceSize', 'deliveryCap', 'discoveryCap', 'maxLineSpan'];
  if (args.limits !== undefined) {
    if (args.limits === null || typeof args.limits !== 'object' || Array.isArray(args.limits)) {
      errors.push('limits must be an object when present');
    } else {
      for (const k of Object.keys(args.limits)) {
        if (!LIMIT_KEYS.includes(k)) errors.push(`unknown limits key: ${k} (expected one of ${LIMIT_KEYS.join(', ')})`);
      }
      // summarizeBucketSize / validateBatch / verifySliceSize / maxLineSpan: positive safe
      // integers — a zero or negative bucket/batch/slice size would divide the work into an
      // infinite (or negative-length) number of dispatches. maxLineSpan (issue #204): the
      // effective-limit accessor's `||` fallback treats a falsy 0 as absent and silently
      // substitutes the default, so an unvalidated 0 would be confusingly overridden rather
      // than honored — refuse it here instead.
      for (const k of ['summarizeBucketSize', 'validateBatch', 'verifySliceSize', 'maxLineSpan']) {
        const v = args.limits[k];
        if (v !== undefined && (!Number.isSafeInteger(v) || v <= 0)) {
          errors.push(`limits.${k} must be a positive safe integer when present`);
        }
      }
      // challengeCap: non-negative safe integer — 0 is a real, legal cap ("challenge
      // nothing"; effectiveChallengeCap/challengeStage both honor it).
      if (args.limits.challengeCap !== undefined
        && (!Number.isSafeInteger(args.limits.challengeCap) || args.limits.challengeCap < 0)) {
        errors.push('limits.challengeCap must be a non-negative safe integer when present');
      }
      // deliveryCap: absent, null (uncapped — a meaningful value, not a default-pending
      // hole; see LIMIT_DEFAULTS above), or a non-negative safe integer.
      if (args.limits.deliveryCap !== undefined && args.limits.deliveryCap !== null
        && (!Number.isSafeInteger(args.limits.deliveryCap) || args.limits.deliveryCap < 0)) {
        errors.push('limits.deliveryCap must be null, absent, or a non-negative safe integer when present');
      }
      // discoveryCap: absent or a positive safe integer (no null form — unlike
      // deliveryCap, discoveryCap's absence alone already means "no per-agent ceiling").
      if (args.limits.discoveryCap !== undefined
        && (!Number.isSafeInteger(args.limits.discoveryCap) || args.limits.discoveryCap <= 0)) {
        errors.push('limits.discoveryCap must be a positive safe integer when present');
      }
    }
  }
  return { ok: errors.length === 0, errors };
}

// resolveReviewConfig(A) -> { reviewConfig, exclusionPatterns, reviewConfigSource,
// exclusionsSource, reviewMdEntryCount } (issue #24 PR2 / #80).
//
// A strict SUPERSET of today's behavior: when A.reviewMd/A.exclusionsText are absent this
// resolves to exactly A.reviewConfig/A.exclusionPatterns as before (req 8 backward compat —
// bench children and older invocation shapes are unaffected). validateArgs above already
// refuses a waist that stamps BOTH the raw and pre-parsed form for the same axis, so at most
// one of each pair is ever present here.
//
// reviewMd entries are stably sorted by path depth ascending (root first, ties keep their
// original relative order) BEFORE merging — "deeper wins" is a code guarantee here, not a
// promise the caller's discovery order happens to keep. Per
// skills/code-gauntlet/references/review-md-spec.md: a later (deeper) entry's threshold
// SETTING overrides an earlier one's when both set it; `ignore` lists ACCUMULATE across every
// entry, in post-sort order. Absent settings are never defaulted here — parseReviewMd only
// stamps a key when the text actually set it (see its own doc comment), and this merge
// preserves that: a setting neither entry set stays `undefined` so applyThresholdFilter's own
// config-absent 55/70 split (filterFindings.js) still applies.
//
// reviewConfigSource and exclusionsSource are two INDEPENDENT provenance signals, one per
// axis — 'reviewMd' when A.reviewMd was present (even an empty array: discovery ran and found
// nothing is still authoritative) / 'exclusionsText' when A.exclusionsText was present;
// 'preParsed' when the axis's pre-parsed field (A.reviewConfig / A.exclusionPatterns) was
// present instead; 'none' when neither form of that axis was supplied. A mixed waist (one axis
// raw, the other pre-parsed) is legal transition back-compat and reports one label per axis
// accordingly — the two never need to agree.
function pathDepth(entry) {
  const p = (entry && entry.path) || '';
  return p.split('/').length;
}

function resolveReviewConfig(A) {
  const a = A || {};
  const reviewConfigSource = a.reviewMd !== undefined ? 'reviewMd'
    : (a.reviewConfig !== undefined ? 'preParsed' : 'none');
  const exclusionsSource = a.exclusionsText !== undefined ? 'exclusionsText'
    : (a.exclusionPatterns !== undefined ? 'preParsed' : 'none');

  let reviewConfig;
  let reviewMdEntryCount = 0;
  if (a.reviewMd !== undefined) {
    const sorted = a.reviewMd
      .map((entry, index) => ({ entry, index }))
      .sort((x, y) => (pathDepth(x.entry) - pathDepth(y.entry)) || (x.index - y.index))
      .map((wrapped) => wrapped.entry);
    const merged = { ignore: [] };
    for (const entry of sorted) {
      const parsed = parseReviewMd(entry && entry.text);
      if (parsed.confidence_threshold !== undefined) merged.confidence_threshold = parsed.confidence_threshold;
      if (parsed.security_min_confidence !== undefined) merged.security_min_confidence = parsed.security_min_confidence;
      if (parsed.severity_threshold !== undefined) merged.severity_threshold = parsed.severity_threshold;
      merged.ignore.push(...parsed.ignore);
    }
    reviewConfig = merged;
    reviewMdEntryCount = a.reviewMd.length;
  } else {
    reviewConfig = a.reviewConfig || {};
  }

  const exclusionPatterns = a.exclusionsText !== undefined ? loadExclusions(a.exclusionsText)
    : (a.exclusionPatterns || []);

  return { reviewConfig, exclusionPatterns, reviewConfigSource, exclusionsSource, reviewMdEntryCount };
}

// --- stages.js ---
// stages.js — orchestration stage functions for the code-gauntlet v3 pipeline: all eight
// stages (Summarize -> Discover -> Merge -> Verify -> Validate -> Filter -> Challenge ->
// Report), persistence, checkpoints and the runWith orchestrator, plus the agent-count
// coarsening formula that keeps the whole run's worst-case fan-out under the platform guard.
//
// Every stage takes an injected `ctx` ({ agent, parallel }) so unit tests can drive
// it with a mock (the runtime globals do not exist under node:test). Defaults fall
// back to the runtime globals when present, so the shipped bundle needs no wiring.
//
// Failure contract (Phase 0): bare agent() THROWS on schema-retry-exhaustion (cap 5)
// and unknown agentType; parallel() converts a failed member to null. So single agent()
// calls are wrapped in try/catch. Null members are NOT handled uniformly: discover,
// validate and challenge keep the results positionally aligned and push a NAMED gap per
// null member, because a degraded member must be traceable to the exact work it dropped
// (see validateStage's header). Summarize is the exception — it .filter(Boolean)s null
// bucket members without per-bucket gaps, and emits one generic gap if no partial
// survives, the merge or single-call result is null, or any summarize dispatch throws.
// No wall-clock, no import at runtime.

// Runtime globals are injected by the workflow host; under node:test they are absent,
// so ctx must be supplied. defaultCtx lets the shipped pipeline call stages without wiring.
function defaultCtx() {
  return {
    agent: typeof agent === 'function' ? agent : undefined,
    parallel: typeof parallel === 'function' ? parallel : undefined,
    pipeline: typeof pipeline === 'function' ? pipeline : undefined,
  };
}

// Resolve the dispatch model for an agent type from the args-waist policy object —
// the single place the policy shape maps onto resolvePolicy's opts.
function modelFor(agentType, policy) {
  return resolvePolicy(agentType, { subagentModelEnv: policy.subagentModel, provider: policy.provider }).model;
}

// Shared char budget for a single agent's by-value PROMPT payload. Above it, verify
// slice-input writing segments into multiple dispatches to stay under the receiving
// agent's context.
//
// It does NOT bound the workflow's RETURN — that is RETURN_CHAR_BUDGET below. One
// constant used to do both jobs, the second by analogy with the first, and the analogy
// is false: a prompt is read by a model and a return is serialized by the harness, so
// the two have neither the same limit nor the same failure mode. Three recorded runs
// threw their resume state away against a ceiling that was never measured for it.
const PROMPT_SEGMENT_CHAR_BUDGET = 100000;

// Char budget for the workflow's RETURN value — the object the HARNESS serializes to
// `tasks/<taskid>.output`. Measured 2026-07-30 with a zero-subagent probe: the on-disk
// file was byte-exact against the requested string at 200,000, 500,000 and 4,000,000
// chars (fnv1a32 match at each, including a lone surrogate left by slicing an emoji in
// half), in 18-122 ms. No ceiling was found at 4 MB.
//
// 1,000,000 is a quarter of the largest proven size, and ~15x the largest run ever
// recorded (findings 6.8-53 KB across 14 runs, report <=13.5 KB, so ~66 KB of unique
// content at the top end). It is a guard against a pathological run, not a limit anyone
// is expected to reach; the return channel falls back to the artifact-writer above it.
const RETURN_CHAR_BUDGET = 1000000;

// --- Shared context file: the deterministic read plan (issue #48) ---------------
//
// A `Read` returns only PART of a large file and says nothing about it. Measured on
// run wf_cef39739-577: all 7 discovery agents' first Read of the 95,057-byte /
// 2,028-line shared context file returned 58,145 chars ending at line 1083, with no
// truncation notice in ANY of the 7 tool results. Six agents inferred the cutoff and
// paginated on; security-reviewer did not, and reviewed roughly the first half of the
// diff while reporting as if it had seen all of it.
//
// The fix is arithmetic, not instruction. The skill stamps the file's size
// (contextLines/contextChars, measured after it writes the file); these helpers turn
// that into the EXACT list of Read calls that covers it, and the prompt enumerates
// them. The agent's job is "make these listed calls", not "notice an invisible
// truncation and drive a loop" — a judgment it demonstrably gets wrong 1 time in 7.
//
// Both bounds below are observed platform behavior, not a documented contract, so the
// planner stays well under each: the Read tool documents a 2,000-line default cap, and
// the run above puts a character cap near 58,000. A plan chunk is sized by whichever
// binds first, from the stamped chars-per-line.
const READ_PLAN_MAX_LINES = 750;
const READ_PLAN_MAX_CHARS = 30000;
// Above this many chunks, the prompt states the plan as its generating rule (first
// offset, span, final line) instead of listing every call — identical information,
// bounded prompt size. Four chunks covers the profiled file; the rule form is for
// pathological inputs (very many very short lines), never the normal path.
const READ_PLAN_MAX_ENUMERATED = 10;
// Hard ceiling on the plan's SIZE, checked before a single element is allocated. Without
// it the loop below allocates one object per chunk for whatever `lines` it is handed, and
// the waist accepts any positive safe integer: contextLines = Number.MAX_SAFE_INTEGER
// OOM-kills the node process — a V8 fatal error, not a catchable throw, so runWith's
// top-level catch never runs, no gap is recorded, and nothing is dispatched. 2000 chunks
// covers a 1.5M-line context file; past that the plan degrades to the count-free
// read-to-end wording, because a review context that large is already beyond triage.
const READ_PLAN_MAX_CHUNKS = 2000;

// contextReadPlan(lines, chars) -> [{ offset, limit }, ...] covering lines 1..lines.
// PURE arithmetic. Offsets are 1-based to match the Read tool's `cat -n` numbering
// (the profiled agents' own follow-up Reads used 1-based offsets). An unusable or
// absent line count yields [] — the caller then falls back to the count-free wording
// rather than emitting a plan built from a guess.
function contextReadPlan(lines, chars) {
  const total = Number.isSafeInteger(lines) && lines > 0 ? lines : 0;
  if (total === 0) return [];
  // Chars is advisory: absent/unusable just means the line cap binds alone.
  const perLine = Number.isSafeInteger(chars) && chars > 0 ? chars / total : 0;
  const byChars = perLine > 0 ? Math.floor(READ_PLAN_MAX_CHARS / perLine) : READ_PLAN_MAX_LINES;
  const span = Math.max(1, Math.min(READ_PLAN_MAX_LINES, byChars));
  // Bound the ALLOCATION, not just the input: computed before the loop so an absurd size
  // degrades instead of exhausting the heap (see READ_PLAN_MAX_CHUNKS).
  if (Math.ceil(total / span) > READ_PLAN_MAX_CHUNKS) return [];
  const plan = [];
  for (let offset = 1; offset <= total; offset += span) {
    plan.push({ offset, limit: Math.min(span, total - offset + 1) });
  }
  return plan;
}

// sharedContextLine(inp) -> the leading context-read sentence, or '' when no context
// path was threaded. Called ONCE, by runWith, which threads the resulting STRING to the
// stages that need it. The stages never receive the path, so no stage is ABLE to build a
// context-read instruction of its own — the property that used to be defended by scanning
// this file's source text for hand-rolled copies. Capability removed rather than guarded:
// an adversarial review defeated the text-scan version in one edit by rewording.
function sharedContextLine(inp) {
  const path = inp && inp.contextPath;
  if (!path) return '';
  const head = `Read the shared context at ${path} first — it has the diff, project rules, and risk classification.`;
  // A partial Read is INVISIBLE: it carries no truncation notice and looks exactly
  // like a complete file. Stated on every path, plan or no plan.
  const warn = 'A single Read of this file returns only PART of it and gives NO truncation notice, so one Read is never the whole file.';
  const prefix = `${head} ${warn}`;
  const plan = contextReadPlan(inp.contextLines, inp.contextChars);
  if (plan.length === 0) {
    // No measurement (or one too large to plan): the terminus is unknown, so end-detection
    // is unavoidable here. The STEPPING still is not — spelling out fixed-size steps keeps
    // the only judgment "did that call return anything", instead of the open-ended "have I
    // read enough yet" that issue #48 records an agent answering wrong.
    const s = READ_PLAN_MAX_LINES;
    return `${prefix} Read it in ${s}-line steps — Read(offset=1, limit=${s}), then Read(offset=${1 + s}, limit=${s}), then Read(offset=${1 + 2 * s}, limit=${s}), continuing to step by ${s} until a call returns no further content. Do not stop before that. `;
  }
  const total = inp.contextLines;
  if (plan.length === 1) {
    return `${prefix} It is ${total} lines: read it with Read(offset=1, limit=${plan[0].limit}), and if that call does not reach line ${total}, continue with offset set past the last line you received until it does. `;
  }
  const tail = `Make ALL of them — stopping early means you review only the part you saw. If any call does not land where the plan says, continue with offset set past the last line you received until you reach line ${total}.`;
  if (plan.length <= READ_PLAN_MAX_ENUMERATED) {
    const calls = plan.map((p) => `Read(offset=${p.offset}, limit=${p.limit})`).join(', ');
    return `${prefix} It is ${total} lines, which takes exactly ${plan.length} Read calls: ${calls}. ${tail} `;
  }
  const span = plan[0].limit;
  return `${prefix} It is ${total} lines, which takes exactly ${plan.length} Read calls of limit=${span}, at offsets 1, ${1 + span}, ${1 + 2 * span}, … stepping by ${span} through line ${total}. ${tail} `;
}

// Greedy pack: accumulate items into a chunk until adding the next would exceed
// `budget` serialized chars, then start a new chunk. A single oversized item still
// goes in a chunk of its own (never dropped). Used by verify slice-input writing.
function chunkBySerializedSize(items, budget) {
  const chunks = [];
  let cur = [];
  let curSize = 0;
  for (const it of items) {
    const size = JSON.stringify(it).length;
    if (cur.length && curSize + size > budget) {
      chunks.push(cur);
      cur = [];
      curSize = 0;
    }
    cur.push(it);
    curSize += size;
  }
  if (cur.length) chunks.push(cur);
  return chunks.length ? chunks : [[]];
}

// --- Phase 1: Summarize -----------------------------------------------------

// The change-summarizer returns its prose wrapped as { summary } (StructuredOutput).
const SUMMARIZE_SCHEMA = { type: 'object', properties: { summary: { type: 'string' } }, required: ['summary'] };

// summarize(ctx, input) -> { summary, gaps }
// Small PRs: one change-summarizer agent() call. Large PRs (>500 changed lines that
// also span more files than one bucket): fan out per-file buckets of
// limits.summarizeBucketSize through parallel(), then a single merge agent() call to
// stitch the partials. Any throw / total null-out degrades to { summary:'', gaps:[...] }.
async function summarize(ctx, input) {
  const c = ctx || defaultCtx();
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const changedFiles = inp.changedFiles || [];
  const changedLines = inp.changedLines || 0;
  const limits = inp.limits || {};
  const policy = inp.policy || {};
  const bucketSize = effectiveBucketSize(limits);
  const model = modelFor('code-gauntlet:change-summarizer', policy);

  const bucketed = changedLines > 500 && changedFiles.length > bucketSize;
  try {
    if (bucketed) {
      const buckets = [];
      for (let i = 0; i < changedFiles.length; i += bucketSize) buckets.push(changedFiles.slice(i, i + bucketSize));
      // parallel() takes thunks; each calls agent(promptString, opts).
      const thunks = buckets.map((files, idx) => () => c.agent(summarizePrompt(inp, files), {
        label: `summarize-bucket-${idx}`,
        agentType: 'code-gauntlet:change-summarizer',
        model,
        schema: SUMMARIZE_SCHEMA,
      }));
      const partials = (await c.parallel(thunks)).filter(Boolean);
      if (partials.length === 0) return { summary: '', gaps: ['summarize failed'] };
      const mergeResult = await c.agent(summarizeMergePrompt(inp, partials), {
        label: 'summarize-merge',
        agentType: 'code-gauntlet:change-summarizer',
        model,
        schema: SUMMARIZE_SCHEMA,
      });
      if (!mergeResult) return { summary: '', gaps: ['summarize failed'] };
      return { summary: mergeResult.summary || '', gaps: [] };
    }
    const result = await c.agent(summarizePrompt(inp, changedFiles), {
      label: 'summarize',
      agentType: 'code-gauntlet:change-summarizer',
      model,
      schema: SUMMARIZE_SCHEMA,
    });
    if (!result) return { summary: '', gaps: ['summarize failed'] };
    return { summary: result.summary || '', gaps: [] };
  } catch {
    return { summary: '', gaps: ['summarize failed'] };
  }
}

function summarizePrompt(inp, files) {
  // Prebuilt by runWith (issue #48): the summarizer opens the SAME file the discovery
  // agents do, so it gets the same read plan. This stage cannot construct one — it never
  // sees the context path.
  const ctxLine = inp.contextLine || '';
  // Single-source the size number (live-run L7): triage said 1211 changed lines, the
  // report said ~1218 because the summarizer re-derived it from the diff. The waist's
  // changedLines is the one authoritative count.
  const countLine = typeof inp.changedLines === 'number' && inp.changedLines > 0
    ? ` The authoritative changed-line count is ${inp.changedLines}; cite that number verbatim if you mention change size — never re-estimate it from the diff.`
    : '';
  return `${ctxLine}Summarize the semantic intent of these changed files for downstream reviewers: ${files.join(', ')}.${countLine} Return { summary }.`;
}

// The merge call produces the FINAL summary on the bucketed path, so it needs the same
// changedLines pin as summarizePrompt — without it the merge step can re-drift the size
// number the per-bucket prompts were pinned to (Bugbot PR-20 wave 2).
function summarizeMergePrompt(inp, partials) {
  const joined = partials.map((p) => p.summary || '').filter(Boolean).join('\n---\n');
  const countLine = typeof inp.changedLines === 'number' && inp.changedLines > 0
    ? ` The authoritative changed-line count is ${inp.changedLines}; cite that number verbatim if you mention change size — never re-estimate it.`
    : '';
  return `Combine these per-bucket change summaries into one concise semantic summary.${countLine} Partials:\n${joined}\nReturn { summary }.`;
}

// --- Phase 2: Discover ------------------------------------------------------

// intersectRequiredExtra(rows) -> string[] (issue #66). The safe algebra for a multi-dimension
// agent's effective requiredExtra: a field is dispatch-required only if EVERY row (dimension)
// sharing that agent's one dispatch requires it. Union semantics would be unsafe — promoting a
// single-dimension's required field (e.g. a hypothetical convention-only requirement) onto the
// whole conventions-and-intent dispatch would reject every intent/comment_accuracy finding that
// correctly omits it. Order-independent (sorted) so the result never depends on DIMENSIONS row
// iteration order. Exported standalone so the intersection can be exercised with synthetic rows
// without needing to mutate the module-level registry.
//
// registry.test.js's sibling-parity test ("rows sharing an agentType declare identical
// requiredExtra sets") is the actual AUTHORITY that keeps this safe on the real registry: it
// fails the build the moment a multi-dimension agent's rows disagree, so on a healthy tree this
// intersection is an IDENTITY (every sibling already agrees, so nothing is ever actually
// dropped). This function is not what makes divergence safe — that guard is. It is the
// fail-safe ALGEBRA underneath: if a divergence somehow reached runtime anyway (a bypassed
// guard, a registry built by different code some day), the intersection still degrades safely
// — dropping the disputed field from `required` — instead of the union's failure mode, which
// would force every compliant OMIT-ing finding on a sibling dimension to fabricate a value it
// was correctly told to omit.
function intersectRequiredExtra(rows) {
  if (!rows || rows.length === 0) return [];
  let acc = new Set(rows[0].requiredExtra || []);
  for (const row of rows.slice(1)) {
    const next = new Set(row.requiredExtra || []);
    acc = new Set([...acc].filter((f) => next.has(f)));
  }
  return [...acc].sort();
}

// Group DIMENSIONS by agentType, unioning each agent's per-dimension schemaExtra into
// one finding schema. One task per unique AGENT (7) — agents covering several
// dimensions (conventions-and-intent -> convention/intent/comment_accuracy) dispatch once.
// `requiredExtra` on the returned spec is the INTERSECTION of that agent's rows' requiredExtra
// (intersectRequiredExtra above), not a union like schemaExtra — see the registry.js note on
// why a per-dimension required field cannot safely promote onto sibling dimensions.
//
// Takes `dims` (defaults to the module-level DIMENSIONS) so the intersection-through-grouping
// seam can be exercised with synthetic rows in tests, independent of the real registry. Agent
// order is derived from `dims` itself (`[...new Set(dims.map(d => d.agentType))]`), NOT from
// the module-level AGENTS constant — mapping over AGENTS here would look up entries by an
// agentType a synthetic `dims` never populated and return undefined specs. For the default
// call this produces the byte-identical order AGENTS already pins (see registry.test.js).
function agentSpecs(dims = DIMENSIONS) {
  const byAgent = new Map();
  for (const d of dims) {
    if (!byAgent.has(d.agentType)) byAgent.set(d.agentType, { agentType: d.agentType, dimensions: [], schemaExtra: {}, conditionalFlags: [], promptExtra: null, rows: [] });
    const spec = byAgent.get(d.agentType);
    spec.dimensions.push(d.dimension);
    Object.assign(spec.schemaExtra, d.schemaExtra || {});
    spec.conditionalFlags.push(d.conditionalFlag);
    spec.rows.push(d);
    // promptExtra is scoped per AGENT, not per dimension — every DIMENSIONS row for a
    // multi-dimension agent is expected to carry the same value (see registry.js), so a
    // truthy value on any of an agent's rows sets it for the whole spec.
    if (d.promptExtra) spec.promptExtra = d.promptExtra;
  }
  const order = [...new Set(dims.map((d) => d.agentType))];
  return order.map((a) => {
    const spec = byAgent.get(a);
    spec.requiredExtra = intersectRequiredExtra(spec.rows);
    // conditionalRequired (issue #218): one { dimension, required } entry per row that
    // declares a non-empty requiredWhenDimension, sorted by dimension so the derivation
    // never depends on DIMENSIONS row order. Defensive `|| []` on the read — synthetic rows
    // built for tests (registry.test.js) omit the key entirely, and this must not throw.
    // Empty on every single-dimension spec (and on the one of conventions-and-intent's three
    // rows — comment_accuracy — that carries none) by construction, so findingItemSchema below
    // emits nothing extra for them regardless of policy.
    spec.conditionalRequired = spec.rows
      .filter((r) => (r.requiredWhenDimension || []).length)
      .map((r) => ({ dimension: r.dimension, required: [...r.requiredWhenDimension].sort() }))
      .sort((a1, b1) => a1.dimension.localeCompare(b1.dimension));
    delete spec.rows;
    return spec;
  });
}

// An agent is active when at least one of its dimensions is enabled. A dimension is
// enabled when its conditionalFlag is null/undefined (UNGATEABLE — always on, e.g. the
// core bug/security dimensions) OR its agentFlags entry is not the literal `false`.
// OPT-OUT semantics: a MISSING key counts as enabled, so absent/empty agentFlags leaves
// every dimension on — byte-identical to the pre-flag behavior where all flags were null.
// Only an explicit `false` (stamped by a light-scope run, e.g. { deep: false }) disables.
function agentActive(spec, agentFlags) {
  const flags = agentFlags || {};
  return spec.conditionalFlags.some((flag) => flag === null || flag === undefined || flags[flag] !== false);
}

// deriveAgentFlags(riskTable, changedLines, scopeAnswer) -> { deep: false } | {} (issue #24
// req 1/4/5, PR3). The pipeline's OWN, tested derivation of the scope-gating map agentActive
// consumes — replaces the orchestrator's SKILL.md-prose "stamp agentFlags at assembly time"
// rule with deterministic JS. Behavior-preserving: the eligibility test is byte-identical to
// the rule phase2-triage.md 2e documented (computeLightEligible, args.js — the ONE place it
// lives, shared with validateArgs's pre-dispatch coherence guard so the two can never drift).
//
// validateArgs already refused an incoherent waist before runWith ever calls this (scopeAnswer
// 'light' while not eligible, or eligible with no scopeAnswer) — see its "Fail-loud coherence"
// block. So by the time this runs, only two coherent cases can produce `{ deep: false }`:
// lightEligible with scopeAnswer 'light'. Every other coherent combination (not eligible,
// eligible-but-full, not-eligible-with-no-answer) is full scope.
function deriveAgentFlags(riskTable, changedLines, scopeAnswer) {
  const lightEligible = computeLightEligible(riskTable, changedLines);
  return (lightEligible && scopeAnswer === 'light') ? { deep: false } : {};
}

// allActiveDimensionsDegraded(dispatched, degraded) -> boolean (issue #178).
// True when every dimension owned by a dispatched agent is in the degraded list.
// Dimension-level and scope-relative on purpose: a light-scope run whose two active
// agents both fail must fail loud too, and the comparison stays correct if degradation
// ever becomes finer than per-agent.
//
// FAIL-CLOSED arm: if `dispatched` resolves to zero active dimensions — agentSpecs()
// no longer recognizes an agentType in it (a registry rename between the run that wrote
// a replayed checkpoint and this one) or `dispatched` is absent entirely — this is
// UNRESOLVABLE scope, not "nothing was dispatched, so nothing degraded." Reading it as
// "not all degraded" would let a replay with unresolvable scope and something already in
// `degraded` sail through as an ok:true empty clean review: the exact silent success this
// guard exists to stop. So an empty activeDims returns whether anything was reported
// degraded at all, not false. The call site's findings-empty conjunct is what keeps this
// arm from ever aborting a replay that actually carries findings (see runWith).
function allActiveDimensionsDegraded(dispatched, degraded) {
  const dispatchedSet = new Set(dispatched || []);
  const degradedSet = new Set(degraded || []);
  const activeDims = agentSpecs()
    .filter((spec) => dispatchedSet.has(spec.agentType))
    .flatMap((spec) => spec.dimensions);
  if (activeDims.length === 0) return degradedSet.size > 0;
  return activeDims.every((d) => degradedSet.has(d));
}

// The canonical finding ITEM schema (one array element). Declared IN FULL — every
// canonical property with a concrete type, `description` among them — everywhere an agent
// returns findings BY VALUE. An items schema of `{ type:'object', properties:{} }` is the
// trap: StructuredOutput leaves an empty-properties object UNCONSTRAINED, so a model
// transcribing findings back "verbatim via the schema" is free to drop the single largest
// field — `description` — which is exactly what the verify executor did, emptying
// descriptions for every downstream stage (validate/filter/challenge) and false-firing the
// filter's short-description injection guard on high-confidence findings.
//
// An UNDECLARED property is REJECTED at dispatch, not silently dropped: `additionalProperties:
// false` makes a field no one declared a schema violation the platform retries, rather than
// pass-through tolerated at random (issue #53 watched one undeclared field survive 0/8, then
// 8/8, then 5/5 across three PRs of a single smoke — permitted, never a contract). Closing the
// item schema is safe because the declaration is complete and STAYS complete: every field an
// agent contract instructs is one entry in FINDING_PROP_TYPES or a dimension's `schemaExtra` in
// registry.js, and tests/test_dimensions_registry.py fails the build when the declared set
// drifts from what the .md contracts instruct (declared − instructed == {origin}), so the
// closed schema cannot reject a field a contract asks for (issue #47: `suggestion`/
// `claude_md_rule`/`spec_text`/`criticality`/`failure_scenario` were instructed by the
// contracts, declared by nothing, and dropped at this boundary on every run). The blast radius
// is ONE boundary — this item schema reaches only the per-agent discovery dispatch
// (findingSchema below); verify echoes per-id deltas, validate per-id confidence adjustments,
// challenge a score, none of them finding items. `agent`, the one field whose undeclared
// survival ever mattered (the filter's cross-agent dedup keyed on it), is not emitted by
// discovery at all: discover() stamps it in code after StructuredOutput returns and
// joinVerifyDeltas deletes it — both deterministic.
// Entries are EITHER a type-name shorthand string ({ k: 'string' } -> { type:'string' }) OR a
// full JSON-Schema fragment used verbatim (how array-valued fields like cross_file_refs and
// affected_consumers are declared); the shorthand keeps the common case terse while the
// fragment form supports arrays the platform's schema validator requires `items` on.
// schemaExtra wins on a key collision — a dimension may narrow a canonical field, never the
// reverse. `required` is FINDING_REQUIRED plus the dispatch's effective `requiredExtra`
// (issue #66, agentSpecs' intersection) — empty for bug-detector, conventions-and-intent and
// type-design-analyzer, so those three dispatch the byte-identical flat list they always did.
//
// The promotion's blast radius (why registry.js's requiredExtra comment demands
// contract-UNCONDITIONAL fields only): a `required` array is a hard StructuredOutput
// constraint on every element of `findings`, so ONE finding omitting a required field makes
// the whole `{ findings, complete, total_seen }` envelope a schema violation, not just that
// one finding — the platform retries the WHOLE agent dispatch (cap 5) with the validation
// error fed back. If retries exhaust, `parallel()` resolves that member to null and discover()
// treats it as a terminal agent failure: EVERY dimension that agent owns degrades (see
// discover's null-member handling below), not just the dimension whose field was missing.
// A conditionally-omitted field (claude_md_rule, spec_text, hidden_errors,
// invalid_state_example) promoted here would make that omission — which the contract itself
// tells the model to do — a self-inflicted retry storm on every dimension the agent covers.
// `conditionalRequired` (issue #218) is the ONLY caller-gated argument here: findingSchema
// below passes spec.conditionalRequired only when conditionalSchemaActive(policy) is true, so
// this function itself stays a pure function of its inputs — every other agent's spec has an
// empty conditionalRequired regardless of policy, so this construct never appears there at
// all. When non-empty, this appends EXACTLY the measured-accepted spelling — a per-dimension
// `allOf`/`if`/`then` nested inside the item, never a top-level oneOf/allOf/anyOf (API 400,
// measured 2026-08-18). NO enum on `dimension` [delta round]: an enum was considered to close
// the case-sensitive `const` match's case-variant escape, but filterFindings.js's own
// normalization sets (`comment-accuracy`, `documentation`, `doc-accuracy`) are evidence agents
// emit variant dimension spellings the pipeline already tolerates elsewhere — pinning an enum
// here would turn one of those observed, tolerated spellings into a whole-dispatch schema
// violation (all three conventions-and-intent dimensions degrade) to close a narrower escape.
// Accepted as a fail-open risk (contract enforcement only) rather than traded for that.
function findingItemSchema(schemaExtra, requiredExtra, conditionalRequired) {
  const props = {};
  for (const [k, t] of Object.entries({ ...FINDING_PROP_TYPES, ...(schemaExtra || {}) })) {
    props[k] = typeof t === 'string' ? { type: t } : t;
  }
  const required = requiredExtra && requiredExtra.length ? [...FINDING_REQUIRED, ...requiredExtra] : FINDING_REQUIRED;
  const itemSchema = { type: 'object', properties: props, required, additionalProperties: false };
  if (conditionalRequired && conditionalRequired.length) {
    itemSchema.allOf = conditionalRequired.map(({ dimension, required: dimRequired }) => ({
      if: { properties: { dimension: { const: dimension } }, required: ['dimension'] },
      then: { required: dimRequired },
    }));
  }
  return itemSchema;
}

// Canonical finding schema (per-dimension schemaExtra unioned on top), wrapped in the
// per-agent result envelope { findings, complete, total_seen }. REAL JSON Schema —
// {type, properties, required, items} — because the platform validates schemas before
// dispatch and StructuredOutput enforces them (shorthand {id:'string'} is rejected).
// schemaExtra is shorthand {key: typeName} (or a full JSON-Schema fragment for arrays).
//
// `policy` gates the conditional-required construct (issue #218): spec.conditionalRequired is
// threaded through only when conditionalSchemaActive(policy) is true (first-party-direct, no
// gateway). Every other run — third-party providers, gateway sessions, or a spec that simply
// has no conditional rows — dispatches the byte-identical flat schema it always did; contract
// prose (agents/conventions-and-intent.md) stays the enforcement floor everywhere.
function findingSchema(spec, policy) {
  const conditionalRequired = conditionalSchemaActive(policy) ? (spec.conditionalRequired || []) : [];
  return {
    type: 'object',
    properties: {
      findings: {
        type: 'array',
        items: findingItemSchema(spec.schemaExtra, spec.requiredExtra, conditionalRequired),
      },
      complete: { type: 'boolean' },
      total_seen: { type: 'number' },
    },
    required: ['findings', 'complete', 'total_seen'],
  };
}

// Shared by the two discover-side drop branches below: a dropped suggested_fix_code is
// always the same operation (delete-and-report-whether-it-was-there), only the reason for
// dropping it differs between call sites. The report renderer owns its separate exclusion
// list through reportExtraFields().
function dropSuggestedFixCode(f) {
  if (!('suggested_fix_code' in f)) return false;
  delete f.suggested_fix_code;
  return true;
}

// discover(ctx, input) -> { findings, gaps, degraded, dispatched }
// `dispatched` is the full fan-out list (every active agentType, whether it succeeded,
// failed, or returned zero findings) — mergeStage() uses it so a zero-finding agent
// stays distinguishable from one never dispatched at all (e.g. disabled via agentFlags).
// One parallel() call fanning out to every active AGENT. A null member -> gap AND
// every dimension that agent covers is marked degraded: a null means the agent
// terminally failed after the platform's schema retries (cap 5), so those dimensions
// are entirely uncovered — the failure IS the degradation. (Each dimension maps to
// exactly one agent, so a per-dimension failure COUNTER could never cross a >1
// threshold within a single dispatch; degradation is therefore recorded on the first
// failure, not counted toward a limit.) A malformed result (no findings array) is
// treated the same. A non-null result reporting complete=false or total_seen at/over
// an optional discoveryCap -> "possibly incomplete" gap (soft: its findings are still
// collected, dimension not degraded). runWith fails loud (ok:false) instead of returning
// this output's empty findings as a clean review when EVERY active dimension degrades —
// see allActiveDimensionsDegraded and its guard in runWith (issue #178).
async function discover(ctx, input) {
  const c = ctx || defaultCtx();
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const agentFlags = inp.agentFlags || {};
  const limits = inp.limits || {};
  const policy = inp.policy || {};
  const discoveryCap = limits.discoveryCap; // optional per-agent finding ceiling

  const specs = agentSpecs().filter((spec) => agentActive(spec, agentFlags));
  // Platform contract: parallel() takes an array of ZERO-ARG THUNKS, each calling
  // agent(promptString, opts). label IS the agentType (identity for gaps); the prompt
  // already names the dimensions, so no non-standard opts field is passed.
  const thunks = specs.map((spec) => {
    const model = modelFor(spec.agentType, policy);
    return () => c.agent(discoverPrompt(inp, spec), {
      label: spec.agentType,
      agentType: spec.agentType,
      model,
      schema: findingSchema(spec, policy),
    });
  });

  const results = await c.parallel(thunks);

  const gaps = [];
  const findings = [];
  const degradedDims = [];

  // conditionalSchemaActive is policy-only (not per-spec), so compute it once outside the
  // loop — whether a GIVEN spec actually carried the construct still depends on that spec's
  // own conditionalRequired (empty for every agent but conventions-and-intent).
  const schemaActive = conditionalSchemaActive(policy);

  // parallel() resolves a failed member to null IN PLACE (Phase 0 verified): the
  // results array is positionally aligned with `thunks`, so results[i] pairs with specs[i].
  results.forEach((res, i) => {
    const spec = specs[i];
    if (res === null || res === undefined) {
      // issue #218: a dispatch failure on a spec that carried the conditional allOf/if/then
      // construct is worth distinguishing in the gap text — the construct is the one thing
      // about this dispatch's schema that differs from every other run, so it is the first
      // thing an operator diagnosing a schema-retry-exhaustion failure should rule in or out.
      const conditionalNote = schemaActive && (spec.conditionalRequired || []).length
        ? ' (dispatch carried the conditional per-dimension schema)'
        : '';
      gaps.push(`${spec.agentType}: agent returned null (dispatch failed) — dimensions ${spec.dimensions.join('/')} not covered${conditionalNote}`);
      degradedDims.push(...spec.dimensions); // terminal agent failure -> its dimensions degraded
      return;
    }
    const list = Array.isArray(res.findings) ? res.findings : null;
    if (list === null) {
      // Malformed result (no findings array) — no usable coverage, so degrade like a null.
      gaps.push(`${spec.agentType}: malformed result (no findings array)`);
      degradedDims.push(...spec.dimensions);
      return;
    }
    for (const f of list) {
      // Inject the SHORT agent name (canonical schema: 'bug-detector', not the dispatch
      // agentType 'code-gauntlet:bug-detector'). filterFindings matches short names for
      // disagreement suppression / security escalation, and mergeStage regroups on this —
      // the full prefix silently broke both on the live path.
      f.agent = spec.agentType.split(':').pop();
      findings.push(f);
    }
    const nearCap = discoveryCap != null && (res.total_seen >= discoveryCap || list.length >= discoveryCap);
    if (res.complete === false || nearCap) {
      gaps.push(`${spec.agentType}: possibly incomplete (complete=${res.complete === false ? 'false' : 'true'}, total_seen=${res.total_seen}) — dimensions ${spec.dimensions.join('/')}`);
    }
  });

  // Issue #204: bound an implausible discovery-agent line_end at intake, before anything
  // reaches mergeStage. A 2026-08-17 live run had an agent emit line_start=68,
  // line_end=940 (an ~872-line span crossing hunks) — post_review.py's delivery-side fix
  // (PR #200) now falls back to a single-line comment rather than 422ing the whole
  // review, but the emission-side bound belongs HERE too: a span this implausible is
  // agent noise, not a real multi-line finding, and letting it through just makes every
  // downstream stage (and the delivery fallback) carry dead weight. DROP `line_end`
  // rather than clamp it — a clamped value is a fabricated line number nobody reported;
  // the finding survives, anchored at its (still-valid) line_start, same as a finding
  // that never had an end line. maxLineSpan is a caller-tunable limit (LIMIT_DEFAULTS),
  // not a hardcoded literal, so a codebase with legitimately large multi-line findings
  // can raise it.
  const maxLineSpan = effectiveMaxLineSpan(limits);
  let droppedLineSpans = 0;
  let droppedNoLineEnd = 0;
  let droppedFixForImplausibleSpan = 0;
  for (const f of findings) {
    const lineEnd = f.line_end;
    if (lineEnd === undefined || lineEnd === null) {
      // Round-1 #63 fix (F4): a finding that never emitted line_end has no stated
      // replacement range for suggested_fix_code to apply against — six stages later
      // that's a guaranteed missing_end_line downgrade at delivery, so the field is
      // dead payload from here on. Drop it now rather than carry it through every
      // downstream stage; the finding itself survives, anchored at line_start, same
      // as before.
      if (dropSuggestedFixCode(f)) droppedNoLineEnd += 1;
      continue;
    }
    const span = lineEnd - f.line_start;
    if (!Number.isInteger(lineEnd) || span < 0 || span > maxLineSpan) {
      delete f.line_end;
      // Issue #63: suggested_fix_code states its replacement range as line_start..line_end.
      // Dropping line_end just destroyed that stated range, so a fence built from it would
      // mis-apply at whatever single-line anchor line_start now resolves to — delete it in
      // the same breath rather than let a now-unanchored patch survive to delivery. Count it
      // too (only when it was actually present) — the sibling missing-line_end branch counts
      // its drop and says so in its own gap; a silent discard here left the same class of
      // loss unreported and unmeasured.
      if (dropSuggestedFixCode(f)) droppedFixForImplausibleSpan += 1;
      droppedLineSpans += 1;
    }
  }
  if (droppedLineSpans > 0) {
    const fixClause = droppedFixForImplausibleSpan > 0
      ? ` — ${droppedFixForImplausibleSpan} of those also carried suggested_fix_code: patch field(s) dropped along with the range`
      : '';
    gaps.push(`discover: ${droppedLineSpans} finding(s) had an implausible line_end (non-integer, before line_start, or spanning more than maxLineSpan=${maxLineSpan} lines) — line_end dropped, finding kept anchored at line_start${fixClause}`);
  }
  if (droppedNoLineEnd > 0) {
    gaps.push(`discover: ${droppedNoLineEnd} finding(s) emitted suggested_fix_code without line_end — field dropped (a patch must state its range)`);
  }

  // Each dimension belongs to a single agent so no overlap is possible today; the Set
  // keeps degraded deduplicated and insertion-ordered should that ever change.
  return {
    findings,
    gaps,
    degraded: [...new Set(degradedDims)],
    dispatched: specs.map((spec) => spec.agentType),
  };
}

// v2-grade elicitation frame (v3's terse one-liner cut discovery yield ~40% — see the
// skill's phase3-dispatch.md history): read context first, investigate with the agent's
// OWN methodology/tools per its .md definition (loaded as its system prompt via
// agentType), no cap/no minimum on findings, and a reminder of the canonical schema's
// single-paragraph description constraint. Kept short — StructuredOutput's `schema`
// (findingSchema) does the actual shape enforcement, this prompt only sets behavior.
//
// Hill-climb iter 5: two additions. (1) A dimension-agnostic EVIDENCE DISCIPLINE clause
// in the base prompt — every finding must cite concrete, investigated evidence, and any
// absence/"missing" claim must name the specific file or path checked (the
// unverifiable-claim source the challenger later gates on). (2) spec.promptExtra
// (registry.js) is appended verbatim when the agent carries one — the per-agent
// discovery-breadth sweeps (security: SSRF/postMessage/string-bypass; bug-detector +
// conventions-and-intent: typo/naming). Scoping lives entirely in the registry; no
// agent-name special-casing here.
function discoverPrompt(inp, spec) {
  const ctxLine = inp.contextLine || '';
  const dims = spec.dimensions.join(', ');
  const base = `${ctxLine}This is a code gauntlet built for thoroughness, not speed: investigate using your own methodology and tools (LSP first, Grep fallback) as defined for your role, across the full codebase context around the diff — not just the changed lines. Your dimension(s): ${dims}. Report EVERY genuine finding for these dimension(s): there is no cap and no minimum. An empty findings list must reflect a genuine post-investigation absence of issues, never brevity or a quota. Every finding MUST cite concrete evidence: the evidence field must be non-empty and reference real lines you actually inspected (in the diff or in a file you opened) — a finding you cannot ground in inspected code is noise, do not emit it. For any absence or "missing" claim (e.g. a test-coverage negative asserting no test exists), name in evidence the specific file or path you checked; an unproven absence is not a finding. Return { findings, complete, total_seen }; each finding must match the canonical schema, with description as a single paragraph of prose, at most 500 characters — no code blocks or bullet lists; put code references in evidence and cross_file_refs instead.`;
  return spec.promptExtra ? `${base} ${spec.promptExtra}` : base;
}

// --- Phase 3: Merge ---------------------------------------------------------

// mergeStage(discoverOut, meta) -> envelope
// Consumes merge() from mergeFindings.js as-is. Since merge() ingests raw per-agent
// NDJSON strings, regroup the discovered findings by their injected `agent` field and
// re-serialize each group to one JSON object per line. No text-fallback channel exists
// in v3 (parallel() returns structured findings), so textContents is empty.
function mergeStage(discoverOut, meta) {
  const out = discoverOut || { findings: [] };
  const M = typeof meta === 'string' ? JSON.parse(meta) : (meta || {});
  const findings = out.findings || [];

  const byAgent = {};
  for (const f of findings) {
    const a = f.agent || 'unknown';
    (byAgent[a] = byAgent[a] || []).push(f);
  }

  const ndjsonContents = {};
  for (const [a, group] of Object.entries(byAgent)) {
    ndjsonContents[a] = group.map((f) => JSON.stringify(f)).join('\n');
  }

  // agents drives merge()'s per-agent iteration AND methodology.agents_dispatched — and
  // merge()'s injectAgentField RE-STAMPS every finding's `.agent` to whichever string is
  // in this list. discover() now injects the SHORT agent name onto findings (FIX 1: the
  // full 'code-gauntlet:' prefix broke filterFindings' short-name matching), so this list
  // must match that short form too, or the `nd[agent]` lookup below misses for every
  // agent (silently dropping all its findings) and injectAgentField would re-inject the
  // long prefix, undoing FIX 1 downstream. discover()'s own fan-out list (`dispatched`)
  // is still the full 'code-gauntlet:<agent>' agentType (unaffected by FIX 1), so it is
  // normalized here — Object.keys(ndjsonContents) is already short (built straight from
  // findings' own .agent) and needs no normalization.
  //
  // Prefer discover()'s own fan-out list (`dispatched`) so a zero-finding agent is
  // still counted as dispatched, distinguishable from one never dispatched at all
  // (disabled via agentFlags). Older/synthetic callers that omit `dispatched` fall back
  // to the agents that actually produced findings, and finally the full roster so an
  // empty run still yields an envelope.
  const shortAgentName = (a) => (typeof a === 'string' ? a.split(':').pop() : a);
  const agents = Array.isArray(out.dispatched)
    ? out.dispatched.map(shortAgentName)
    : (Object.keys(ndjsonContents).length ? Object.keys(ndjsonContents) : AGENTS.map(shortAgentName));
  return merge(ndjsonContents, {}, { ...M, agents });
}

// --- Phase 4: Verify --------------------------------------------------------

// The canonical key order of one delta, and the ONLY keys that carry meaning. Both the
// dispatch schema and the checksum canonicalisation are built from this one list, so a
// field added to the delta cannot be declared in one place and forgotten in the other.
// It mirrors verify_findings.py's `_DELTA_FIELDS` plus the two structural keys; the
// script's audit comment is the authority for why the set is exactly this.
const DELTA_KEYS = ['id', 'verified', 'origin', 'severity', 'confidence', 'elimination_reason'];

// The discriminated-union envelope the executor returns. Both shapes coexist so an
// honest failure is schema-valid — the executor never fabricates a success under
// StructuredOutput retry pressure ({status:'failed'} is a legal answer).
//
// `result.deltas` REPLACED the by-value verified/eliminated finding arrays (#25 req 1).
// The workflow already holds every dispatched finding, so the only thing the executor can
// tell it is what the SCRIPT decided; re-transcribing the findings themselves bought
// nothing and cost everything — 22.95s of one profiled executor's 31.9s generation, a
// 1,990-byte schema (the file's largest) dispatched per slice, and the entire surface on
// which a live run's 10-verified/0-eliminated disk result came back as a 7/3 echo under a
// valid receipt. The item shape is deliberately flat and typed: six scalars, no nested
// objects, no per-dimension extras to union, nothing whose absence can silently empty a
// finding field downstream (the `description`-stripping class this schema used to enable).
//
// `agent` is not declarable here because no finding is echoed at all any more — the
// withholding that used to depend on leaving one property out of a finding schema is now
// structural. `agent` re-lands with #22's redesign: joinVerifyDeltas no longer strips it
// (consolidateCrossAgent never drops a finding, so a deterministic `agent` past verify no
// longer costs recall the way the old drop-one-winner dedupCrossAgent did — V3.1 item 4's
// prior attempt moved mini-subset A's dedup eliminations 7 -> 33 and same-6 recall
// 20/30 -> 13/30 under that eliminator).
const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    status: { type: 'string' }, // 'ok' | 'failed'
    receipt: {
      type: 'object',
      properties: {
        sha: { type: 'string' },
        n_in: { type: 'number' },
        nonce: { type: 'string' },
        // The delta echo's content proof (fnv1a32 over the script's own serialisation).
        // Optional in the SCHEMA, mandatory in trustSlice — an absent proof is a legal
        // thing for the executor to say and an untrusted thing for the workflow to act on.
        deltas_checksum: { type: 'string' },
        // The slice-input content proof (issue #69 / #25 req 4-6): fnv1a32 over the
        // document the script PARSED, compared in trustSlice against the checksum this
        // stage computed over the content it dispatched. Optional in the SCHEMA,
        // mandatory in trustSlice — same shape and same reason as deltas_checksum.
        input_checksum: { type: 'string' },
      },
    },
    result: {
      type: 'object',
      properties: {
        deltas: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              id: { type: 'string' },
              verified: { type: 'boolean' },
              origin: { type: 'string' },
              severity: { type: 'string' },
              confidence: { type: 'number' },
              elimination_reason: { type: 'string' },
            },
            required: ['id', 'verified'],
          },
        },
      },
    },
    // Present ONLY when the script recovered a slice-input file whose sole defect was
    // trailing closing punctuation. Never declared `required` at the TOP level (an absent
    // object is a legal, common answer) — but `trailing_bytes` IS required WITHIN the
    // object once it exists, because the RECOVERED disclosure keys on a usable string
    // there, not on the object's mere presence: a schema-legal `input_recovery: {}` must
    // not be answerable at all, or trustSlice's caller would have to distinguish "no
    // recovery" from "a recovery that forgot to say what it recovered" on its own.
    input_recovery: {
      type: 'object',
      properties: { trailing_bytes: { type: 'string' } },
      required: ['trailing_bytes'],
    },
    exitCode: { type: 'number' },
    stderr: { type: 'string' },
  },
  required: ['status'], // discriminated union: receipt/result only present on status:'ok'
};

// Dispatches per verify slice: the first executor call plus EXACTLY ONE deterministic
// re-dispatch when that call comes back untrusted (verifySliceWithRetry).
//
// It is a named constant because two independent things must agree with the retry
// verifySliceWithRetry actually performs: worstCaseAgentCount's verify term (a guard that
// undercounts the worst case is a guard that does not hold) and the tests that pin the
// dispatch count. Exported so those tests assert against THIS value rather than a
// hand-copied literal — raise it here without touching verifySliceWithRetry and the
// dispatch-count test fails instead of the guard silently over-counting.
const VERIFY_ATTEMPTS_PER_SLICE = 2;

// Issue #72: verifySliceSize is deliberately NOT floored. A very small slice is the
// legitimate mitigation for a transcription-fidelity failure (#25 req 1 — a smaller slice
// means less content per executor round trip, less to transcribe faithfully, less to
// mismatch), so clamping it upward here would remove the exact knob an operator reaches for
// under that failure mode. Instead: degrade-and-disclose. When a configured verifySliceSize
// produces MORE than VERIFY_FANOUT_DISCLOSE_THRESHOLD slices, verifyStage pushes a gap
// naming the configured size, the resulting slice count, and the dispatch ceiling
// (slices * VERIFY_ATTEMPTS_PER_SLICE) — an operator who set verifySliceSize:1 on a
// 500-finding run sees the cost of that choice instead of discovering it from a slow run or
// a worstCaseAgentCount rejection.
const VERIFY_FANOUT_DISCLOSE_THRESHOLD = 5;

// verifyStage(ctx, input) -> { findings, verified: boolean, gaps }
// Slices findings into limits.verifySliceSize chunks and dispatches an `executor` agent
// per slice — one call, plus at most one retry (below) — SEQUENTIALLY (not parallel())
// so each envelope pairs to its slice by order. Each executor runs the pinned
// verify_findings.py receipt command and returns VERIFY_SCHEMA: the receipt plus a
// per-finding DELTA, never the findings themselves (#25 req 1). A slice is TRUSTED only
// when status==='ok', the receipt echoes the dispatched nonce and head sha and n_in, the
// deltas cover exactly the ids this slice dispatched, and their content proof matches
// (trustSlice). The verified findings are then rebuilt HERE, by joining the delta onto
// the findings this stage already holds by value — the executor's transcription is no
// longer in the data path at all, only in the decision path.
//
// DEGRADATION IS PER SLICE (issue #54, and issue #25 requirement 3). An untrusted slice
// — receipt mismatch, status:'failed', an agent() throw, or a slice whose --input file
// was never provably written — degrades ONLY ITS OWN findings to the UNVERIFIED shape
// (origin='unknown', surfaced-classification skipped) and the loop keeps going; slices
// that verify cleanly keep their verified output. This replaced an all-or-nothing
// `break` under which one transient hiccup on slice 0 cost EVERY slice its
// classification: measured live on 2026-07-27 (smoke-20260727-205454-f99d948), a single
// dropped nonce echo marked all 16 findings of a one-slice PR origin=unknown. The size
// of the damage now tracks the size of the fault.
//
// Findings are never dropped and success is never fabricated, now at slice granularity:
// against every failure class this stage DETECTS, every finding leaves this stage either
// as its slice's trusted verified output or as itself with origin='unknown' — never
// missing, never silently upgraded. `verified` is true only when ZERO slices degraded, so
// the one top-level boolean keeps meaning "this whole run's classification is trustworthy".
//
// ("this stage", not "trustSlice": an agent() throw is caught in dispatchVerifySlice and a
// missing slice input in materializeVerifySlices — trustSlice never sees either.)
//
// The never-drop half is now structural rather than merely intended (#25 req 2, which
// removed the qualifier that used to stand here). The findings this stage emits on the
// trusted path are the ones IT dispatched — joinVerifyDeltas walks the dispatched slice
// and enriches it — so no echo, however wrong, can substitute or delete a finding: the
// worst an untrusted echo achieves is its own slice's honest degrade. The previous design
// pushed the findings themselves through the executor, where an envelope carrying a
// same-length SIBLING slice's findings satisfied every guard and the real slice's findings
// were dropped outright while the run reported verified=true (reproduced end to end during
// the #54 review). That class is closed here, not mitigated.
async function verifyStage(ctx, input) {
  const c = ctx || defaultCtx();
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const findings = inp.findings || [];
  const limits = inp.limits || {};
  const policy = inp.policy || {};
  const nonce = inp.nonce;
  const headShaShort = inp.headShaShort;
  const sliceSize = effectiveSliceSize(limits, findings.length);

  // Empty set: nothing to verify, trivially trusted (no executor dispatched). The
  // counters are still emitted, zero-populated: a consumer that has to distinguish
  // "no slices" from "the field is missing" is a consumer that will get it wrong.
  if (findings.length === 0) {
    return { findings: [], verified: true, gaps: [], inputProof: emptyInputProof() };
  }

  const model = modelFor('code-gauntlet:executor', policy);

  const slices = [];
  for (let i = 0; i < findings.length; i += sliceSize) slices.push(findings.slice(i, i + sliceSize));

  // Degrade-and-disclose (issue #72), not abort: a small verifySliceSize is a legitimate
  // transcription-fidelity mitigation, not a mistake to reject, but its dispatch cost is
  // real and otherwise invisible until the run runs long or worstCaseAgentCount rejects it
  // outright. Collected here rather than pushed straight into `gaps` so it lands ahead of
  // any per-slice degrade gap, in the order this stage discovers information.
  const fanoutGaps = slices.length > VERIFY_FANOUT_DISCLOSE_THRESHOLD
    ? [`verify_fanout: verifySliceSize=${sliceSize} splits ${findings.length} finding(s) into ${slices.length} slices `
      + `(above the ${VERIFY_FANOUT_DISCLOSE_THRESHOLD}-slice disclosure threshold) — up to ${slices.length * VERIFY_ATTEMPTS_PER_SLICE} `
      + `executor dispatches at ${VERIFY_ATTEMPTS_PER_SLICE} attempts per slice. Raise verifySliceSize to reduce fan-out, `
      + 'or keep it small deliberately if this run is mitigating a transcription-fidelity failure (issue #25).']
    : [];

  // Materialize each slice's --input JSON on disk BEFORE the executor loop. The
  // executor reads ${inputPathBase}.slice{i}.json, but the workflow script has no disk
  // access and the merged findings exist only mid-workflow (the skill CANNOT pre-write
  // them). One or more artifact-writer dispatches (segmented when the payload is large)
  // write them by value. A writer GROUP that fails takes only the
  // slices IT carried to the UNVERIFIED path — never fabricate a verification for a
  // slice whose input is not provably on disk, and never punish the slices whose input is.
  const materialized = await materializeVerifySlices(c, inp, slices, policy);

  const out = [];
  const gaps = [...fanoutGaps];
  let degradedSlices = 0;
  const inputProof = { ...emptyInputProof(), slices: slices.length };

  // The output is assembled in SLICE-INDEX order — trusted output and degraded originals
  // alike — because downstream ranking (applyChallenges' stable sort on severity then
  // confidence) breaks ties by array position. Completion order or "trusted first" would
  // make delivery ordering vary run to run for tied findings.
  for (let i = 0; i < slices.length; i += 1) {
    const slice = slices[i];
    const expectedInputChecksum = materialized.expected.get(i);
    const degrade = (detail) => {
      out.push(...degradedSlice(slice));
      gaps.push(verifyDegradeGap(detail, slice.length, findings.length));
      degradedSlices += 1;
    };

    // No write proof for this slice's --input file: the executor would read a file that
    // may not exist, so it is never dispatched. Only this slice degrades.
    const unwritten = materialized.failed.get(i);
    if (unwritten !== undefined) {
      degrade(`slice ${i} (slice-input group ${unwritten.group}): ${unwritten.reason}`);
      continue;
    }

    // The delta echo is keyed by finding id, so a slice whose own findings have no usable
    // id set cannot be joined no matter how faithfully the executor answers. Checked
    // BEFORE dispatch: spending an executor on an answer this stage could not use is
    // strictly worse than degrading now. Degrade-and-disclose rather than reject, so a
    // merge-side id regression costs one slice its classification and says so, instead of
    // failing the run (post-merge ids are present by construction — mergeFindings drops
    // id-less findings — which is why this is a guard, not a routine path).
    const ids = dispatchableIds(slice);
    if (!ids.ok) {
      degrade(`slice ${i}: ${ids.reason} — the delta echo is keyed by id, so this slice cannot be verified`);
      continue;
    }

    const attempt = await verifySliceWithRetry(c, inp, i, slice, { model, nonce, headShaShort, ids: ids.ids, expectedInputChecksum });
    if (!attempt.ok) {
      if (attempt.inputFault === 'mismatch') inputProof.mismatched += 1;
      else if (attempt.inputFault === 'missing') inputProof.missing += 1;
      degrade(`slice ${i}: ${attempt.reason}`);
      continue;
    }
    const recoveryBytes = usableRecoveryBytes(attempt.recovery);
    if (expectedInputChecksum == null) inputProof.unprovable += 1;
    else if (recoveryBytes) inputProof.recovered += 1;
    else inputProof.proven += 1;
    // Trusted: this slice's OWN findings, enriched by the script's delta (origin
    // new/surfaced, the surfaced severity downgrade, the factual-verification confidence
    // re-score). Everything the script did not touch — description, evidence,
    // cross_file_refs, suggestion, every per-dimension extra — is the value this stage
    // already held, so it cannot be dropped or mangled in transcription. Findings the
    // script really eliminated are absent by design (their delta says verified:false, and
    // trustSlice requires the script's elimination stamp on every one of them).
    out.push(...attempt.verified);
    if (attempt.gap) gaps.push(attempt.gap);
    if (recoveryBytes) {
      // Degraded-but-disclosed, never invisible: the writer appended bytes after a
      // complete document and the script recovered from it. Nothing was lost — the
      // LEADING document is the one the input proof matched — but a tolerance the run
      // does not state is a tolerance that stops being noticed. Deliberately carries no
      // UNVERIFIED token and none of the bench checker's degrade sentinels: this slice
      // degraded nothing (bench/runner/check.py _DEGRADE_RE).
      //
      // The closing clause states only what was actually established: "proven against
      // dispatch" is a claim the unprovable slice has no right to make, and a
      // disclosure that overstates its evidence is the reporting defect this
      // pipeline exists to prevent.
      const provenClause = expectedInputChecksum == null
        ? 'no cross-runtime proof was computable for this slice; verdicts trusted on the remaining guards'
        : 'leading document proven against dispatch, verdicts trusted';
      gaps.push(`verify: RECOVERED — slice ${i}: writer appended trailing bytes ${JSON.stringify(recoveryBytes)} after a complete slice-input document; ${provenClause}`);
    }
  }

  return { findings: out, verified: degradedSlices === 0, gaps, inputProof };
}

// One slice's share of the UNVERIFIED degradation: its ORIGINAL findings re-emitted with
// origin='unknown' (surfaced-classification skipped). Nothing is dropped and nothing is
// upgraded. Numeric-string fields are pinned here for the same reason they are pinned on
// the slice-input path: the trusted path returns the script's re-scored numbers, but this
// path re-emits discovery-shaped findings straight through. The discovery schema now
// declares confidence a NUMBER (FINDING_PROP_TYPES in registry.js), so the string form
// "85" no longer arrives from a live dispatch; the pin is defence-in-depth for
// legacy/checkpoint-resume findings that predate that schema pin — leaked downstream, a
// string confidence makes the filter's consensus `+` boost concatenate ("85" + 10 ->
// "8510" -> clamped to 100).
function degradedSlice(slice) {
  return slice.map((f) => ({ ...pinNumericFields(f), origin: 'unknown' }));
}

// The slice-input proof ledger. One object, one construction site, so a new path
// cannot forget a key (issue #69 / #25 req 4-6). Counters are DISJOINT: a trusted slice
// lands in exactly one of proven / recovered / unprovable, a degraded one in at most one
// of mismatched / missing (a slice degraded for any other reason is counted in `slices`
// and nowhere else).
const emptyInputProof = () => ({ slices: 0, proven: 0, recovered: 0, mismatched: 0, missing: 0, unprovable: 0 });

// A recovery is only USABLE when it names a non-empty `trailing_bytes` string. The
// schema declares `input_recovery` an object with no top-level `required`, so an absent
// recovery (`undefined`) is the common legal answer — but WITHIN the object,
// `trailing_bytes` is schema-required (VERIFY_SCHEMA), so a StructuredOutput answer can
// still arrive malformed only via a non-string value the schema's own type check missed,
// or (pre-schema-fix) an empty string. Both the `recovered` counter and the RECOVERED
// disclosure key on THIS, never on the weaker truthiness of the `input_recovery` object
// itself — an object with no usable bytes is not a recovery, it is an unusable answer,
// and treating it as one would fabricate a disclosure claiming bytes that do not exist.
function usableRecoveryBytes(recovery) {
  const bytes = recovery && recovery.trailing_bytes;
  return typeof bytes === 'string' && bytes !== '' ? bytes : null;
}

// The loud gap for one degraded slice. `detail` names the slice (and, for a write
// failure, the writer group) and carries the underlying reason, so a reader can tell
// WHICH share of the run lost its classification and why; `k of n` states the blast
// radius directly, which is the whole point of per-slice degradation — a run that
// degrades 2 of 16 findings must not read the same as one that degrades all 16.
//
// The UNVERIFIED token is load-bearing: tests and the bench checker's degrade scan key
// on substrings of this string, and the underlying reason is passed through VERBATIM (a
// write-proof failure's "(no write proof)" is exactly what bench/runner/check.py's
// _DEGRADE_RE matches — paraphrasing it would silently disable that detection).
function verifyDegradeGap(detail, k, n) {
  return `verify: UNVERIFIED — ${detail}; ${k} of ${n} finding(s) marked origin=unknown, surfaced-classification skipped`;
}

// verifySliceWithRetry -> { ok:true, verified, gap } | { ok:false, reason }
// One slice, dispatched at most VERIFY_ATTEMPTS_PER_SLICE times: the first executor call
// and — only if that one came back untrusted — exactly ONE re-dispatch before degrading.
// Same shape and rationale as writeArtifactsDerived's single retry: the executor is a
// SAMPLED AGENT, not a function, so a second dispatch is a fresh sample and is a
// plausible fix for the whole failure set here (a dropped/garbled receipt echo, a
// truncated result body, a fabricated elimination, a schema-retry exhaustion or timeout
// throw). That is why this retries uniformly where the persist path classifies: there is
// no verify failure class for which "our dispatch never reached the script" is provable,
// so a blanket single retry is both simpler and never less honest than a taxonomy.
//
// The retry carries a DISTINCT nonce (`${nonce}.${i}.r1`). Re-using the slice nonce
// would move the exact confusion trustSlice defends against from space (two equal-length
// slices satisfying each other's receipts) into time (attempt 2 satisfied by a replay of
// attempt 1's receipt) — and since attempt 1 was untrusted, a fresh receipt is precisely
// the thing we are re-dispatching to obtain. The suffix stays inside the args-waist nonce
// charset (args.js NONCE_RE) and inside one AST-safe word token.
//
// The nonce is now COMPUTED ONCE and threaded into verifyPrompt/verifyCommand. It used
// to be derived independently at both sites, which silently required the two formulas to
// stay identical; an attempt-varying nonce makes that a live bug rather than a latent one.
async function verifySliceWithRetry(c, inp, i, slice, { model, nonce, headShaShort, ids, expectedInputChecksum }) {
  const attempt = (sliceNonce, label) =>
    dispatchVerifySlice(c, inp, i, slice, { model, headShaShort, sliceNonce, label, ids, expectedInputChecksum });

  const first = await attempt(`${nonce}.${i}`, `verify-slice-${i}`);
  if (first.ok) return { ok: true, verified: first.verified, gap: null, recovery: first.recovery };

  // A DETERMINISTIC fault is one a fresh sample cannot fix: the slice-input content
  // proof compares the file on disk against what this stage dispatched, and a retry
  // re-reads the same file. Spending the second dispatch would buy the identical answer
  // and inflate nothing but latency. This only ever REDUCES the dispatch count, so
  // worstCaseAgentCount's VERIFY_ATTEMPTS_PER_SLICE term and coarsenLimits' matching
  // lever stay exactly as they are — a bound that is still a bound.
  if (first.deterministic) {
    return {
      ok: false,
      reason: `${first.reason} — not retried: a re-dispatch reads the same slice-input file, so this fault is deterministic`,
      inputFault: first.inputFault,
    };
  }

  const second = await attempt(`${nonce}.${i}.r1`, `verify-slice-${i}-retry`);
  if (second.ok) {
    // Disclosed, not degraded: no finding lost its classification, but the run states
    // that it took two dispatches to get there (the persist path's retry discloses the
    // same way). Deliberately carries no UNVERIFIED token — nothing was degraded.
    return {
      ok: true,
      verified: second.verified,
      gap: `verify-slice-retry: slice ${i}'s first executor dispatch was untrusted (${first.reason}); a second dispatch was trusted and this slice's verified findings are from that attempt`,
      recovery: second.recovery,
    };
  }
  return {
    ok: false,
    reason: `${second.reason} — retried once after the first attempt failed (${first.reason})`,
    inputFault: second.inputFault,
  };
}

// One executor dispatch for one slice. Never throws: a thrown agent() becomes an
// untrusted result carrying the message, exactly as the pre-retry loop recorded it.
async function dispatchVerifySlice(c, inp, i, slice, { model, headShaShort, sliceNonce, label, ids, expectedInputChecksum }) {
  let env;
  try {
    // agent(promptString, opts); the pinned command is embedded in the prompt
    // (verifyPrompt), which is how the executor agent receives it.
    env = await c.agent(verifyPrompt(inp, i, sliceNonce), {
      label,
      agentType: 'code-gauntlet:executor',
      model,
      schema: VERIFY_SCHEMA,
    });
  } catch (e) {
    return { ok: false, reason: `executor threw (${(e && e.message) || 'unknown'})` };
  }
  const trust = trustSlice(env, { nonce: sliceNonce, headShaShort, n: slice.length, ids, expectedInputChecksum });
  if (!trust.ok) {
    return { ok: false, reason: trust.reason, inputFault: trust.inputFault, deterministic: trust.deterministic };
  }
  // `input_recovery` rides out on the TRUSTED path only: the whole point of disclosing
  // it is that the leading document was proven against dispatch, so the verdicts stand.
  return { ok: true, verified: joinVerifyDeltas(slice, env.result.deltas), recovery: env.input_recovery };
}

// dispatchableIds(slice) -> { ok:true, ids:[...] } | { ok:false, reason }
// The delta echo is joined by id, so a slice is only dispatchable when every finding in
// it carries a usable string id and no two share one. Duplicates ACROSS slices are fine —
// each slice's join is independent — so this is deliberately a per-slice check.
//
// Ids are matched EXACTLY, everywhere: here, in trustSlice's coverage check, and in the
// join. Only the USABILITY test trims, mirroring verify_findings.py's `id.strip()` guard —
// an id that is nothing but whitespace is one the script would skip. Matching on the
// trimmed form was tried and removed: it bought no tolerance the checksum did not
// immediately take back (the proof compares the id text the script wrote, so an echo that
// added or stripped whitespace failed there instead), while making two dispatched findings
// whose ids differ ONLY by surrounding whitespace collide into a false whole-slice degrade
// the script itself would never have produced. Strict everywhere is both simpler and
// strictly less likely to lose a slice.
function dispatchableIds(slice) {
  const ids = [];
  const seen = new Set();
  for (const f of slice) {
    const id = f && typeof f.id === 'string' ? f.id : '';
    if (!id.trim()) return { ok: false, reason: 'a dispatched finding has no usable id' };
    if (seen.has(id)) return { ok: false, reason: `duplicate finding id in the slice (${id})` };
    seen.add(id);
    ids.push(id);
  }
  return { ok: true, ids };
}

// The delta keys that carry a VALUE onto a finding (DELTA_KEYS minus the two structural
// ones). Iterated in the same fixed order the canonicalisation uses.
const DELTA_VALUE_KEYS = DELTA_KEYS.filter((k) => k !== 'id' && k !== 'verified');

const deltaHas = (d, k) => d[k] !== undefined && d[k] !== null;

// joinVerifyDeltas(slice, deltas) -> the slice's verified findings, enriched.
// Exported for the dual-runtime golden fixtures: the parity case records
// verify_findings.py's own delta and its own verified findings, and asserts THIS function
// reconstructs the latter from the former — which is the whole equivalence claim #25
// requirement 1 makes ("the enriched set after the join must be equivalent to today's
// trusted-path output for every field downstream stages consume").
//
// Walks the DISPATCHED slice, never the echo: order, membership and every untouched field
// come from data this stage already holds. A finding whose delta says verified:false was
// eliminated by the script and is omitted, exactly as it was omitted from the old echo's
// verified[] array.
//
// PRECONDITION, and the one way this function could ever drop a finding: it must be called
// only with deltas that trustSlice has already accepted, which is what proves every
// dispatched id has exactly one delta carrying a boolean `verified`. A finding with NO
// delta is skipped here — there is no honest alternative, since keeping it would deliver an
// unverified finding as a verified one — so a caller that skips the coverage check would
// reintroduce the silent drop this whole change exists to close. Nothing but
// dispatchVerifySlice (immediately after its trustSlice call) and the golden-fixture test
// calls it; keep it that way.
//
// `agent` used to be stripped here — the one place where the withholding #25
// requirement 1 mandated was enforced. It used to happen by omission (the echo schema
// simply did not declare `agent`, so StructuredOutput dropped it... most of the time —
// measured surviving on 2 of 6 PRs). Joining onto findings this stage holds would have
// made it deterministic, which was the measured dedup recall-collapse mechanism (the old
// drop-one-winner `dedupCrossAgent` silently discarded whichever agent's finding lost),
// so the withholding had to become explicit. It re-lands now (#22): `consolidateCrossAgent`
// eliminates nothing, so a deterministic `agent` on the trusted path no longer costs
// recall, and both this path and `degradedSlice` emit `agent` identically again.
function joinVerifyDeltas(slice, deltas) {
  const byId = new Map();
  for (const d of Array.isArray(deltas) ? deltas : []) {
    if (d && typeof d.id === 'string') byId.set(d.id, d);
  }
  const out = [];
  for (const f of slice) {
    const delta = byId.get(f.id);
    if (!delta || delta.verified === false) continue;
    // pinNumericFields for the same reason the degraded path applies it: the script
    // coerces numeric strings at its --input boundary, so the trusted output has always
    // carried real numbers, and a leaked "85" makes the filter's consensus boost
    // string-concatenate ("85" + 10 -> "8510").
    const joined = pinNumericFields(f);
    for (const k of DELTA_VALUE_KEYS) if (deltaHas(delta, k)) joined[k] = delta[k];
    out.push(joined);
  }
  return out;
}

// Numeric finding fields that verify_findings.py does arithmetic on (line_start - 1,
// line comparisons). Pin them to real numbers before the slice-input JSON is written
// AND again on the join path, mirroring verify_findings._coerce_numeric_fields:
//
//   1. A clean integer string ("153") becomes a number — a quoted value makes the
//      receipt-path arithmetic raise `unsupported operand type(s) for -: 'str' and
//      'int'` and degrade the whole slice to UNVERIFIED (the TypeError the live smoke
//      run hit).
//   2. A finite non-integral number is half-up rounded to an int. Line fields are NOT
//      in the delta (the script does not re-decide them), so without this the join
//      would keep the fractional dispatched value while verification ran against the
//      rounded one — the silent divergence the Python input-boundary rounding was
//      meant to remove. Confidence is also rounded here; a delta that carries a
//      script-decided confidence overwrites it afterward.
//
// Everything else (null, non-numeric, NaN/inf, fractionally-valued numeric strings) is
// left alone so the script's own guards still fire.
const VERIFY_NUMERIC_FIELDS = ['line_start', 'line_end', 'line', 'end_line', 'confidence'];
function pinNumericFields(finding) {
  const out = { ...finding };
  for (const k of VERIFY_NUMERIC_FIELDS) {
    const val = out[k];
    if (typeof val === 'string' && val.trim() !== '' && Number.isFinite(Number(val))) {
      const n = Number(val);
      // Any string whose numeric VALUE is an integer ("153", but also "12.0"/"1e5");
      // a fractionally-valued string is left alone. Python's `_INT_RE` branch is
      // narrower — it fullmatches plain digits, so only "153" coerces there.
      if (Number.isInteger(n)) out[k] = n;
      continue;
    }
    if (typeof val === 'number' && Number.isFinite(val) && !Number.isInteger(val)) {
      // Explicit half-up (Math.floor(x + 0.5)), matching Python's
      // int(math.floor(value + 0.5)) — not Math.round, whose tie-breaking is easy to
      // misread against the Python spelling this must stay locked to.
      out[k] = Math.floor(val + 0.5);
    }
  }
  return out;
}

// The slice-input projection (issue #50b): the fields verify_findings.py consults on a
// dispatched slice, walked in this fixed order so the serialized key order is
// deterministic — NOT the order the script reads them in (classify_blame's reads come
// first there and don't match this order). One list in two runtimes with
// `_SLICE_INPUT_FIELDS` in scripts/verify_findings.py — `tests/test_verify_findings.py`
// pins the pair in lockstep and scans the script's own source to enforce the list against
// it. `origin` is listed as tolerated forward-compat even though the script never actually
// reads the dispatched value: classify_blame overwrites `origin` before every read site.
// Keep this list on ONE LINE — tests/test_verify_findings.py regex-parses it against the
// Python twin.
const VERIFY_SLICE_FIELDS = ['id', 'file', 'line_start', 'line_end', 'description', 'evidence', 'severity', 'confidence', 'cross_file_refs', 'origin'];

// projectVerifySliceFinding(finding) -> a finding narrowed to VERIFY_SLICE_FIELDS, in that
// key order, with absent fields left absent (never written as null — an omitted key and an
// explicit null are different signals to the script's own `.get()` defaults). The delta
// echo (joinVerifyDeltas) rebuilds every verified finding from the workflow's OWN in-memory
// copy, never from this projection, so a field dropped here loses nothing downstream (see
// workflows/AGENTS.md, "The verify boundary"). Numeric fields get the identical
// pinNumericFields treatment applied to the full finding elsewhere (degradedSlice,
// joinVerifyDeltas) so a slice's on-disk numbers and its in-memory numbers never diverge.
function projectVerifySliceFinding(finding) {
  const projected = {};
  for (const k of VERIFY_SLICE_FIELDS) {
    if (finding && Object.hasOwn(finding, k) && finding[k] !== undefined) projected[k] = finding[k];
  }
  return pinNumericFields(projected);
}

// Dispatch the artifact-writer to persist each slice's --input JSON (the shape
// verify_findings.py --input reads: { findings, base_branch }). Segmented under the
// shared char budget. Returns { failed, expected } — `failed` a Map from SLICE INDEX to
// { group, reason } for every slice whose input file is not provably on disk (an empty
// map means every slice's input was written and proven); `expected` a Map from SLICE
// INDEX to the slice-input content proof this stage computed over the content it
// dispatched (string), or null when no cross-runtime proof is computable for that slice.
//
// The per-GROUP fan-out goes through parallel() (issue #38, S2) — the groups are
// independent writes to distinct paths — and each thunk owns its try/catch, so a thrown
// member can never escape and parallel() never has to null it (the message survives into
// the reason string). NOTE this is the group loop only; verifyStage's per-SLICE executor
// loop stays sequential on purpose (each envelope pairs to its slice by order).
//
// A failed group takes down only ITS OWN slices (issue #54). This used to return the
// FIRST failure in group-index order and degrade the entire run, which threw away both
// the groups that wrote successfully and every other group's failure reason. Failures are
// still surfaced in a deterministic order — verifyStage walks slices by index and groups
// are contiguous in that index, so gap order is fixed by construction, not by which
// parallel member happened to settle first.
async function materializeVerifySlices(c, inp, slices, policy) {
  const v = inp.verify || {};
  const inputPathBase = v.inputPathBase || 'phase4-input';
  const model = modelFor('code-gauntlet:artifact-writer', policy);
  const entries = slices.map((slice, i) => ({
    path: `${inputPathBase}.slice${i}.json`,
    content: { findings: slice.map(projectVerifySliceFinding), base_branch: v.baseBranch },
  }));
  // The slice-input CONTENT proof (issue #25 requirements 4-6). The write proof below
  // only ever confirms a path came back in the echo — it cannot tell a file holding
  // this slice's document from a file holding a sibling's, an empty one, or one the
  // writer paraphrased. verify_findings.py checksums the document it actually PARSED
  // and reports it in the receipt; this is the other half of that comparison, computed
  // over the content this stage dispatched.
  //
  // A VALUE proof, not a byte proof, and deliberately so: the writer persists compact
  // JSON (measured on both retained captures from smoke-20260728-144630-a162ecd), so a
  // byte comparison against the pretty form would fail every real run. Both runtimes
  // hash a canonical re-serialisation of the same value — the identical pair the
  // persist path uses, pinned by tests/fixtures/parity/slice_input_proof/.
  //
  // null means NO PROOF IS COMPUTABLE: the Python twin refuses a number it cannot spell
  // identically (firstUnsafeNumber's rule, assemble_artifacts.assert_js_reproducible).
  // Since issue #50b, the fields pinNumericFields walks (line_start, line_end, confidence)
  // already had a fractional value rounded inside projectVerifySliceFinding — but that is
  // not every numeric the slice document can carry: `cross_file_refs` is projected too,
  // and while the schema types its items as strings, a legacy/checkpoint-resume finding is
  // off-schema and firstUnsafeNumber walks arrays, so a numeric hiding inside
  // `cross_file_refs` still reaches this branch unrounded. Likewise an already-integral
  // pinned field outside JS's safe integer range (e.g. a corrupted line_start) is left
  // exactly as large as it arrived — pinNumericFields only rounds a FINITE NON-INTEGER
  // value. Either way the check is skipped rather than failed — every other guard still
  // applies, and degrading a slice over one unspellable value would repeat the defect
  // issue #69 closes.
  const expected = new Map(
    entries.map((e, i) => [
      i,
      firstUnsafeNumber(e.content, `slice${i}`) === null
        ? fnv1a32(JSON.stringify(e.content, null, 2))
        : null,
    ]),
  );
  // path -> slice index. Keyed on the PATH (unique per slice by construction) rather than
  // on a group's position, so attributing a group's failure to its slices cannot be
  // silently invalidated by a future change to how entries are chunked.
  const sliceOfPath = new Map(entries.map((e, i) => [e.path, i]));
  const groups = chunkBySerializedSize(entries, PROMPT_SEGMENT_CHAR_BUDGET);
  const thunks = groups.map((group, g) => async () => {
    let result;
    try {
      result = await c.agent(verifySliceWriterPrompt(group), {
        label: `verify-input-writer-${g}`,
        agentType: 'code-gauntlet:artifact-writer',
        model,
        schema: WRITTEN_SCHEMA,
      });
    } catch (e) {
      return { ok: false, reason: `slice-input writer threw (${(e && e.message) || 'unknown'})` };
    }
    if (!result) return { ok: false, reason: 'slice-input writer returned null' };
    // Write-proof: the echoed `written` list must cover every slice-input path this group
    // dispatched. WRITTEN_SCHEMA declares no `required`, so an empty { written: [] } is
    // schema-valid — without this a writer that persisted nothing would pass and the
    // executor would then read slice-input files that were never written. An uncovered
    // path degrades THIS GROUP's slices to UNVERIFIED (findings kept), never a fabricated
    // verify. The literal "(no write proof)" is the bench checker's degrade sentinel
    // (bench/runner/check.py _DEGRADE_RE) — do not paraphrase it.
    const written = new Set(Array.isArray(result.written) ? result.written : []);
    const dispatchedPaths = group.map((e) => e.path);
    if (!dispatchedPaths.every((p) => written.has(p))) {
      return { ok: false, reason: 'slice-input writer echo did not cover all dispatched slice paths (no write proof)' };
    }
    return { ok: true };
  });

  const results = await c.parallel(thunks);
  const failed = new Map();
  for (let g = 0; g < groups.length; g += 1) {
    const r = results[g];
    // A null member is unreachable while the thunks above swallow their own throws; it is
    // still handled so a platform-side null can never be mistaken for a successful write.
    let reason = null;
    if (!r) reason = `slice-input writer group ${g} produced no result`;
    else if (r.ok !== true) reason = r.reason;
    if (reason === null) continue;
    for (const e of groups[g]) {
      const idx = sliceOfPath.get(e.path);
      if (idx !== undefined) failed.set(idx, { group: g, reason });
    }
  }
  return { failed, expected };
}

function verifySliceWriterPrompt(entries) {
  const payload = JSON.stringify(entries);
  return `Persist each verify slice-input file to disk exactly as given (the workflow has no disk access). For every entry in the payload, write its "content" as JSON to its "path". Return { written } listing the paths you wrote. The payload is the single JSON line after the marker below.\n${WRITER_PAYLOAD_MARKER}${payload}`;
}

// canonicalDeltas(ids, deltas) -> the deltas in a form both runtimes spell identically.
// Rebuilt from the DISPATCHED id order, one object per id, keys in DELTA_KEYS order,
// absent values omitted — so the echo's own array order, key order, and any field it
// invented cannot move the checksum. Only the VALUES the script decided can.
// verify_findings.py's build_deltas() emits exactly this shape in exactly this order.
//
// The rebuild therefore also makes the proof BLIND to any key outside DELTA_KEYS. That is
// deliberate and not a hole: joinVerifyDeltas copies only DELTA_VALUE_KEYS, so a key the
// proof ignores is a key nothing reads — and VERIFY_SCHEMA is deliberately OPEN, so an
// undeclared key genuinely can arrive. Covering it would buy no protection and would cost
// the order- and noise-tolerance that keeps a harmless echo quirk from degrading a slice.
function canonicalDeltas(ids, byId) {
  return ids.map((id) => {
    const src = byId.get(id) || {};
    const out = {};
    for (const k of DELTA_KEYS) if (deltaHas(src, k)) out[k] = src[k];
    return out;
  });
}

// deltaContentProof(ids, deltas) -> "fnv1a32:0x........"
// The workflow half of the delta echo's content proof. Exported because the tests must
// build valid envelopes with the REAL computation rather than a second copy of it — a
// helper that re-derives the canonicalisation would happily agree with a broken one. The
// cross-runtime half is pinned separately, by the golden fixture whose checksum
// verify_findings.py itself produced.
function deltaContentProof(ids, deltas) {
  const byId = new Map();
  for (const d of Array.isArray(deltas) ? deltas : []) {
    // Exact id text — never trim. dispatchableIds, trustSlice, joinVerifyDeltas, and
    // Python's build_deltas all key on the raw id; trimming here made a whitespace-padded
    // dispatched id miss its delta (canonical form silently became {}), so an honest
    // Python deltas_checksum failed the JS recomputation and the whole slice degraded.
    // Two ids differing only by surrounding whitespace also collided into one map entry.
    if (d && typeof d.id === 'string') byId.set(d.id, d);
  }
  return fnv1a32(JSON.stringify(canonicalDeltas(ids || [], byId), null, 2));
}

// A slice envelope is trusted only if it is the honest success shape AND its receipt
// echoes exactly what we dispatched: the nonce (this answer is for OUR call), the head
// sha (same tree the workflow resolved), and n_in (the executor loaded every finding we
// sent). Three guards beyond the receipt, in increasing strength:
//
//   (1) DELTA-ID COVERAGE (#25 req 2) — the echoed deltas must name EXACTLY the ids this
//       slice dispatched: no missing id, no duplicate, no stranger. This replaced a count
//       guard (verified.length + eliminated.length === n_in) that could only ever catch
//       transport truncation: verifySliceSize is a constant, so most slices in a run share
//       a length, and an envelope carrying a SIBLING slice's findings summed identically.
//       That was not a misclassification — the real slice's findings were dropped outright
//       while the run reported verified=true (reproduced end to end during the #54 review).
//       An id set is the cheapest thing that binds an answer to its question.
//   (2) SHAPE AND STAMP — `verified` must be a boolean; the value fields must be the types
//       the script emits; a verified:false delta must carry the elimination_reason stamp
//       run_verification() ALWAYS writes before eliminating ('evidence does not match file
//       content'), and a verified:true delta must NOT carry one. The stamp check is
//       preserved from the by-value design, where it was the only defence against an
//       executor moving a finding verified->eliminated in its echo (observed live: script
//       disk 10v/0e, echo 7v/3e under a valid receipt). It is now redundant with (3) and
//       kept anyway, because a precise reason in the gap is worth more than a checksum
//       mismatch when a human reads the run.
//   (3) CONTENT PROOF — fnv1a32 over the canonical rebuild must equal the checksum the
//       SCRIPT computed over its own deltas. This is what closes coherent drift: an
//       executor that flips one origin, shifts one confidence, or invents a plausible
//       elimination satisfies (1) and (2) and fails here. It is the same checksum pair the
//       persist path uses (assemble_artifacts.py <-> fnv1a32/JSON.stringify here), pinned
//       across runtimes by tests/test_assemble_artifacts.py.
//   (4) INPUT PROOF (issue #69 / #25 req 4-6) — the receipt's checksum over the document
//       the SCRIPT parsed must equal the checksum this stage computed over the content it
//       DISPATCHED. Guards (1)-(3) all grade the executor's answer; this one grades the
//       QUESTION, which nothing before it could see — a slice-input file on disk that is
//       not the document this stage dispatched (stale, truncated, a sibling's) can satisfy
//       every other guard while the script verified the wrong thing. Skipped only when no
//       cross-runtime proof exists (see materializeVerifySlices).
//
// Every failure degrades the WHOLE slice to UNVERIFIED, which is conservative in the
// direction that matters: every dispatched finding is KEPT (origin=unknown, disclosed in a
// gap), so no guard here can be used to drop a real finding.
//
// Threat model: this defends against a STALE, DRIFTING or CONFUSED executor (an old/wrong
// result, a fabricated success, another slice's answer, a garbled transcription) — NOT a
// Byzantine one. The nonce is argv-visible and the checksum travels in the same envelope
// as the data it covers, so a malicious executor could recompute both; an LLM transcribing
// a document cannot, which is exactly the failure class this boundary keeps hitting.
function trustSlice(env, { nonce, headShaShort, n, ids, expectedInputChecksum }) {
  if (!env || typeof env !== 'object') return { ok: false, reason: 'executor returned no envelope' };
  if (env.status !== 'ok') return { ok: false, reason: `status=${env.status == null ? 'missing' : env.status}${env.stderr ? ` (${env.stderr})` : ''}` };
  const r = env.receipt || {};
  if (r.nonce !== nonce) return { ok: false, reason: `receipt nonce mismatch (got ${r.nonce == null ? 'missing' : r.nonce}, expected ${nonce})` };
  if (r.sha !== headShaShort) return { ok: false, reason: `receipt sha mismatch (got ${r.sha == null ? 'missing' : r.sha})` };
  if (r.n_in !== n) return { ok: false, reason: `receipt n_in mismatch (got ${r.n_in == null ? 'missing' : r.n_in}, expected ${n})` };
  const result = env.result || {};
  if (!Array.isArray(result.deltas)) return { ok: false, reason: 'result missing deltas array' };

  const expected = new Set(ids || []);
  const byId = new Map();
  for (const d of result.deltas) {
    if (!d || typeof d !== 'object') return { ok: false, reason: 'delta entry is not an object' };
    const id = typeof d.id === 'string' ? d.id : '';
    if (!id.trim()) return { ok: false, reason: 'delta entry has no id' };
    if (!expected.has(id)) return { ok: false, reason: `delta names a finding this slice did not dispatch (${id})` };
    if (byId.has(id)) return { ok: false, reason: `delta repeats a finding id (${id})` };
    if (typeof d.verified !== 'boolean') return { ok: false, reason: `delta ${id} has no boolean verified flag` };
    for (const k of ['origin', 'severity', 'elimination_reason']) {
      if (deltaHas(d, k) && typeof d[k] !== 'string') return { ok: false, reason: `delta ${id}: ${k} is not a string` };
    }
    // The script canonicalises confidence to an integer precisely so this side never has
    // to agree with Python on how a float is spelled (_delta_confidence). A non-integer
    // here therefore did not come from the script.
    if (deltaHas(d, 'confidence') && !Number.isInteger(d.confidence)) {
      return { ok: false, reason: `delta ${id}: confidence is not an integer` };
    }
    const stamp = typeof d.elimination_reason === 'string' ? d.elimination_reason.trim() : '';
    if (d.verified === false && stamp === '') {
      return { ok: false, reason: `delta ${id}: eliminated without the elimination_reason stamp (fabricated elimination — the verify script always stamps a real one)` };
    }
    if (d.verified === true && stamp !== '') {
      return { ok: false, reason: `delta ${id}: verified finding carries an elimination_reason stamp` };
    }
    byId.set(id, d);
  }
  const missing = (ids || []).filter((id) => !byId.has(id));
  if (missing.length) {
    return { ok: false, reason: `delta does not cover ${missing.length} of ${(ids || []).length} dispatched finding(s) (first: ${missing[0]})` };
  }

  const proof = typeof r.deltas_checksum === 'string' ? r.deltas_checksum.trim() : '';
  if (!proof) return { ok: false, reason: 'receipt carries no deltas_checksum (content proof missing)' };
  const recomputed = deltaContentProof(ids || [], result.deltas);
  if (proof !== recomputed) {
    return { ok: false, reason: `delta content proof mismatch (receipt ${proof}, recomputed ${recomputed}) — the echoed values are not the ones the script wrote` };
  }

  // (4) INPUT PROOF — the receipt's checksum over the document the SCRIPT parsed must
  //     equal the checksum this stage computed over the content it DISPATCHED. Guards
  //     (1)-(3) all grade the executor's answer; this one grades the QUESTION, which
  //     nothing before it could see. Skipped only when no cross-runtime proof exists
  //     (see materializeVerifySlices).
  if (expectedInputChecksum != null) {
    const inputProof = typeof r.input_checksum === 'string' ? r.input_checksum.trim() : '';
    if (!inputProof) {
      // Retryable: a dropped field is a sampled executor's transcription failure, and a
      // fresh sample is a plausible fix.
      return { ok: false, reason: 'input content proof missing from receipt', inputFault: 'missing' };
    }
    if (inputProof !== expectedInputChecksum) {
      // DETERMINISTIC: the file on disk is what it is, and a re-dispatch re-reads the
      // same bytes, so attempt 2 cannot produce a different answer. verifySliceWithRetry
      // short-circuits on this flag rather than spending an executor to learn nothing.
      return {
        ok: false,
        reason: `slice-input content proof mismatch (receipt ${inputProof}, dispatched ${expectedInputChecksum}) — the slice-input file on disk is not the document this stage dispatched`,
        inputFault: 'mismatch',
        deterministic: true,
      };
    }
  }

  return { ok: true };
}

// shellWord(tok) -> the token as ONE shell word. A token of ordinary path characters is
// returned bare, so an ordinary command is byte-identical to a plain `parts.join(' ')`;
// anything else is POSIX single-quoted, which keeps the command AST-safe: with no embedded
// single quote the token is one `raw_string` node to tree-sitter-bash — no expansion, no
// operator, nothing the sandbox's auto-approval parse does not recognise. The charset is
// shlex.quote's: deliberately conservative, since every character outside it only costs a
// pair of quotes. `'\''` closes, escapes, and reopens for an embedded single quote; that
// token parses as a `concatenation` rather than a `raw_string`, so auto-approval is not
// guaranteed on that rare edge (a quote in a repo path) — a correct command is worth more.
const SHELL_SAFE_RE = /^[A-Za-z0-9_%+=:,.\/@-]+$/;
function shellWord(tok) {
  // null/undefined/'' contribute an empty string, exactly as Array.join did: an absent
  // optional field must not materialize a literal `undefined` or a stray `''` in argv.
  if (tok == null) return '';
  const s = String(tok);
  if (s === '' || SHELL_SAFE_RE.test(s)) return s;
  return `'${s.replaceAll("'", `'\\''`)}'`;
}

// The pinned command: a single `python3 <script> --flags...` invocation whose tokens are
// AST-safe (CLAUDE.md AST-safe emission — no command substitution, heredocs, env prefix,
// or shell operators), each shellWord-quoted so a path bearing a space stays ONE argv word
// (issue #75). Per-slice input/output paths are sha-scoped and index-suffixed; verifyStage
// materializes the slice inputs via the artifact-writer (see materializeVerifySlices)
// before dispatch, then the executor reads the slice output.
//
// `sliceNonce` is THREADED IN, never re-derived: it is the same value verifySliceWithRetry
// hands trustSlice as the expected receipt nonce, so argv and the trust check cannot
// disagree. It varies by ATTEMPT as well as by slice (the retry's `.r1` suffix), which is
// exactly what a second, independently-derived formula here would get wrong. The paths do
// NOT vary by attempt: a retry re-runs the same script over the same slice input and
// overwrites the same output.
function verifyCommand(inp, i, sliceNonce) {
  const v = inp.verify || {};
  const inPath = `${v.inputPathBase || 'phase4-input'}.slice${i}.json`;
  const outPath = `${v.outputPathBase || 'phase4-output'}.slice${i}.json`;
  const parts = [
    'python3', v.scriptPath || 'scripts/verify_findings.py',
    '--input', inPath,
    '--output', outPath,
    '--nonce', sliceNonce,
    '--head-sha', inp.headShaShort,
    '--base-branch', v.baseBranch || 'main',
  ];
  if (v.diffPath) parts.push('--diff-file', v.diffPath);
  return parts.map(shellWord).join(' ');
}

// What the executor is asked for is now a PREFIX of the output document, not the whole of
// it: the script writes `result.deltas` as the first key precisely so a length-capped Read
// (which returns no truncation notice — CLAUDE.md) still contains everything this prompt
// names. The large verified/eliminated arrays that follow are for bench and v2 consumers;
// naming them here as explicitly-not-wanted is cheaper than letting the agent decide.
function verifyPrompt(inp, i, sliceNonce) {
  return `Run exactly this command, then read the --output file and return, via the schema: its "status"; its "receipt" object with every field it contains (sha, n_in, nonce, deltas_checksum, and input_checksum when present — never invent an absent one) copied exactly; its top-level "input_recovery" object if the file has one (omit it entirely when the file does not); and every entry of its "result.deltas" array, copied exactly. The same file also holds large "verified" and "eliminated" arrays — do NOT return those and do not summarise them. Copy character for character: the deltas carry a checksum and a single altered value costs this slice its verification.\n${verifyCommand(inp, i, sliceNonce)}`;
}

// --- Agent-count coarsening -------------------------------------------------

const AGENT_COUNT_GUARD = 900;   // stay strictly under the platform fan-out ceiling
const SUMMARIZE_TERM_BOUND = 300; // widen the summarize bucket once its term alone exceeds this
const CHALLENGE_CAP_FLOOR = 5;    // never challenge fewer than this many findings

const ceilDiv = (n, d) => Math.ceil(Math.max(0, n) / Math.max(1, d));

// Issue #24 req 7 (C): the SINGLE accessor path for a stage's effective limit — summarize,
// verifyStage, validateStage, and challengeStage all call these directly rather than
// re-deriving their own fallback, so worstCaseAgentCount/coarsenLimits can never count a
// different fan-out than the stage actually dispatches. normalizeArgs (args.js
// LIMIT_DEFAULTS) fills summarizeBucketSize/validateBatch/verifySliceSize/challengeCap on
// every real waist before a stage ever sees `limits`, so the `|| <literal>` fallbacks below
// are now the DEFENSIVE case (a caller that built `limits` by hand, a test, or a bare
// `coarsenLimits({}, …)` call) rather than the common one. Keep them anyway: a literal
// default here still has to agree with LIMIT_DEFAULTS, but that agreement is not load-
// bearing for a normalized waist.
//
// Mirror challengeStage's cap semantics EXACTLY: an absent/null challengeCap means
// "challenge every finding" (the stage defaults to findings.length), while 0 is a real
// cap of zero. The guard math must never undercount the stage's actual fan-out.
const effectiveChallengeCap = (L, findings) =>
  Math.max(0, L.challengeCap != null ? L.challengeCap : findings);

// Mirror each stage's own absent/zero-size default EXACTLY (summarize: bucket
// LIMIT_DEFAULTS.summarizeBucketSize; verify/validate: ONE slice/batch over all findings) so the
// guard arithmetic can never go NaN (Math.max(1, undefined) is NaN — a NaN worst case silently
// disables the coarsening loop) and never counts a different fan-out than the stage dispatches.
// The four LIMIT_DEFAULTS numbers live in exactly one place (workflows/src/args.js); these
// helpers read it rather than restating a literal.
const effectiveBucketSize = (L) => Math.max(1, L.summarizeBucketSize || LIMIT_DEFAULTS.summarizeBucketSize);
const effectiveSliceSize = (L, findings) => Math.max(1, L.verifySliceSize || findings || 1);
const effectiveBatchSize = (L, findings) => Math.max(1, L.validateBatch || findings || 1);

// Issue #204: the discovery-intake line-span bound (see its call site in discover()).
// Same accessor pattern as its siblings above — read the ONE LIMIT_DEFAULTS constant
// rather than restating the literal here.
const effectiveMaxLineSpan = (L) => Math.max(1, L.maxLineSpan || LIMIT_DEFAULTS.maxLineSpan);

// worstCaseAgentCount(limits, nFiles, nFindings) -> number
// summarize buckets (+1 merge) + the 7 discovery agents + verify slices + validate
// batches + min(nFindings, challengeCap) challengers + 2 (report + writer).
//
// The verify term counts VERIFY_ATTEMPTS_PER_SLICE dispatches per slice, because every
// slice can independently take its one deterministic retry (verifySliceWithRetry) and a
// worst case that assumes the happy path is not a bound. The remaining terms are still
// NOMINAL: the report/writer pair can segment, and writeArtifactsDerived has its own
// single retry, neither of which is counted here. That looseness is covered by the
// headroom between AGENT_COUNT_GUARD and the platform ceiling; the verify term is the one
// that scales with finding count, which is why it is the one made exact.
function worstCaseAgentCount(limits, nFiles, nFindings) {
  const L = limits || {};
  const files = Math.max(0, nFiles || 0);
  const findings = Math.max(0, nFindings || 0);
  const summarizeCalls = ceilDiv(files, effectiveBucketSize(L)) + 1;
  const verifyCalls = ceilDiv(findings, effectiveSliceSize(L, findings)) * VERIFY_ATTEMPTS_PER_SLICE;
  const validateCalls = ceilDiv(findings, effectiveBatchSize(L, findings));
  const challengeCalls = Math.min(findings, effectiveChallengeCap(L, findings));
  return summarizeCalls + AGENTS.length + verifyCalls + validateCalls + challengeCalls + 2;
}

// coarsenLimits(limits, nFiles, nFindings) -> limits
// Iteratively pulls the worst-case count below the guard. Each iteration strictly
// decreases the count:
//   - When the summarize term alone exceeds SUMMARIZE_TERM_BOUND, widen the bucket
//     (doubling). Without this, a pathological changed-file count (~>17k) keeps the
//     summarize term above the guard and no validate/challenge coarsening can converge.
//   - Otherwise reduce whichever of {verify, validate, challenge} is currently largest:
//     RAISE verifySliceSize / validateBatch (fewer batches, since ceil(n/x) shrinks) or
//     LOWER challengeCap (the challenge term is min(n, cap), so a SMALLER cap lowers the
//     count — raising it is the inversion trap).
// summarizeBucketSize / validateBatch / verifySliceSize rise monotonically while
// challengeCap falls to CHALLENGE_CAP_FLOOR, so the chosen term is always reducible
// whenever the count is still >= guard, guaranteeing termination.
function coarsenLimits(limits, nFiles, nFindings) {
  const L = { ...(limits || {}) };
  const files = Math.max(0, nFiles || 0);
  const findings = Math.max(0, nFindings || 0);

  while (worstCaseAgentCount(L, files, findings) >= AGENT_COUNT_GUARD) {
    const summarizeTerm = ceilDiv(files, effectiveBucketSize(L)) + 1;
    if (summarizeTerm > SUMMARIZE_TERM_BOUND) {
      // Double from the EFFECTIVE size (pinning a concrete value): doubling from a raw
      // absent field (|| 1 -> 2) would LOWER the effective bucket below the stage's
      // default of 20 and move the term the wrong way.
      L.summarizeBucketSize = effectiveBucketSize(L) * 2;
      continue;
    }
    // Same VERIFY_ATTEMPTS_PER_SLICE scaling worstCaseAgentCount applies, so the "reduce
    // whichever term is largest" choice is made against each term's real contribution to
    // the count it is trying to pull down. Doubling verifySliceSize still strictly halves
    // this term, so the loop's termination argument is unchanged.
    const verifyTerm = ceilDiv(findings, effectiveSliceSize(L, findings)) * VERIFY_ATTEMPTS_PER_SLICE;
    const validateTerm = ceilDiv(findings, effectiveBatchSize(L, findings));
    const challengeTerm = Math.min(findings, effectiveChallengeCap(L, findings));
    if (validateTerm >= verifyTerm && validateTerm >= challengeTerm) {
      L.validateBatch = effectiveBatchSize(L, findings) * 2;
    } else if (verifyTerm >= validateTerm && verifyTerm >= challengeTerm) {
      L.verifySliceSize = effectiveSliceSize(L, findings) * 2;
    } else {
      // Halve the EFFECTIVE cap (min(cap, findings)) so C strictly decreases even when
      // the nominal cap already exceeds nFindings — or is absent (= findings).
      L.challengeCap = Math.max(CHALLENGE_CAP_FLOOR, Math.floor(Math.min(effectiveChallengeCap(L, findings), findings) / 2));
    }
  }
  return L;
}

// --- Phase 5: Validate ------------------------------------------------------

// The validator independently re-scores a batch of findings, one entry per finding it
// chose to score (it may omit some, which then keep their original confidence). The
// entries are an array, but the DISPATCH schema must be OBJECT-rooted: the Messages API
// rejects an array-rooted tool input_schema with `tools.N.custom.input_schema.type:
// Input should be 'object'` (the 400 the live smoke run hit). So the array is wrapped in
// a { validations: [...] } object; validateStage unwraps `.validations` at the consumer.
const VALIDATE_SCHEMA = {
  type: 'object',
  properties: {
    validations: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          finding_id: { type: 'string' },
          confidence: { type: 'number' },
          justification: { type: 'string' },
          reachability: { type: 'string', enum: REACHABILITY_VALUES },
        },
        required: ['finding_id', 'confidence'],
      },
    },
  },
  required: ['validations'],
};

function validateReturnDescriptor() {
  return Object.entries(VALIDATE_SCHEMA.properties.validations.items.properties)
    .map(([name, schema]) => {
      const values = Array.isArray(schema.enum) ? ` (${schema.enum.join(' | ')})` : '';
      return `${name}${values}`;
    })
    .join(', ');
}

// validateStage(ctx, input) -> { findings, gaps, stats }
// Batches findings into limits.validateBatch chunks and dispatches ONE validator per
// batch through parallel(). applyValidations merges the returned confidence
// adjustments into the findings IN PLACE (id match, [0,100] clamp, original_confidence
// captured once). parallel() nulls a failed member in place, so results are positionally
// aligned with `batches` — attribution is by INDEX (like discover), not .filter(Boolean),
// because a degraded batch must be traced back to the exact findings it left unvalidated.
// A null/malformed batch means its findings went UNVALIDATED: they are kept at face value
// (conservative — never dropped, confidence never touched) and marked validation='skipped'
// with a loud gap. Every surviving finding ends marked validation='validated' or 'skipped'.
async function validateStage(ctx, input) {
  const c = ctx || defaultCtx();
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const findings = inp.findings || [];
  const limits = inp.limits || {};
  const policy = inp.policy || {};
  const batchSize = effectiveBatchSize(limits, findings.length);

  if (findings.length === 0) {
    return { findings: [], gaps: [], stats: { batches_dispatched: 0, batches_completed: 0, validated: 0, skipped: 0, adjusted: 0 } };
  }

  const model = modelFor('code-gauntlet:validator', policy);

  const batches = [];
  for (let i = 0; i < findings.length; i += batchSize) batches.push(findings.slice(i, i + batchSize));

  const thunks = batches.map((batch, idx) => () => c.agent(validatePrompt(inp, batch), {
    label: `validate-batch-${idx}`,
    agentType: 'code-gauntlet:validator',
    model,
    schema: VALIDATE_SCHEMA,
  }));

  const results = await c.parallel(thunks);

  const gaps = [];
  const validations = [];
  const skippedSet = new Set(); // finding REFERENCES (immune to a missing/duplicate id)
  let completed = 0;

  results.forEach((res, idx) => {
    const batch = batches[idx];
    const list = res === null || res === undefined
      ? null
      : (Array.isArray(res) ? res : (Array.isArray(res.validations) ? res.validations : null));
    if (list === null) {
      gaps.push(`validate-batch-${idx}: validator returned null/malformed — ${batch.length} finding(s) unvalidated (validation=skipped, kept conservatively)`);
      for (const f of batch) skippedSet.add(f);
      return;
    }
    completed += 1;
    // Field-name normalization (v2 SKILL parity): the validator agent's shipped
    // output format emits `finding_id` (agents/validator.md), but applyValidations
    // matches on `id`. Accept BOTH the .md-shaped (`finding_id`) and schema-shaped
    // (`id`) entries so a real validator dispatch actually merges — without this the
    // adjustments silently never match and every finding keeps its raw confidence.
    for (const e of list) {
      validations.push(e && typeof e === 'object' ? { ...e, id: e.id ?? e.finding_id } : e);
    }
  });

  const { adjustedCount } = applyValidations(findings, validations);

  let skipped = 0;
  for (const f of findings) {
    if (skippedSet.has(f)) { f.validation = 'skipped'; skipped += 1; }
    else f.validation = 'validated';
  }

  return {
    findings,
    gaps,
    stats: {
      batches_dispatched: batches.length,
      batches_completed: completed,
      validated: findings.length - skipped,
      skipped,
      adjusted: adjustedCount,
    },
  };
}

function validatePrompt(inp, batch) {
  const ctxLine = inp.contextLine || '';
  // Each finding carries its location + claim so the validator can open the right code
  // (validator.md step 1: "Read the code at the file and line range specified"). Passing
  // only ids left validators unable to locate anything — they scored blind.
  const block = batch.map((f) => {
    const range = f.line_end != null && f.line_end !== f.line_start
      ? `${f.line_start}-${f.line_end}`
      : `${f.line_start != null ? f.line_start : '?'}`;
    const ev = f.evidence ? ` | evidence: ${f.evidence}` : '';
    return `- ${f.id} [${f.dimension || '?'}/${f.severity || '?'}] ${f.file || '?'}:${range} — ${f.description || ''}${ev}`;
  }).join('\n');
  return `${ctxLine}Independently validate this batch of findings. For each, Read the code at the file and line range shown, attempt to disprove the claim, and score it. Findings:\n${block}\nReturn { validations: [{ ${validateReturnDescriptor()} }] } — confidence 0-100 (one entry per finding you scored; omit the rest).`;
}

// --- Phase 6: Filter --------------------------------------------------------

// filterStage(input) -> applyFilterPipeline envelope. PURE and deterministic: no ctx,
// no agents (that is the whole point of the JS twin). `reviewConfig` is the parsed
// REVIEW.md object (thresholds + ignore list) and `exclusionPatterns` the parsed
// exclusions list, both prepared upstream (parseReviewMd / loadExclusions). generatedAt
// is threaded from the args waist into the envelope's generated_at — never new Date().
function filterStage(input) {
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const findings = inp.findings || [];
  const config = inp.reviewConfig || {};
  const exclusionPatterns = inp.exclusionPatterns || [];
  return applyFilterPipeline(findings, config, exclusionPatterns, inp.generatedAt);
}

// --- Phase 7: Challenge -----------------------------------------------------

// The challenger agent (agents/challenger.md) emits
// { confidence_claim_is_correct, justification }; the stage reads that field (?? score)
// and injects the KNOWN finding id by index (never trusts the challenger to echo it).
const CHALLENGE_SCHEMA = {
  type: 'object',
  properties: {
    confidence_claim_is_correct: { type: 'number' },
    justification: { type: 'string' },
  },
  required: ['confidence_claim_is_correct'],
};

// blindChallengeFields(finding) -> { title, description, file, line_start, line_end }
// STRUCTURAL blindness guarantee: the blind challenger sees ONLY these keys — the claim
// (title/description) plus the LOCATION so it can open the raw code itself (challenger.md
// has Read/Grep/LSP and is told to read the code at the location). Selecting them
// explicitly (an allowlist, not a delete-list) means no confirming context — evidence,
// origin, cross_file_refs, corroborated_by, the original agent's reasoning — can ever
// reach the challenger, and stays impossible even if new reasoning-bearing fields are
// added to findings later. The prior `code` field was never populated anywhere in the
// pipeline, so the challenger always received an empty code block; location + the agent's
// own tools replaces that dead field. Unit-tested both ways: the returned object has
// exactly these keys and the built prompt leaks none of the rest.
function blindChallengeFields(finding) {
  return {
    title: finding.title || '',
    description: finding.description || '',
    file: finding.file || '',
    line_start: finding.line_start != null ? finding.line_start : '',
    line_end: finding.line_end != null ? finding.line_end : '',
  };
}

// Hill-climb iter 5: teeth + unverifiable-claim gate. The challenger must VERIFY the
// claim's central factual assertion against the raw code, and score any claim it cannot
// confirm from the code+context at or below 25 (below 25 removes non-security findings
// downstream; see applyChallenges thresholds). This targets the two noise clusters the
// subset diagnosis surfaced: test-coverage "no test exists" negatives and
// cross_file_impact claims that cite no in-diff evidence. Still fully blind — only
// {title, description, file, line_start, line_end} reach the challenger.
function challengePrompt(finding) {
  const b = blindChallengeFields(finding);
  const range = b.line_end !== '' && b.line_end !== b.line_start ? `${b.line_start}-${b.line_end}` : `${b.line_start}`;
  return `You are a blind challenger. You have NOT seen the original reviewer's rationale — assess this claim on its own merits and try to disprove it. First VERIFY the claim's central factual assertion against the raw code: the claim concerns ${b.file}:${range} — open that location and enough surrounding context yourself (Read/Grep/LSP), find the specific lines the claim rests on, and confirm they actually say what the claim needs them to say. If that central assertion cannot be verified from the code and context — for example a test-coverage "no test exists" or missing-coverage claim you cannot confirm, or a cross-file-impact claim that cites no in-diff evidence — treat the claim as UNVERIFIABLE and score it 25 or below (below 25 when nothing in the code confirms it, so it does not survive). Reserve scores above 25 for claims whose central assertion you positively confirmed in the code.\nClaim: ${b.title}\n${b.description}\nLocation to inspect: ${b.file}:${range}\nReturn { confidence_claim_is_correct, justification }; confidence_claim_is_correct 0-100 (higher = the claim holds).`;
}

// challengeStage(ctx, input) -> { findings, unverified, eliminated, gaps, stats, generated_at }
// Ranks the incoming findings and blind-challenges the top min(n, limits.challengeCap)
// through parallel() — one challenger per finding, each fed ONLY blindChallengeFields.
// parallel() nulls a failed member in place, so results are positionally aligned with the
// candidate list (attribution by INDEX — a degraded member must be traced to its exact
// finding). A finding counts as CHALLENGED only when its member returned an int-coercible
// score; applyChallenges then applies the blind-score thresholds (remove / downgrade /
// contest / survive), re-runs cross-agent dedup, and ranks — that ranked set is the
// high-confidence bucket. Every UNCHALLENGED finding — cap overflow OR a null/unscored
// member — is marked challenge='skipped' and routed to `unverified` (the pipeline-degraded
// section); it NEVER enters the high-confidence bucket. Only genuinely-challenged findings
// flow into applyChallenges, so its `unchallenged` pass-through (which would land a finding
// in the high-confidence set) can never fire here. Records dispatched-vs-completed counts.
async function challengeStage(ctx, input) {
  const c = ctx || defaultCtx();
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const findings = inp.findings || [];
  const limits = inp.limits || {};
  const policy = inp.policy || {};
  const cap = effectiveChallengeCap(limits, findings.length);

  if (findings.length === 0) {
    return {
      findings: [], unverified: [], eliminated: [], gaps: [],
      stats: {
        total_input: 0, dispatched: 0, completed: 0, skipped: 0,
        challenge_removed: 0, challenge_downgraded: 0, challenge_contested: 0,
        challenge_survived: 0, unchallenged: 0, cross_agent_consolidated: 0, final_count: 0,
      },
      generated_at: inp.generatedAt,
    };
  }

  const model = modelFor('code-gauntlet:challenger', policy);

  // Rank first so the cap, when it bites, challenges the HIGHEST-priority findings;
  // the lower-ranked overflow is skipped (routed to `unverified`, never dropped).
  const ranked = rankFindings(findings);
  const candidates = ranked.slice(0, cap);
  const overflow = ranked.slice(cap);

  const thunks = candidates.map((finding, idx) => () => c.agent(challengePrompt(finding), {
    label: `challenge-${idx}`,
    agentType: 'code-gauntlet:challenger',
    model,
    schema: CHALLENGE_SCHEMA,
  }));

  const results = thunks.length ? await c.parallel(thunks) : [];

  const gaps = [];
  const challenged = [];
  const challenges = [];
  const skipped = [];

  results.forEach((res, idx) => {
    const finding = candidates[idx];
    // Field-name normalization (v2 SKILL parity): the challenger agent's shipped
    // output format emits `confidence_claim_is_correct` (agents/challenger.md), not
    // `score`. Accept BOTH so a real challenger dispatch is scored — without this
    // every result reads unscored, every finding is skipped, and the high-confidence
    // bucket is ALWAYS empty. `??` (not `||`) so a legitimate 0 score is honoured.
    const rawScore = res && typeof res === 'object' ? (res.confidence_claim_is_correct ?? res.score) : undefined;
    if (res === null || res === undefined || pyIntStrict(rawScore) === null) {
      gaps.push(`challenge-${idx}: challenger returned null/unscored — finding ${finding.id} unchallenged (challenge=skipped, pipeline-degraded)`);
      skipped.push(finding);
      return;
    }
    // Pair the score with the KNOWN finding id (never trust the challenger to echo it).
    challenges.push({ id: finding.id, score: rawScore, justification: res.justification });
    challenged.push(finding);
  });

  for (const f of overflow) skipped.push(f);
  if (overflow.length) {
    gaps.push(`challenge: ${overflow.length} finding(s) over challengeCap=${cap} left unchallenged (challenge=skipped, pipeline-degraded)`);
  }

  const applied = applyChallenges(challenged, challenges);

  // Mark + rank the degraded section. Shallow-clone so the caller's findings stay
  // untouched (applyChallenges likewise clones the survivors it mutates).
  const unverified = rankFindings(skipped.map((f) => ({ ...f, challenge: 'skipped' })));

  return {
    findings: applied.findings,
    unverified,
    eliminated: applied.eliminated,
    gaps,
    stats: {
      total_input: findings.length,
      dispatched: candidates.length,
      completed: challenged.length,
      skipped: skipped.length,
      challenge_removed: applied.stats.challenge_removed,
      challenge_downgraded: applied.stats.challenge_downgraded,
      challenge_contested: applied.stats.challenge_contested,
      challenge_survived: applied.stats.challenge_survived,
      unchallenged: applied.stats.unchallenged,
      cross_agent_consolidated: applied.stats.cross_agent_consolidated,
      final_count: applied.stats.final_count,
    },
    generated_at: inp.generatedAt,
  };
}

// --- Phase 8: Delivery selection --------------------------------------------

// selectDelivery(survivors, cap, tier) -> rank-ordered top-cap delivery set.
// The deterministic Phase 8 delivery policy: the pipeline — not the live agent — decides
// what gets posted, honoring the user-chosen delivery TIER (resolved at Phase 1, threaded
// through args.delivery.tier):
//   - 'all' (the default — interactive Recommended, headless CODE_GAUNTLET_DELIVERY_TIER
//     default): every challenge-survivor is a delivery candidate regardless of its
//     report_tag (main AND suggestion alike);
//   - 'main_only': keep only main-tagged survivors (suggestions stay in the report but are
//     not posted as PR comments).
// Any tier value other than 'main_only' (including undefined/null) resolves to 'all', so the
// no-silent-narrowing default holds. The report_tag is set by tagFindings/applyChallenges
// (report_destination is the older alias); tagFindings itself is unchanged — the tag stays
// meaningful metadata that this selection reads, never mutates. rankFindings then orders the
// pool (severity, confidence, risk/description) and `cap` truncates: a null/undefined cap
// means "no cap", a numeric cap keeps the top-cap floored at 0 (mirrors challengeStage's
// Math.max(0, ...) idiom so a 0/negative cap yields an empty set rather than throwing). PURE
// — never mutates its input (rankFindings copies) — and exported so the live agent consumes
// the result verbatim and never re-filters or re-ranks. Challenge-removed / challenge-skipped
// findings are already absent from `survivors`, so they stay excluded exactly as before.
function selectDelivery(survivors, cap, tier) {
  const pool = tier === 'main_only'
    ? (survivors || []).filter((f) => (f.report_tag ?? f.report_destination) === 'main')
    : (survivors || []);
  // Rank the renderer-owned tolerant projection, then map back to the original entries so
  // persistence keeps its byte/identity relationship with the challenge output.
  const rankable = coerceReportFindings(pool);
  const originalByRankable = new Map(rankable.map((finding, index) => [finding, pool[index]]));
  const ranked = rankFindings(rankable).map((finding) => originalByRankable.get(finding));
  if (cap === undefined || cap === null) return ranked;
  return ranked.slice(0, Math.max(0, cap));
}

// --- Persistence: writeArtifacts --------------------------------------------

const WRITER_SCHEMA = {
  type: 'object',
  properties: { artifactPaths: { type: 'object', properties: {} } },
};
// The verify slice-input writer returns the list of paths it wrote.
const WRITTEN_SCHEMA = {
  type: 'object',
  properties: { written: { type: 'array', items: { type: 'string' } } },
};

// Issue #148: Persist outputDir-prefix fence. One predicate for stamp throws and
// writer-echo gaps. Sandbox has no fs/realpath — string normalize then prefix only.
// Deliberately do NOT collapse `//` (still under the fence; collapsing it would be a
// separate normalizer that tests would then need to pin). Reject `..` outright — do not
// resolve it textually (symlinks make a/b/../c ≠ a/c). Reject `\` so a Windows separator
// cannot sail past a /-based prefix test.

/** Gap token for writer-reported paths outside outputDir. Registered in docs/machine-parsed-strings.md; G3 still keys off the surrounding `(partial-artifacts)` suffix. */
const PATH_ESCAPE_TOKEN = 'path-escape';

function collapseDotSlash(p) {
  let out = p;
  for (;;) {
    const next = out.replace(/\/\.\//g, '/');
    if (next === out) return out;
    out = next;
  }
}

function stripTrailingSlashes(p) {
  let out = p;
  while (out.length > 1 && out.endsWith('/')) out = out.slice(0, -1);
  return out;
}

// Collapse `/./` then strip trailing `/` (and a leftover trailing `/.` from `..././`).
// Deliberately does NOT collapse `//` — still under the fence; see #148 design.
function normalizePathString(p) {
  let out = p;
  for (;;) {
    let next = stripTrailingSlashes(collapseDotSlash(out));
    if (next.endsWith('/.')) next = next.length === 2 ? '/' : next.slice(0, -2);
    next = stripTrailingSlashes(next);
    if (next === out) return next;
    out = next;
  }
}

function hasBackslash(s) {
  return s.includes('\\');
}

function hasDotDotSegment(s) {
  return s.split('/').includes('..');
}

// Normalize an absolute confined root, or null if it fails the absolute/root arms.
function normalizeOutputDirRoot(outputDir) {
  if (typeof outputDir !== 'string' || outputDir === '') return null;
  const root = normalizePathString(outputDir);
  if (!root.startsWith('/') || hasBackslash(root) || hasDotDotSegment(root)) return null;
  return root;
}

function requireAbsoluteOutputDir(outputDir) {
  const root = normalizeOutputDirRoot(outputDir);
  if (root === null) {
    throw new Error(
      `outputDir must be an absolute confined root (POSIX /-prefix, no .. or \\ segments); got ${JSON.stringify(outputDir)}`,
    );
  }
  return root;
}

// True iff path is under the absolute outputDir root after the shared normalize arms.
// Empty / null / undefined path → false (gap, not TypeError). Bad root → false.
function pathUnderOutputDir(outputDir, path) {
  const root = normalizeOutputDirRoot(outputDir);
  if (root === null) return false;
  if (typeof path !== 'string' || path === '') return false;
  const p = normalizePathString(path);
  if (!p.startsWith('/') || hasBackslash(p) || hasDotDotSegment(p)) return false;
  // Equality arm: path === root must pass (startsWith(root + '/') alone would reject it).
  return p === root || p.startsWith(`${root}/`);
}

function assertPlannedPathUnderOutputDir(outputDir, path) {
  if (!pathUnderOutputDir(outputDir, path)) {
    throw new Error(`planned artifact path escapes outputDir: ${path}`);
  }
}

// Collect writer-reported fields that fail the fence. Check ALL present fields (do not
// bail early) so the one gap can name every escape. Missing keys are left to write-proof
// (`{}` echo → "no write proof"); an explicit null/empty still fails the fence (gap, not
// TypeError). Persist remains all-or-nothing on partial().
function pathEscapeReason(outputDir, fields) {
  const escaped = [];
  for (const { name, path, present } of fields) {
    if (!present) continue;
    if (!pathUnderOutputDir(outputDir, path)) {
      escaped.push(`${name}=${path == null ? String(path) : path}`);
    }
  }
  if (!escaped.length) return null;
  return `${PATH_ESCAPE_TOKEN}: writer-reported paths outside outputDir (${escaped.join(', ')})`;
}

// The four artifacts writeArtifacts plans (and asks the writer to echo). Exported so a
// faithful mock/recorder echoes the SAME paths the write-proof gate checks against — the
// gate rejects any echo that fails to account for all four planned paths.
// Issue #148: requires absolute outputDir; every stamped path must pass pathUnderOutputDir
// or this throws (programming-error / stamp regression — not a partial-artifacts gap).
function plannedArtifactPaths(outputDir, sha) {
  const root = requireAbsoluteOutputDir(outputDir);
  const paths = {
    findings: `${root}/code-gauntlet-findings-${sha}.json`,
    report: `${root}/code-gauntlet-report-${sha}.md`,
    postReview: `${root}/code-gauntlet-post-review-${sha}.json`,
    checkpoints: `${root}/${checkpointPath('all', sha)}`,
  };
  for (const p of Object.values(paths)) assertPlannedPathUnderOutputDir(root, p);
  return paths;
}
const ARTIFACT_PATH_KEYS = ['findings', 'report', 'postReview', 'checkpoints'];

// Write-proof: the echoed artifactPaths must account for EVERY planned path (each key
// present and echoing the exact path we dispatched). WRITER_SCHEMA declares no `required`,
// so an empty {} echo is schema-valid — a writer under StructuredOutput retry pressure can
// return one having written nothing. Same threat model as trustSlice: a self-reported echo
// is a consistency/liveness check, not proof-of-write, but requiring the four exact paths
// stops a degenerate {} (or a partial echo) from passing as a full persist.
function writerEchoCoversPaths(echoed, paths) {
  if (!echoed || typeof echoed !== 'object') return false;
  return ARTIFACT_PATH_KEYS.every((k) => echoed[k] === paths[k]);
}

// writeArtifacts(ctx, { findings, postReview, report, checkpoints, outputDir,
// headShaShort, policy, persist }) -> { artifactPaths, gaps, partial }
// The workflow script has NO disk access, so agents persist findings.json + report.md
// + the post-review delivery set + the checkpoint/progress JSON to {output_dir}.
//
// THREE persistence paths, one PUBLIC contract (same return shape, the same four
// artifactPaths keys, the same partial-artifacts degradation):
//
//   RETURN (taken whenever args.persist.returnPrimaries is true — the primary path, and
//     independent of assembleScriptPath, which only the writer path's executor needs).
//     No agent is dispatched at all. The three primaries ride home in the workflow's
//     own return value, which the HARNESS serializes; Phase 8 materializes them with
//     scripts/materialize_artifacts.py and derives the projections from disk. See
//     returnChannelPersist for the measurement and the failure mode it removes.
//
//   DERIVED (issue #38, D3; taken when args.persist.assembleScriptPath is present and
//     the return channel was not asked for or could not carry the run).
//     Measured on a real run: of the 88,389 B the writer emitted, the post-review
//     findings array was canonically byte-identical to findings.json, the checkpoint's
//     phases.challenge.findings was the alias-stripped twin of the same array, and the
//     genuine residual was 383 B. So the writer now persists ONLY the unique content
//     (findings.json, report.md, the persist plan) and the executor runs the pinned
//     scripts/assemble_artifacts.py to DERIVE the two projections from what actually
//     landed on disk, returning a content-proof receipt.
//
//   LEGACY (no persist waist, or the id-integrity guard refused). One artifact-writer
//     dispatch carrying all four artifacts by value. Unchanged.
//
// Wrapped in its own try/catch: a throw OR null result degrades to
// a partial-artifacts gap with null paths and is NON-FATAL — it never bubbles to the
// top-level catch. The try covers the WHOLE body, not just the dispatches: the derived
// path computes the plan and the primaries (JSON.stringify over caller-supplied objects,
// a deep clone of the checkpoint) BEFORE any agent is called, and a throw there is exactly
// as non-fatal as a writer failure. Keeping those computations outside the guard is the
// regression this shape exists to prevent — SKILL.md's Error Recovery promises the caller
// that writer failure never ends the run.
// `salvaged` (optional, derived path only) names the primaries a refused assemble receipt
// nevertheless PROVED are on disk byte-identical to the payload — see provenPrimaryPaths.
// They are surfaced instead of nulled so Phase 8's documented "deliver whatever
// artifactPaths.report exists" branch is reachable. `partial` stays true and the failure
// gap stays, so nothing downstream mistakes this for a successful persist; the DERIVED
// paths are always null here because nothing derived them.
async function writeArtifacts(ctx, input) {
  const partial = (reason, extraGaps, salvaged) => ({
    artifactPaths: {
      findings: (salvaged && salvaged.findings) || null,
      report: (salvaged && salvaged.report) || null,
      postReview: null,
      checkpoints: null,
    },
    gaps: (extraGaps || []).concat([
      `writeArtifacts: ${reason} — artifacts not persisted (partial-artifacts)`
      // Never silently imply more landed than did: the salvaged paths are named, and a
      // run with nothing salvaged reads exactly as it did before.
      + (salvaged && (salvaged.findings || salvaged.report)
        ? ` — content-proven on disk and still usable: ${[salvaged.findings, salvaged.report].filter(Boolean).join(', ')}`
        : ''),
    ]),
    partial: true,
  });

  // Issue #148: absolute outputDir + planned-path stamp BEFORE the outer try so a
  // programming-error / stamp regression throws to runWith ({ ok:false }) instead of
  // being softened into a partial-artifacts gap. No relative fallback — omitting or
  // passing a relative outputDir is the same class of failure as a stamp escape.
  const c = ctx || defaultCtx();
  const inp = typeof input === 'string' ? JSON.parse(input) : (input || {});
  const outputDir = requireAbsoluteOutputDir(inp.outputDir);
  const sha = inp.headShaShort || 'head';
  const policy = inp.policy || {};
  const paths = plannedArtifactPaths(outputDir, sha);

  try {
    const persist = inp.persist || {};
    const scriptPath = typeof persist.assembleScriptPath === 'string' && persist.assembleScriptPath !== ''
      ? persist.assembleScriptPath
      : null;
    // The two flags are read INDEPENDENTLY. `returnPrimaries` used to be consulted only
    // inside the script-path branch, which made `{ returnPrimaries: true }` alone opt a
    // caller silently into the legacy by-value writer — the one path with no content proof
    // at all — while its args said it had opted out of transcription entirely. The return
    // channel has no use for the script: Phase 8's materializer imports the assembler
    // directly, so the path is only ever needed by the executor dispatch on the writer
    // path, and requiring it here would be a dependency that does not exist.
    const wantsReturn = persist.returnPrimaries === true;
    if (scriptPath || wantsReturn) {
      // The guard that keeps BOTH derived paths safe under pathological input. Every
      // projection is by finding id, so a missing/duplicate id — or a delivery/challenge
      // entry that is not a byte-identical twin of its findings.json row — makes the
      // derivation unfaithful. Rather than degrade the run (null paths, no artifacts) we
      // fall back to the legacy full by-value writer and name the reason in a gap.
      const derivable = persistDerivable(inp);
      if (derivable.ok) {
        // The RETURN channel first: it dispatches nothing and is the only path on which
        // no model transcribes the bytes. Its ONE refusal is size (see RETURN_CHAR_BUDGET),
        // and it falls through to a writer rather than degrading the run — the derived one
        // when a script path is in hand, the legacy one otherwise. Either way the fallback
        // says what it costs, because a run that quietly demoted to a transcriber is
        // exactly the failure this channel exists to remove.
        if (wantsReturn) {
          const viaReturn = returnChannelPersist(inp, paths, outputDir, sha);
          if (viaReturn.ok) return viaReturn.result;
          const gap = `writeArtifacts: ${viaReturn.reason} — persisted through the artifact-writer instead, which transcribes the bytes`;
          if (!scriptPath) return await writeArtifactsLegacy(c, inp, paths, outputDir, policy, partial, [gap]);
          const fallback = await writeArtifactsDerived(c, inp, paths, outputDir, sha, policy, partial, scriptPath);
          return { ...fallback, gaps: [gap].concat(fallback.gaps || []) };
        }
        return await writeArtifactsDerived(c, inp, paths, outputDir, sha, policy, partial, scriptPath);
      }
      return await writeArtifactsLegacy(c, inp, paths, outputDir, policy, partial, [
        `writeArtifacts: derived persistence unavailable (${derivable.reason}) — persisted the full by-value payload instead`,
      ]);
    }
    // No persist waist: the documented clean degradation for older callers (bench
    // included). Legacy path, no gap — nothing was lost, only latency.
    return await writeArtifactsLegacy(c, inp, paths, outputDir, policy, partial, []);
  } catch (e) {
    return partial(`persistence threw before any artifact was written (${(e && e.message) || 'unknown'})`, []);
  }
}

// The legacy full by-value persist: ONE artifact-writer dispatch carrying all four
// artifacts. `extraGaps` rides along on both the success and the degradation return so
// an id-integrity fallback is always visible in the envelope.
async function writeArtifactsLegacy(c, inp, paths, outputDir, policy, partial, extraGaps) {
  const model = modelFor('code-gauntlet:artifact-writer', policy);
  try {
    const result = await c.agent(writeArtifactsPrompt(inp, paths), {
      label: 'artifact-writer',
      agentType: 'code-gauntlet:artifact-writer',
      model,
      schema: WRITER_SCHEMA,
    });
    if (!result) return partial('writer returned null', extraGaps);
    // Issue #148: check EVERY echoed path field; one gap naming each escape; all-or-nothing
    // null via partial() (same shape as write-proof failure).
    const echoed = result.artifactPaths;
    const escape = pathEscapeReason(
      outputDir,
      ARTIFACT_PATH_KEYS.map((k) => ({
        name: k,
        path: echoed ? echoed[k] : undefined,
        present: !!(echoed && Object.hasOwn(echoed, k)),
      })),
    );
    if (escape) return partial(escape, extraGaps);
    if (!writerEchoCoversPaths(echoed, paths)) {
      return partial('writer echo did not account for all four planned artifact paths (no write proof)', extraGaps);
    }
    return { artifactPaths: paths, gaps: extraGaps, partial: false };
  } catch (e) {
    return partial(`writer agent threw (${(e && e.message) || 'unknown'})`, extraGaps);
  }
}

// persistEntries(inp, paths, outputDir, sha) -> { plan, planPath, entries }
//
// The ONE serialization of the three primaries, shared by both channels that persist them:
// the RETURN channel carries these entries home for Phase 8 to write, the derived writer
// path dispatches these same entries to be transcribed. A second copy of this arithmetic
// would be a second spelling of the same three documents, drifting apart the moment either
// side changed — and the plan's `expect[]` proves the primaries by checksum, so a drift is
// a failed content proof on whichever channel did not get the edit.
//
// The plan text is escape-hardened for the WIRE (see hardenEscapeRuns), which is
// load-bearing on the writer path — the plan is transcribed by the same model and carries
// checkpoint prose, and a mangled plan is a HARD failure (bad planChecksum) rather than a
// tolerated mismatch — and dead weight on a channel with no transcriber. It is applied to
// both anyway: hardening cannot move a proof (assemble_artifacts.py recomputes
// planChecksum from the PARSED plan, and `\u005c` parses to the same backslash `\\` does),
// so the cost of one spelling is nothing and the cost of two is a divergence.
function persistEntries(inp, paths, outputDir, sha) {
  const planPath = persistPlanPath(outputDir, sha);
  const { findingsJson, reportMd } = persistPrimaries(inp);
  // Kept as an OBJECT as well as a string: trustAssembleReceipt grades the receipt against
  // the expectations the pipeline itself computed, never against the ones the receipt
  // echoes back at us.
  const plan = persistPlan(inp, paths);
  return {
    plan,
    planPath,
    entries: [
      { path: paths.findings, text: findingsJson },
      { path: paths.report, text: reportMd },
      { path: planPath, text: hardenEscapeRuns(JSON.stringify(plan, null, 2)) },
    ],
  };
}

// returnChannelPersist(inp, paths, outputDir, sha) -> { ok: true, result } | { ok:false, reason }
//
// The persist path that dispatches NOTHING. It hands the three primaries — findings.json,
// report.md, the persist plan — back to the caller inside the workflow's own return value,
// and Phase 8 (which has Bash) materializes them with scripts/materialize_artifacts.py.
//
// WHY. Every other path puts the bytes on disk through an artifact-writer agent: a
// language model asked to reproduce ~50 KB of escape-dense JSON verbatim. Measured across
// every recorded run (38 writer journals / 84 artifacts): 26 of 73 attempted writes — 36% —
// failed their own content proof and 12 artifacts were never written at all. Nothing about
// a document predicts it (a 47 KB findings.json with 104 backslashes came back
// byte-perfect; a 6.4 KB zero-backslash .md was truncated), and the worst losses are
// SUMMARIZATION, which no encoding prevents: one checkpoint lost 29,132 chars because the
// writer dropped 11 fields from every finding, another lost 13,008 with its schema intact
// and its prose simply rewritten shorter. Both parse cleanly. Re-encoding (hardenEscapeRuns)
// and re-dispatching were both measured and both failed — the retry corrupted the same
// sites and died at the identical byte offset, twice.
//
// A workflow's return value is serialized by the HARNESS. Measured 2026-07-30 with a
// zero-subagent probe: byte-exact on disk at 200,000 / 500,000 / 4,000,000 chars, in
// 18-122 ms, with no ceiling found (see RETURN_CHAR_BUDGET). The largest run ever recorded
// carries ~66 KB of unique content — 1.6% of the proven-safe size. This already happened by
// accident once: a run whose writer failed and persisted nothing was found with all 58,949
// chars of its pipeline output sitting in that file, recoverable the whole time, because
// the design discarded it on the success path.
//
// THE PROOF IS UNCHANGED AND UNDUPLICATED. The plan's `expect[]` proves the two primaries,
// its `planChecksum` proves itself, and its `derive[]` proves the two projections — the
// same three gradings assemble_artifacts.py already performs, now applied to a
// harness-written copy rather than a model-written one. The materializer reuses that script
// instead of growing a second grader; nothing here recomputes a checksum.
//
// The primaries are the SAME strings the writer path would have been handed, hardening
// included — not by agreement but because persistEntries is the only place either channel
// serializes them.
//
// artifactPaths and `partial: false` are exactly as on the writer path: what changed is who
// writes the bytes, not which four paths the run produces. Nothing is on disk until Phase 8
// materializes — and that is a LOUD absence (the files are simply not there) where the
// writer's failure mode is a silent paraphrase.
function returnChannelPersist(inp, paths, outputDir, sha) {
  const { planPath, entries } = persistEntries(inp, paths, outputDir, sha);
  const chars = JSON.stringify(entries).length;
  if (chars > RETURN_CHAR_BUDGET) {
    return {
      ok: false,
      reason: `the persisted primaries serialize to ${chars} chars, over the ${RETURN_CHAR_BUDGET}-char return budget`,
    };
  }
  return {
    ok: true,
    result: {
      artifactPaths: paths,
      gaps: [],
      partial: false,
      // `nonce` is the run's own id from the args waist. It is what lets the materializer
      // find THIS run's output file by content when no task id is in hand — the return
      // arrives inline on a fast run, and the file exists either way.
      persistReturn: { channel: 'return', nonce: inp.nonce || null, planPath, entries },
    },
  };
}

// The derived persist (issue #38, D3.2): write the three primaries, then derive the two
// projections on disk. Failure at ANY step takes the same partial-artifacts degradation
// as the legacy path — a content-proof MISMATCH is the one exception (see below).
//
// ONE deterministic retry on a STRUCTURAL assemble failure (live smoke
// smoke-20260727-205454-f99d948). On discourse-graphite#6 the writer transcribed
// findings.json with `\"` over-escaped to `\\"`, producing unparseable JSON at line 99;
// assemble_artifacts.py correctly refused to derive anything and the run lost ALL its
// artifacts. The writer is a sampled agent, not a deterministic function — the other two
// runs on the same commit produced parseable JSON — so a second dispatch is a genuinely
// fresh sample rather than a repeat of the same computation. Hence: retry the whole
// derived persist (writer + assembler) exactly once, then degrade.
//
// The boundaries are load-bearing:
//   * ONLY when the assemble script REFUSED (trustAssembleReceipt structural failure:
//     unparseable JSON, missing/duplicate id, bad plan checksum, a derived-document
//     mismatch). A tolerated PRIMARY content-proof mismatch never reaches here — it is a
//     successful persist with a disclosed divergence, and re-rolling it would trade a
//     known-divergent artifact for an unknown one.
//   * A writer throw / null / failed write-proof degrades immediately, as before: the
//     dispatch itself did not complete, so there is nothing the assembler could refuse.
//   * EXACTLY once. `attemptDerivedPersist` is called at most twice from here and calls
//     nothing recursively — there is no loop to unbound.
//   * NEVER fall back to the legacy by-value writer on this path. This was considered and
//     REJECTED: the legacy writer carries NO content proof, so falling back to it converts
//     a visible failure into a silent one. The same smoke run measured the by-value writer
//     diverging from its payload on 3 of 3 runs (16 chars, 8 chars, and the invalid JSON
//     above) — silent corruption is the normal case there, not the exception. Do not
//     "helpfully" add the fallback.
//   * BOTH attempts are disclosed, whichever way the retry lands, so a degraded (or
//     narrowly-rescued) run stays honest about what happened.
async function writeArtifactsDerived(c, inp, paths, outputDir, sha, policy, partial, assembleScriptPath) {
  const { plan, planPath, entries } = persistEntries(inp, paths, outputDir, sha);
  const attempt = () => attemptDerivedPersist(c, entries, planPath, plan, paths, outputDir, policy, assembleScriptPath);

  // The primaries a refused receipt still proved, keyed by artifactPaths name. Only the
  // LAST attempt's proof counts: a retry re-dispatches the writer, which overwrites the
  // files, so the earlier attempt's grading describes bytes that no longer exist.
  const salvage = (att) => {
    const proven = new Set(att.proven || []);
    return {
      findings: proven.has(paths.findings) ? paths.findings : null,
      report: proven.has(paths.report) ? paths.report : null,
    };
  };

  const first = await attempt();
  if (first.ok) return { artifactPaths: paths, gaps: first.gaps, partial: false };
  if (!first.retryable) return partial(first.reason, [], salvage(first));

  const second = await attempt();
  if (second.ok) {
    return {
      artifactPaths: paths,
      gaps: [`artifact-persist-retry: the first derived persist attempt failed (${first.reason}); a second artifact-writer dispatch succeeded and the artifacts below are from that attempt`]
        .concat(second.gaps),
      partial: false,
    };
  }
  return partial(`${second.reason} — retried once after the first attempt failed (${first.reason})`, [], salvage(second));
}

// One derived-persist attempt: dispatch the writer for the three primaries, prove they
// landed, run the assembler, grade the receipt. Returns
//   { ok: true, gaps }                       — persisted (gaps may disclose a tolerated mismatch)
//   { ok: false, retryable, reason }         — failed; `retryable` iff the assemble script
//                                              structurally refused (see the caller).
// Never throws: every dispatch keeps its own try/catch, exactly as before.
async function attemptDerivedPersist(c, entries, planPath, plan, paths, outputDir, policy, assembleScriptPath) {
  const fail = (reason, retryable) => ({ ok: false, retryable: !!retryable, reason });

  let writerOut;
  try {
    writerOut = await c.agent(finalArtifactsWriterPrompt(entries), {
      label: 'artifact-writer',
      agentType: 'code-gauntlet:artifact-writer',
      model: modelFor('code-gauntlet:artifact-writer', policy),
      schema: WRITTEN_SCHEMA,
    });
  } catch (e) {
    return fail(`writer agent threw (${(e && e.message) || 'unknown'})`);
  }
  if (!writerOut) return fail('writer returned null');
  // Write-proof, same threat model as materializeVerifySlices: WRITTEN_SCHEMA declares
  // no `required`, so an empty { written: [] } is schema-valid and a writer under
  // StructuredOutput retry pressure can return one having written nothing. Without this
  // the assembler would then read primaries that never landed.
  const writtenList = Array.isArray(writerOut.written) ? writerOut.written : [];
  // Issue #148: every writer-reported written[] path; one reason naming each escape.
  const writtenEscape = pathEscapeReason(
    outputDir,
    writtenList.map((p, i) => ({ name: `written[${i}]`, path: p, present: true })),
  );
  if (writtenEscape) return fail(writtenEscape);
  const written = new Set(writtenList);
  if (!entries.every((e) => written.has(e.path))) {
    return fail('writer echo did not cover all three primary artifact paths (no write proof)');
  }

  let receipt;
  try {
    receipt = await c.agent(assemblePrompt(assembleScriptPath, planPath), {
      label: 'assemble-artifacts',
      agentType: 'code-gauntlet:executor',
      model: modelFor('code-gauntlet:executor', policy),
      schema: ASSEMBLE_RECEIPT_SCHEMA,
    });
  } catch (e) {
    return fail(`assemble executor threw (${(e && e.message) || 'unknown'})`);
  }
  // Issue #148: every receipt-reported path field (verified + written).
  if (receipt && typeof receipt === 'object') {
    const receiptFields = [];
    const verified = Array.isArray(receipt.verified) ? receipt.verified : [];
    const receiptWritten = Array.isArray(receipt.written) ? receipt.written : [];
    verified.forEach((e, i) => receiptFields.push({ name: `verified[${i}]`, path: e && e.path, present: true }));
    receiptWritten.forEach((e, i) => receiptFields.push({ name: `receipt.written[${i}]`, path: e && e.path, present: true }));
    const receiptEscape = pathEscapeReason(outputDir, receiptFields);
    if (receiptEscape) return fail(receiptEscape);
  }
  const trust = trustAssembleReceipt(receipt, paths, plan);
  // The one retryable class: the primaries reached disk (write-proof passed) and the
  // pinned script graded them and refused. A fresh writer sample can fix exactly this.
  // `proven` rides along so a final refusal keeps the primaries the receipt DID prove
  // rather than discarding a byte-perfect report with the corrupt findings — see
  // provenPrimaryPaths.
  if (!trust.ok) return { ...fail(trust.reason, true), proven: provenPrimaryPaths(receipt, paths, plan) };
  return { ok: true, gaps: trust.gaps };
}

// The assemble receipt gate. A STRUCTURAL failure (no receipt, ok:false, a path the
// script never verified/wrote) is untrustworthy persistence -> degrade. A content-proof
// MISMATCH is deliberately NOT a failure: the script derived from what is actually on
// disk and the artifacts are self-consistent with it, so the findings are still
// delivered and the divergence is raised as a LOUD gap instead of costing the run its
// artifacts (never-fabricate cuts both ways — inventing a new way to lose a run is
// exactly as wrong as inventing a success).
//
// A receipt must NEVER be allowed to grade itself (issue #38 L1-2). The receipt is a
// self-report relayed by an executor agent, so every claim it makes about what it was
// CHECKING AGAINST is compared here to the value the pipeline computed independently:
//
//   * receipt.planChecksum must equal the plan's own planChecksum. The script recomputes
//     it from the plan it actually read and refuses to run on a mismatch, so a receipt
//     echoing a different value did not execute THIS plan.
//   * each verified entry's expected_chars/expected_checksum must equal the plan's
//     expect[] entry for that path. Otherwise a wholly self-consistent fabricated
//     receipt ("expected 10, got 10, match") passes.
//   * content_proof must agree with the numbers the receipt itself reports, since the
//     script derives it as exactly `chars === expected_chars && checksum ===
//     expected_checksum`. An incoherent receipt is a broken relay, not a proof.
//   * each DERIVED document's reported chars/checksum must equal the plan's `derive[]` entry
//     for that path — the pipeline's own serialization of the document it holds. Path
//     presence proved only that something was written there.
function trustAssembleReceipt(receipt, paths, plan) {
  if (!receipt || typeof receipt !== 'object') return { ok: false, reason: 'assemble executor returned no receipt' };
  if (receipt.ok !== true) {
    const errors = Array.isArray(receipt.errors) ? receipt.errors.join('; ') : '';
    return { ok: false, reason: `assemble script reported failure (${errors || 'no reason given'})` };
  }
  if (receipt.planChecksum !== plan.planChecksum) {
    return {
      ok: false,
      reason: `assemble receipt echoed plan checksum ${receipt.planChecksum === undefined ? 'none' : receipt.planChecksum} but the pipeline computed ${plan.planChecksum} — the executor did not run this persist plan`,
    };
  }
  const verified = Array.isArray(receipt.verified) ? receipt.verified : [];
  const written = Array.isArray(receipt.written) ? receipt.written : [];
  const verifiedByPath = new Map(verified.map((e) => [(e && e.path), e]));
  const expectByPath = new Map((plan.expect || []).map((e) => [e.path, e]));
  const writtenPaths = new Set(written.map((e) => (e && e.path)));
  for (const p of [paths.findings, paths.report]) {
    const got = verifiedByPath.get(p);
    if (!got) return { ok: false, reason: `assemble receipt did not verify ${p} (no content proof)` };
    const want = expectByPath.get(p);
    if (!want || got.expected_chars !== want.chars || got.expected_checksum !== want.checksum) {
      return {
        ok: false,
        reason: `assemble receipt checked ${p} against a foreign expectation (receipt says ${got.expected_chars} chars/${got.expected_checksum}, the pipeline handed the writer ${want ? want.chars : 'none'}/${want ? want.checksum : 'none'})`,
      };
    }
    const same = got.chars === want.chars && got.checksum === want.checksum;
    if ((got.content_proof === 'match') !== same) {
      return {
        ok: false,
        reason: `assemble receipt is incoherent for ${p}: content_proof:"${got.content_proof}" contradicts its own chars/checksum (${got.chars}/${got.checksum} vs expected ${want.chars}/${want.checksum})`,
      };
    }
  }
  // The DERIVED documents (the delivered payload). Path presence alone proved nothing about
  // their content, so each is checked against the plan's own `derive` expectation — the
  // chars/checksum the pipeline computed for the document it holds in memory, compared to
  // what the script reports for the bytes it actually wrote.
  //
  // Threat model, stated plainly for whoever reads this next: the plan is on disk, so a
  // BYZANTINE executor can read these numbers and echo them back. This is NOT authentication.
  // It catches a stale/confused/hallucinating executor and a real Python-vs-JS serializer
  // divergence — the same bound trustSlice documents for the verify receipt.
  //
  // Unlike a primary mismatch, this is STRUCTURAL: a primary can still be derived from
  // on-disk truth, but a derived document that disagrees with the pipeline has no other
  // copy to fall back to — the derivation itself is what went wrong.
  //
  // ONE EXCEPTION, and it is not a loophole. Both derived documents are projections of
  // findings.json ALONE, so when findings.json's OWN content proof came back `mismatch` the
  // derived documents are EXPECTED to differ: the script faithfully projected the divergent
  // bytes that are actually on disk. Failing there would convert the deliberately non-fatal
  // primary mismatch into a lost run — inventing a new way to lose a run, which the
  // never-fabricate contract rules out in the same breath as inventing a success. The
  // difference is still reported, as a gap, right beside the primary mismatch that caused it.
  const writtenByPath = new Map(written.map((e) => [(e && e.path), e]));
  const deriveByPath = new Map((plan.derive || []).map((e) => [e.path, e]));
  const findingsProof = verifiedByPath.get(paths.findings);
  const sourceDiverged = !!(findingsProof && findingsProof.content_proof === 'mismatch');
  const derivedGaps = [];
  for (const p of [paths.postReview, paths.checkpoints]) {
    if (!writtenPaths.has(p)) return { ok: false, reason: `assemble receipt did not write ${p} (no write proof)` };
    const want = deriveByPath.get(p);
    if (!want) return { ok: false, reason: `persist plan carries no derived-content expectation for ${p} (no content proof)` };
    const got = writtenByPath.get(p);
    if (got.chars === want.chars && got.checksum === want.checksum) continue;
    const detail = `derived document ${p} does not match the pipeline's own derivation (receipt reports ${got.chars == null ? 'no' : got.chars} chars/${got.checksum == null ? 'no checksum' : got.checksum}, the pipeline derived ${want.chars}/${want.checksum})`;
    if (sourceDiverged) {
      derivedGaps.push(`artifact-content-proof: ${detail} — expected, since ${paths.findings} it was derived from also diverged`);
      continue;
    }
    return { ok: false, reason: `${detail} — the delivered payload is not what this run produced` };
  }
  // Primary mismatches first, then any derived difference they explain — the primary gap
  // ordering is unchanged for every run that has no derived difference.
  const gaps = [];
  for (const e of verified) {
    if (e && e.content_proof === 'mismatch') {
      gaps.push(`artifact-content-proof: ${e.path} bytes on disk differ from the payload handed to the writer (expected ${e.expected_chars} chars/checksum ${e.expected_checksum}, got ${e.chars}/${e.checksum})`);
    }
  }
  gaps.push(...derivedGaps);
  return { ok: true, gaps };
}

// provenPrimaryPaths(receipt, paths, plan) -> the primary paths a REFUSED receipt still
// proves are on disk byte-identical to what the writer was handed.
//
// WHY THIS EXISTS. A structural refusal used to cost the run all four artifactPaths, even
// when most of the persist demonstrably worked. On the 2026-07-30 run that motivated
// hardenEscapeRuns, findings.json was corrupt but report.md was transcribed byte-perfect
// and its content proof MATCHED — and the pipeline threw the path away anyway, so Phase 8
// had nothing to deliver and a completed 11-finding review reached the user as nothing at
// all. SKILL.md's degradation rule already says "deliver whatever artifactPaths.report
// exists"; that branch was simply unreachable, because the paths were unconditionally
// nulled. This makes the documented recovery real.
//
// The grading is EXACTLY trustAssembleReceipt's success-path grading, not a relaxation:
// the receipt must have run this plan (planChecksum), must have checked the path against
// the pipeline's OWN expectation (not a foreign or fabricated one), must report numbers
// equal to it, and must say `match`. A receipt cannot promote a path it did not prove.
//
// It does NOT resurrect the run: `partial` stays true, the failure gap stays, and the
// DERIVED documents are never salvaged — nothing derived them, so there is nothing to
// prove. This is strictly "stop discarding what was proven", not a new success path.
function provenPrimaryPaths(receipt, paths, plan) {
  if (!receipt || typeof receipt !== 'object') return [];
  if (!plan || receipt.planChecksum !== plan.planChecksum) return [];
  const byPath = new Map((Array.isArray(receipt.verified) ? receipt.verified : []).map((e) => [(e && e.path), e]));
  const expectByPath = new Map((plan.expect || []).map((e) => [e.path, e]));
  const proven = [];
  for (const p of [paths.findings, paths.report]) {
    const got = byPath.get(p);
    const want = expectByPath.get(p);
    if (!got || !want) continue;
    if (got.expected_chars !== want.chars || got.expected_checksum !== want.checksum) continue;
    if (got.chars !== want.chars || got.checksum !== want.checksum) continue;
    if (got.content_proof !== 'match') continue;
    proven.push(p);
  }
  return proven;
}

// The persisted findings must satisfy BOTH downstream boundaries: verify_findings.py
// reads canonical names (file/line_start/line_end/description...) and the retained
// post_review.py INDEXES the v2 names f["file"]/f["line"] and reads body/end_line.
// So at the persist boundary each finding carries the v2 aliases ALONGSIDE the
// canonical fields (a union schema): line<-line_start, end_line<-line_end,
// body<-description. Existing v2 keys are never overwritten.
function toV2Aliased(f) {
  const out = { ...f };
  if (out.line === undefined && out.line_start !== undefined) out.line = out.line_start;
  if (out.end_line === undefined && out.line_end !== undefined) out.end_line = out.line_end;
  if (out.body === undefined && out.description !== undefined) out.body = out.description;
  return out;
}

// The by-value payload the writer agent persists. findings/postReview are aliased to the
// union schema so the persisted JSON is consumable by BOTH boundary scripts unchanged.
// `postReview` is the deterministic delivery set (selectDelivery output): every
// challenge-survivor, ranked and capped, each carrying its report_tag — persisted so Phase 8
// posts it verbatim without re-selecting. The pipeline-degraded `unverified` bucket is NOT
// carried here: it is persisted to no file (findings.json is the high-confidence set only),
// the report already renders it, and the slimmed checkpoint's challenge entry carries it for
// resume — so re-sending it in the writer prompt was dead by-value weight (each finding-scale
// piece now crosses the writer prompt exactly once). Pure + exported so tests (and the node
// recorder) can assert the persist output is REAL pipeline output, not a hand-authored fixture.
function writerPayload(inp) {
  const postReviewSet = (inp.postReview || []).map(toV2Aliased);
  const id = inp.prIdentity;
  return {
    findings: (inp.findings || []).map(toV2Aliased),
    // With a PR identity (delivery.prIdentity, live-run L3) the persisted post-review
    // artifact IS the post_review.py input wrapper — Phase 8 posts it without hand-
    // assembling { owner, repo, pr_number, ... } around a bare array (the wrap was
    // documented but got reverse-engineered anyway, ~8 turns in the PR-310 run).
    // review_body is intentionally '' — Phase 8 composes the summary narrative and may
    // fill it before posting; post_review.py treats '' as a valid empty summary. sha is
    // provenance (post_review.py resolves its own HEAD); platform stays absent so
    // post_review.py auto-detects. The findings SET is byte-identical either way —
    // the wrapper only changes the envelope, never the scored content (D16).
    postReview: id
      ? { owner: id.owner, repo: id.repo, pr_number: id.pr_number, sha: id.sha_full, review_body: '', findings: postReviewSet }
      : postReviewSet,
    report: inp.report || '',
    checkpoints: inp.checkpoints || {},
  };
}

// Wire format for the writer's by-value payload: the payload is a single JSON line
// at the END of the prompt, prefixed by this marker. The artifact-writer agent (and
// parseWriterPayload) split on the marker to recover the exact object to persist.
const WRITER_PAYLOAD_MARKER = 'PAYLOAD_JSON:';

// parseWriterPayload(prompt) -> the payload object the writer was asked to persist.
// Documents/round-trips the WRITER_PAYLOAD_MARKER wire format (JSON.stringify emits a
// single physical line, so everything after the last marker is the JSON object).
function parseWriterPayload(prompt) {
  const idx = (prompt || '').lastIndexOf(WRITER_PAYLOAD_MARKER);
  if (idx === -1) return null;
  return JSON.parse(prompt.slice(idx + WRITER_PAYLOAD_MARKER.length));
}

function writeArtifactsPrompt(inp, paths) {
  const payload = JSON.stringify(writerPayload(inp));
  return `Persist these code-gauntlet artifacts to disk exactly as given (the workflow has no disk access). Write the payload's findings (as pretty JSON) to ${paths.findings}, the payload's report (verbatim markdown) to ${paths.report}, the payload's postReview (the pre-selected delivery set, as pretty JSON) to ${paths.postReview}, and the payload's checkpoints (as JSON) to ${paths.checkpoints}. Return { artifactPaths } echoing the paths you wrote. The payload is the single JSON line after the marker below.\n${WRITER_PAYLOAD_MARKER}${payload}`;
}

// --- Derived persistence (issue #38, D3) -------------------------------------

// The v2 aliases toV2Aliased ADDS at the persist boundary. The checkpoint's
// challenge findings are the alias-stripped twin of findings.json, so removing
// exactly these keys restores the canonical shape (and, because the aliases are
// appended LAST, the key order too).
const PERSIST_ALIAS_FIELDS = ['line', 'end_line', 'body'];

function stripPersistAliases(f) {
  const out = {};
  for (const [k, v] of Object.entries(f)) {
    if (!PERSIST_ALIAS_FIELDS.includes(k)) out[k] = v;
  }
  return out;
}

// fnv1a32(s) -> "fnv1a32:0x........" — the content-proof checksum.
//
// It must be computable IDENTICALLY here and in Python. The workflow sandbox has no
// TextEncoder and no Buffer, so the only byte source available is String#charCodeAt —
// i.e. UTF-16 code units. scripts/assemble_artifacts.py reproduces this exactly by
// unpacking the string's utf-16-le encoding, including surrogate pairs (an emoji
// contributes TWO units on both sides). Math.imul is a language builtin, NOT a host
// global, so it is available in the sandbox.
function fnv1a32(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return `fnv1a32:0x${h.toString(16).padStart(8, '0')}`;
}

// Strip a UTF-8 BOM and AT MOST ONE trailing newline before checksumming. The Write
// tool may normalise a trailing newline or prepend a BOM, and a false content-proof
// degrade must not cost a run its artifacts. Applied on BOTH sides (here and in
// assemble_artifacts.py) so the tolerance is symmetric; two trailing newlines is a
// REAL difference and still reports as a mismatch.
function normalizeForChecksum(s) {
  let out = typeof s === 'string' ? s : '';
  if (out.charCodeAt(0) === 0xfeff) out = out.slice(1);
  if (out.endsWith('\r\n')) return out.slice(0, -2);
  if (out.endsWith('\n')) return out.slice(0, -1);
  return out;
}

// The persist plan's own path. Deliberately matches the Phase 2 stale-file truncation
// glob `code-gauntlet-*-<sha>.*`, so no skill change is needed to clean it up. It is
// NOT an artifactPaths key — the public contract stays at exactly four.
function persistPlanPath(outputDir, sha) {
  const root = requireAbsoluteOutputDir(outputDir);
  const path = `${root}/code-gauntlet-persist-plan-${sha}.json`;
  assertPlannedPathUnderOutputDir(root, path);
  return path;
}

// hardenEscapeRuns(json) -> the same JSON document with every escaped backslash (`\\`)
// respelled as `\u005c`, so the text carries NO run of two or more consecutive
// backslashes — whatever the data says.
//
// WHY (measured, run wf_adc1a803-912, 2026-07-30 — the run that lost every artifact).
// The artifact-writer is a model, and models do not transcribe backslash runs. A
// challenger's prose contained ONE literal backslash (it wrote `\"the executor's
// receipt…\"`); that backslash is escaped TWICE on the way to the writer — once by
// findings.json's own serialization, once by the PAYLOAD_JSON wire line — so one
// backslash arrives as a run of SEVEN. Counting runs in that run's payload against the
// bytes the writer actually wrote:
//
//     run length in findings.json               count   transcribed correctly
//     1  (\n, \")                                  53    53
//     2                                             2     2
//     3  (\\\" — a literal \ ahead of a quote)     18     0   <- every one collapsed
//
// The first collapse produced `\\"` = escaped-backslash + an UNTERMINATED string, so
// assemble_artifacts.py refused the document (correctly — unparseable JSON is
// structural) and the run degraded with all four artifactPaths null. This is NOT
// sampling drift: the retry, a fresh sample, corrupted the same 18 sites and the parse
// failed at the identical byte offset. A second dispatch cannot fix a deterministic
// failure, so the WIRE has to stop producing the input that triggers it.
//
// `\u005c` is one backslash followed by the letters u005c, so afterwards the longest run in
// the document is 1, and in the writer's PAYLOAD_JSON line 3 — the everyday spelling of
// an escaped quote, which the same run transcribed 45 times without an error. The bound
// is DATA-INDEPENDENT: k literal backslashes become k separate `\u005c` escapes rather
// than one run of 2k. That is the durable property; the run-length table above is only
// how it was found.
//
// Transparent to both consumers, which is why no Python change pairs with this:
//   * `\u005c` is a standard JSON escape, so json.loads yields the identical value and
//     the documents assemble_artifacts.py derives out of findings.json are unchanged.
//   * the primaries are proven on RAW BYTES and persistPrimaries returns the hardened
//     string, so the checksum both runtimes compare is over the same text.
//   * the plan's proof is VALUE-level (parse, drop planChecksum, re-serialize), so
//     hardening the plan's emitted bytes cannot move its checksum.
//
// Correctness of the scan: in JSON.stringify output a backslash only ever BEGINS an
// escape, and `\\` is the only escape whose payload is itself a backslash. A
// left-to-right non-overlapping replace therefore consumes whole escapes and can never
// split one — `\\\"` becomes `\u005c\"`, never `\u005c` plus a stray quote. Do not
// "simplify" this to a per-character scan of the parsed values; the transform is defined
// over serializer OUTPUT, which is what the writer has to reproduce.
function hardenEscapeRuns(json) {
  return typeof json === 'string' ? json.replace(/\\\\/g, '\\u005c') : json;
}

// The two PRIMARY strings — the only genuinely unique content the writer persists.
// Pure and exported so a test can assert the writer prompt carries them verbatim.
// findingsJson is escape-hardened (see hardenEscapeRuns) BEFORE it is returned, so the
// string the writer is handed, the string persistPlan checksums, and the bytes
// assemble_artifacts.py reads back are all one and the same. reportMd is markdown, not
// JSON — a mangled backslash there is a tolerated content-proof mismatch, not a parse
// failure, so it is deliberately left alone rather than given a format it does not have.
function persistPrimaries(inp) {
  return {
    findingsJson: hardenEscapeRuns(JSON.stringify(((inp || {}).findings || []).map(toV2Aliased), null, 2)),
    reportMd: (inp || {}).report || '',
  };
}

// persistPlan(inp, paths) -> the plan scripts/assemble_artifacts.py consumes.
// PURE (deep-clones the checkpoint before emptying the challenge findings), and
// exported so the projection rules are directly unit-testable — the in-run
// byte-identity test applies them to the primaries and asserts the result equals
// writerPayload(inp).postReview / .checkpoints.
//
// The skeleton is derived FROM slimPersistedCheckpoints' output by EMPTYING (not
// deleting) phases.challenge.findings, so there is exactly one source of truth for the
// checkpoint shape and the key keeps its position — the derived document is
// key-order-identical to the one the pipeline holds in memory.
//
// THE PLAN'S SELF-PROOF (`planChecksum`, issue #38 L1-2). The plan is transcribed to
// disk by the artifact-writer agent exactly like findings.json and report.md — but
// unlike them it is not data to be checked, it is the INSTRUCTION SET. `postReview.ids`
// is the sole authority for which finding ids reach the delivered post-review artifact,
// so a writer that elides two entries from that list produces a silently smaller
// delivered set with a self-consistent ok:true receipt and no gap. The two primaries had
// expect[].chars/checksum to prove them; the plan had nothing. So it now carries a
// checksum of itself, computed over the plan MINUS that field:
//
//   planChecksum = fnv1a32(JSON.stringify(planWithoutPlanChecksum, null, 2))
//
// Unambiguous in both runtimes because (a) the field is appended LAST, so deleting it
// on the Python side restores this exact object (both runtimes preserve insertion order
// and neither reorders on re-serialization), and (b) the serializer is the same pretty
// printer that produces the derived artifacts — which makes the plan checksum a canary
// for serializer divergence too: a Python/JS spelling difference over the plan's content
// fails the proof before a divergent artifact is written.
//
// THE DERIVED DOCUMENTS' CONTENT PROOF (`derive`, issue #38 F1-persist-1/F4-4). The two
// primaries are proven by `expect[].chars/checksum`; the two DERIVED documents —
// post-review.json and checkpoint-all.json, i.e. the payload that actually reaches the user
// — were gated on PATH PRESENCE only ("the script says it wrote something there"). So the
// plan also carries a { path, chars, checksum } expectation for each derived document,
// computed here from writerPayload(inp).postReview / .checkpoints through the SAME
// normalizeForChecksum + fnv1a32 the primaries use. It costs nothing at dispatch (~40 bytes
// each; the documents themselves are still never sent) and it makes the byte-identity claim
// PROVABLE for the delivered payload rather than merely argued.
//
// WHAT THIS IS NOT: authentication. The plan is on disk and the executor can read it, so a
// BYZANTINE executor could echo back any value the plan names — exactly the threat model
// trustSlice already documents for the verify receipt. This is a consistency/liveness check
// against a STALE, CONFUSED or HALLUCINATING executor (a receipt from another run, a
// half-finished derivation, an invented success), and against a real serializer divergence
// between the two runtimes. Do not build a security argument on top of it.
//
// WHY A DERIVED MISMATCH IS FATAL WHERE A PRIMARY MISMATCH IS NOT: a primary mismatch still
// leaves on-disk truth to derive from, so the run keeps its artifacts and raises a loud gap.
// A derived mismatch means the DERIVATION disagreed with the pipeline — there is no other
// copy of that document to fall back to — so trustAssembleReceipt treats it as structural.
//
// WHY THE ID LISTS STAY (the weak point is transcription, not encoding). No wire format
// removes the failure mode: the plan must cross an LLM agent's transcription to reach
// disk (the sandbox has no disk access at all), and no encoding stops an agent from
// writing fewer bytes than it was handed. The alternatives are strictly worse — deriving
// the delivery set on the Python side means reimplementing selectDelivery's ranking and
// cap in a second language, i.e. an order-sensitive stage whose divergence would silently
// change the delivered findings; and "all of findings.json, in order" is simply false,
// delivery is a ranked capped subset. So the list stays explicit and gains a proof.
function persistPlan(inp, paths) {
  const { findingsJson, reportMd } = persistPrimaries(inp);
  const id = inp.prIdentity;
  const skeleton = deepClone(inp.checkpoints || {});
  const challenge = (skeleton.phases || {}).challenge;
  const challengeFindingIds = challenge && Array.isArray(challenge.findings)
    ? challenge.findings.map((f) => f && f.id)
    : [];
  if (challenge && Array.isArray(challenge.findings)) challenge.findings = [];
  const expectOf = (path, text) => {
    const normalized = normalizeForChecksum(text);
    return { path, chars: normalized.length, checksum: fnv1a32(normalized) };
  };
  // The derived documents, as the pipeline itself would serialize them — the same pretty
  // printer assemble_artifacts.py reproduces (js_stringify_pretty) and the same source
  // (writerPayload) the legacy by-value path persists. Only their chars/checksum travel.
  const held = writerPayload(inp || {});
  const plan = {
    planVersion: 2,
    expect: [expectOf(paths.findings, findingsJson), expectOf(paths.report, reportMd)],
    derive: [
      expectOf(paths.postReview, JSON.stringify(held.postReview, null, 2)),
      expectOf(paths.checkpoints, JSON.stringify(held.checkpoints, null, 2)),
    ],
    postReview: {
      path: paths.postReview,
      source: paths.findings,
      ids: (inp.postReview || []).map((f) => f && f.id),
      // Same envelope decision writerPayload makes (live-run L3, D16): with a PR
      // identity the artifact IS the post_review.py input wrapper; without one it is a
      // bare array. Key order is the wire contract — findings are appended last.
      wrapper: id
        ? { owner: id.owner, repo: id.repo, pr_number: id.pr_number, sha: id.sha_full, review_body: '' }
        : null,
    },
    checkpoint: {
      path: paths.checkpoints,
      source: paths.findings,
      challengeFindingIds,
      stripAliasFields: PERSIST_ALIAS_FIELDS,
      skeleton,
    },
  };
  // Appended LAST and computed over the object WITHOUT it — see the construction note
  // above. assemble_artifacts.py deletes exactly this key and recomputes.
  plan.planChecksum = fnv1a32(JSON.stringify(plan, null, 2));
  return plan;
}

// firstUnsafeNumber(root, rootPath) -> the path of the first number the Python twin
// could not spell identically, or null.
//
// JS numbers are doubles and Number#toString has its own spelling rules; Python's
// repr(float) does not share them (1e-7 vs 1e-07, 0.000001 vs 1e-06, 90 vs 90.0, 0 vs
// -0.0, null vs NaN). scripts/assemble_artifacts.py deliberately does NOT reimplement
// Number#toString — a port whose own bugs would be invisible is worse than a
// precondition — so it refuses any number it cannot round-trip and this guard applies
// the SAME rule one step earlier, where refusing is free: the run falls back to the
// legacy by-value writer instead of writing a divergent artifact or losing artifacts.
// Every number the pipeline actually produces is a count, a line number, or a
// confidence, so the precondition never binds in practice. Integers outside JS's safe
// range are rejected too: JS would already have parsed them lossily.
const JS_MAX_SAFE_INTEGER = 9007199254740991;

function firstUnsafeNumber(root, rootPath) {
  const stack = [[root, rootPath]];
  while (stack.length > 0) {
    const [node, where] = stack.pop();
    if (typeof node === 'number') {
      if (!Number.isInteger(node) || node > JS_MAX_SAFE_INTEGER || node < -JS_MAX_SAFE_INTEGER) return where;
      continue;
    }
    if (Array.isArray(node)) {
      for (let i = node.length - 1; i >= 0; i -= 1) stack.push([node[i], `${where}[${i}]`]);
      continue;
    }
    if (node && typeof node === 'object') {
      const entries = Object.entries(node);
      for (let i = entries.length - 1; i >= 0; i -= 1) {
        const [k, v] = entries[i];
        stack.push([v, `${where}.${k}`]);
      }
    }
  }
  return null;
}

// persistDerivable(inp) -> { ok } | { ok:false, reason }
// The guard on the derived path. Every projection is BY FINDING ID out of
// findings.json, so the derivation is only faithful when:
//   0. every number in the persisted content is a JS-safe integer (see
//      firstUnsafeNumber — otherwise the Python serializer spells it differently);
//   1. every finding carries a unique, non-empty string id;
//   2. every postReview / challenge entry has a twin in the findings set; and
//   3. that twin is byte-identical to it under the projection rules — including the
//      alias round trip, because toV2Aliased only ADDS an alias when absent, so a
//      finding that ALREADY carries `line`/`end_line`/`body` would silently lose it to
//      the checkpoint's alias strip.
// A refusal is NOT a degradation: writeArtifacts falls back to the legacy full
// by-value writer and records the reason as a gap. Pure and exported for direct tests.
function persistDerivable(inp) {
  // Everything the derived documents are built from: findings.json's content, the
  // checkpoint skeleton, and the post-review envelope's pr_number.
  for (const [label, value] of [
    ['findings', (inp || {}).findings],
    ['postReview', (inp || {}).postReview],
    ['checkpoints', (inp || {}).checkpoints],
    ['prIdentity', (inp || {}).prIdentity],
  ]) {
    if (value === undefined || value === null) continue;
    const bad = firstUnsafeNumber(value, label);
    if (bad !== null) {
      return { ok: false, reason: `${bad} is not a JS-safe integer — the Python assembler cannot spell it byte-identically, so the derived artifact would diverge` };
    }
  }
  const findings = (inp || {}).findings || [];
  const byId = new Map();
  for (let i = 0; i < findings.length; i += 1) {
    const f = findings[i];
    const fid = f && f.id;
    if (typeof fid !== 'string' || fid === '') {
      return { ok: false, reason: `finding at index ${i} has no usable string id` };
    }
    if (byId.has(fid)) return { ok: false, reason: `duplicate finding id ${fid}` };
    byId.set(fid, f);
    if (JSON.stringify(stripPersistAliases(toV2Aliased(f))) !== JSON.stringify(f)) {
      return { ok: false, reason: `finding ${fid} already carries a v2 alias field (${PERSIST_ALIAS_FIELDS.join('/')}) — the checkpoint alias strip is not reversible` };
    }
  }
  const twinCheck = (list, label, project) => {
    for (let i = 0; i < list.length; i += 1) {
      const entry = list[i];
      const fid = entry && entry.id;
      if (typeof fid !== 'string' || !byId.has(fid)) {
        return `${label} entry at index ${i} (id ${fid === undefined ? 'missing' : fid}) is not present in the findings set`;
      }
      if (JSON.stringify(project(entry)) !== JSON.stringify(project(byId.get(fid)))) {
        return `${label} entry ${fid} differs from the findings entry with the same id`;
      }
    }
    return null;
  };
  const postReviewBad = twinCheck(inp.postReview || [], 'postReview', toV2Aliased);
  if (postReviewBad) return { ok: false, reason: postReviewBad };
  const challenge = ((inp.checkpoints || {}).phases || {}).challenge;
  const challengeFindings = challenge && Array.isArray(challenge.findings) ? challenge.findings : [];
  const challengeBad = twinCheck(challengeFindings, 'checkpoint challenge', (f) => f);
  if (challengeBad) return { ok: false, reason: challengeBad };
  return { ok: true };
}

// The DERIVED writer payload: `[{ path, text }]` — each `text` is written VERBATIM
// (the verify slice-input shape uses `content` and is written as JSON). Sending the
// exact string removes every reformatting degree of freedom, which is what makes the
// content-proof checksum meaningful.
function finalArtifactsWriterPrompt(entries) {
  const payload = JSON.stringify(entries);
  return `Persist these code-gauntlet artifacts to disk exactly as given (the workflow has no disk access). For every entry in the payload, write its "text" VERBATIM to its "path" — byte for byte, nothing before it and NOTHING AFTER THE FINAL BYTE (no trailing commentary, no tool-call markup). Do not reformat, re-indent, or re-serialize. Return { written } listing the paths you wrote. The payload is the single JSON line after the marker below.\n${WRITER_PAYLOAD_MARKER}${payload}`;
}

// The assemble receipt shape (scripts/assemble_artifacts.py's single stdout line).
const ASSEMBLE_RECEIPT_SCHEMA = {
  type: 'object',
  properties: {
    ok: { type: 'boolean' },
    planVersion: { type: 'number' },
    // The plan checksum the script RECOMPUTED from the plan it read; trustAssembleReceipt
    // compares it against the pipeline's own so the receipt cannot grade itself.
    planChecksum: { type: 'string' },
    verified: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          path: { type: 'string' },
          chars: { type: 'number' },
          expected_chars: { type: 'number' },
          checksum: { type: 'string' },
          expected_checksum: { type: 'string' },
          content_proof: { type: 'string' },
        },
      },
    },
    written: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          path: { type: 'string' },
          chars: { type: 'number' },
          checksum: { type: 'string' },
        },
      },
    },
    errors: { type: 'array', items: { type: 'string' } },
  },
};

// The pinned command: a single `python3 <script> --plan <plan>` invocation whose tokens are
// AST-safe (CLAUDE.md AST-safe emission — no command substitution, heredocs, env prefix, or
// shell operators), each shellWord-quoted so a path bearing a space stays ONE argv word
// (issue #75) — exactly like verifyCommand.
function assemblePrompt(scriptPath, planPath) {
  return `Run exactly this command, then return its single line of stdout JSON verbatim via the schema:\npython3 ${shellWord(scriptPath)} --plan ${shellWord(planPath)}`;
}

// --- Checkpoints ------------------------------------------------------------

// checkpointPath(phase, sha) -> bare filename for a phase's persisted checkpoint.
// The skill layer reads these on a rerun and injects the recovered outputs into
// the args waist (args.checkpoints); the pipeline has no disk access of its own.
function checkpointPath(phase, sha) {
  return `code-gauntlet-checkpoint-${phase}-${sha}.json`;
}

// readCheckpoints(ctx, args) -> phase-keyed resume map ({ phase: priorOutput }).
// Injected through the args waist on a rerun (a phase whose output is present is
// skipped, not re-dispatched). The platform's own resume machinery caches
// agent-level work; this is the coarser phase-level skip. Accepts EITHER a bare
// { phase: output } map OR the persisted checkpoint artifact's { phases, completed,
// phaseReached } wrapper (unwrapping .phases) so the artifact the pipeline itself
// writes can be fed straight back. Falls back to a ctx-borne map (test seam), then {}.
//
// GARBAGE IS UNIFORM (round-2 fix): a non-plain-object top-level value (null, an array,
// a primitive) is garbage, exactly like the already-pinned `checkpoints: 'garbage'`
// case -- and so is a non-plain-object `.phases`. Before this fix `typeof [] === 'object'`
// let `{checkpoints: []}` and `{checkpoints: {phases: []}}` both slip past this unwrap
// as a truthy "resolved map", which the gate then sanitized to `{}` (no violations) --
// but runWith indexes THAT ARRAY by phase name, and `[]['filter'] ===
// Array.prototype.filter`, so runPhase('filter') replayed a FUNCTION as the phase's
// output instead of refusing. Top-level-garbage-is-inert is the established decision
// (falls through to the {} default below) -- the fix is only that arrays now count
// as garbage too, at both unwrap points.
// unwrapCheckpointMap(cp) -> the resolved phase-map for a checkpoints value, or `null` if
// `cp` is not a usable shape (a non-plain-object top level, or a plain top level whose
// `.phases` is present but not itself a plain object). Module-level, NOT named `unwrap`
// (build.js flattens every src file's top-level scope into one bundle and
// detectTopLevelCollisions hard-fails on a duplicate top-level name) so readCheckpoints
// AND the #268 discard-disclosure predicate below share one definition of "usable
// checkpoints shape" instead of readCheckpoints's old function-local copy silently
// drifting from a second one.
function unwrapCheckpointMap(cp) {
  if (!isPlainCheckpointObject(cp)) return null;
  if (cp.phases === undefined) return cp;
  return isPlainCheckpointObject(cp.phases) ? cp.phases : null;
}

function readCheckpoints(ctx, args) {
  const A = args || {};
  return unwrapCheckpointMap(A.checkpoints) || (ctx && unwrapCheckpointMap(ctx.checkpoints)) || {};
}

// checkpointDiscardGap(topLevelCheckpoints) -> a 0-or-1-element `checkpoint-discarded:`
// gaps array (issue #268, extended by #270 below). readCheckpoints's fallback chain
// silently treats an unusable `args.checkpoints` exactly like an absent one -- correct
// behavior (a malformed resume input must not abort a review that never needed to
// resume), but previously undisclosed: an operator who stamped a real (if malformed)
// checkpoints value got a fresh full-pipeline run with no signal that their resume
// attempt was discarded rather than honored.
//
// `checkpoints: undefined` (never stamped, OR a stamped `null` -- normalizeArgsReport
// already dropped that to absent on the NULLABLE_TOP_LEVEL allowlist, upstream of this
// call) is deliberately NOT a discard: nothing was tolerated, nothing was lost, exactly the
// same "previously valid and silent" reasoning F4-3 pins for null_arg gaps
// (pipeline_run.test.js). A non-plain-object top level, or a plain top level with a
// non-plain-object `.phases`, is what `unwrapCheckpointMap` REJECTS outright (`null`) --
// WAS a real value the operator supplied, reduced to a fresh run with no resume, so it
// earns the disclosure below.
//
// Names the failing POSITION (`checkpoints` at the top level, or `checkpoints.phases` for a
// malformed wrapper) and reads describeCheckpointShape AT THAT POSITION: describing the
// wrapper object itself for a `{phases: 'x'}`-class value would print the useless
// "(got object)" instead of naming what is actually wrong (the `.phases` value).
//
// Issue #270: unwrapCheckpointMap REJECTING isn't the only no-resume outcome an operator
// gets zero disclosure for. It can also SUCCEED to something inert:
//   Arm A (zero-recognized non-empty map) -- the classic case is a fed-back return's
//   `checkpoints` field re-supplied as the next run's `checkpoints` argument, which
//   SKILL.md documents as a real return and headless auto-resume reads
//   `return.checkpoints` directly. `{completed, truncated: true}` IS buildResumeCheckpoints'
//   own FAILURE-path return, once the in-memory phase map would exceed the return budget.
//   A bare `{completed}` (no truncated, no phases) is NOT that helper's output at all --
//   buildResumeCheckpoints only ever returns `{phases, completed}` or `{completed,
//   truncated: true}`; bare `{completed}` is the ok:true SUCCESS return's own compact form
//   (built once the writer has persisted -- see the `checkpoints: writeOut.partial ? ... :
//   { completed }` success-path assignment below), naming only the phases that ran. Either
//   way its keys ('completed', 'truncated') are not phase names, so the direct-return
//   unwrap branch hands it straight through as a "resolved map" that recognizes nothing --
//   every phase re-runs, silently. Also catches plain garbage like `{foo: 1}`.
//   Arm B (empty-.phases masking) -- `{phases: {}, challenge: {...}}`: the unwrap reads
//   ONLY `.phases` (empty), so the real `challenge` output sitting right next to it at the
//   wrapper's top level is silently ignored. Deliberately narrow to the wholly-empty
//   `.phases` case -- a NON-empty `.phases` resuming real work (`{phases: {challenge:
//   ...}, summarize: {...}}`) never reaches this arm, even though a sibling key is still
//   being ignored: partial masking is not this arm's problem to catch (see the comment at
//   the arm itself), because a legitimate producer for that shape does not exist and the
//   phase(s) that DO resume are real, not silently dropped.
// Both arms require the resolved/`.phases` map to actually be EMPTY of recognized content
// (checked via CHECKPOINT_PHASE_SHAPE_TABLE's key set -- safe to derive from the table here
// because checkpoint_shape_gate.test.js's ALL_PHASES container-test loop independently pins
// the table's completeness over all eight phases), so `{}` and `{phases: {}}` alone --
// legitimately empty, nothing was ever supplied to lose -- stay silent, and so does any map
// carrying at least one recognized phase key (that key resumes normally; #270 is only about
// a resume attempt that resolves to NOTHING).
//
// All #270 message text below is FIXED pipeline-authored vocabulary: it never interpolates
// a caller-supplied key name or byte. `args.checkpoints` is PR-author-reachable, and a key
// named after a G3 bench sentinel echoed into a gap would flip that gate.
function checkpointDiscardGap(topLevelCheckpoints) {
  if (topLevelCheckpoints === undefined) return [];

  const resolved = unwrapCheckpointMap(topLevelCheckpoints);

  if (resolved === null) {
    const atTopLevel = !isPlainCheckpointObject(topLevelCheckpoints);
    const position = atTopLevel ? 'checkpoints' : 'checkpoints.phases';
    const offending = atTopLevel ? topLevelCheckpoints : topLevelCheckpoints.phases;
    return [`checkpoint-discarded: ${position} must be a plain object, got ${describeCheckpointShape(offending)} -- `
      + 'the supplied checkpoints argument was discarded entirely; nothing was resumed, exactly as '
      + 'if no checkpoints had been supplied.'];
  }

  const recognizedPhaseNames = Object.keys(CHECKPOINT_PHASE_SHAPE_TABLE);
  const resolvedKeys = Object.keys(resolved);
  // Deliberately KEY-PRESENCE (Object.keys + includes), not a truthiness/value check on
  // `resolved[k]` -- a recognized phase key can legitimately carry any JSON-safe value
  // (including one the shape gate below will still refuse), and `undefined` cannot arrive
  // through the JSON waist at all, so there is no "recognized key present but empty" case
  // this would need to distinguish.
  const hasRecognizedKey = resolvedKeys.some((k) => recognizedPhaseNames.includes(k));

  // Arm A: the unwrap succeeded to a NON-EMPTY map recognizing none of it.
  if (resolvedKeys.length > 0 && !hasRecognizedKey) {
    // Truthiness, not `'truncated' in resolved` -- a stamped `truncated: false` sits right
    // next to `completed` in a real buildResumeCheckpoints success-path return and must NOT
    // be misread as the truncated sub-case just because the key exists.
    if (resolved.truncated) {
      return ['checkpoint-discarded: the supplied checkpoints value is a truncated failure-path return '
        + '(phase names only, no phase outputs) -- nothing in it is resumable; re-run without the '
        + 'checkpoints argument to start the review fresh.'];
    }
    if (resolvedKeys.includes('completed')) {
      // Split on whether `completed` is actually non-empty: a real compact-return producer
      // (the ok:true success path's `{ completed }`) always names at least one phase, so a
      // non-empty array is the only shape that could have come from an on-disk-backed run --
      // the on-disk pointer sentence is correct there. An empty (or non-array) `completed`
      // instead matches makeCheckpointShapeRejectEnvelope's OWN refusal envelope
      // (`{ completed: [] }`, `artifactPaths: {}` -- nothing was ever persisted for it to
      // point at), so pointing at artifactPaths.checkpoints there would send the operator to
      // a path that was never written.
      if (Array.isArray(resolved.completed) && resolved.completed.length > 0) {
        return ['checkpoint-discarded: the supplied checkpoints value looks like a compact return rather '
          + 'than a checkpoint artifact -- it carries no phase outputs to resume from; the on-disk resume '
          + 'state from that run lives at artifactPaths.checkpoints.'];
      }
      return ['checkpoint-discarded: the supplied checkpoints value looks like a return envelope rather '
        + 'than a checkpoint artifact -- it carries no phase outputs to resume from; re-run without the '
        + 'checkpoints argument to start the review fresh.'];
    }
    return ['checkpoint-discarded: the supplied checkpoints value contains none of the eight recognized '
      + 'phase names (summarize, discover, merge, verify, validate, filter, challenge, report) -- '
      + 'nothing was resumed, exactly as if no checkpoints had been supplied.'];
  }

  // Arm B: the unwrap took the `.phases` branch to an EMPTY map while the wrapper itself
  // still carries a recognized phase name at its own top level, right next to `.phases`.
  // `resolvedKeys.length === 0` is load-bearing, not redundant with `tookPhasesBranch`: a
  // NON-empty `.phases` resuming real work, sitting next to an ignored top-level sibling
  // (`{phases: {challenge: ...}, summarize: {...}}`), must NOT fire this arm. Partial
  // masking of that shape is a deliberate NON-GOAL -- there is no legitimate producer that
  // emits a real `.phases` resume plus a stray top-level phase key, and the phase(s) inside
  // `.phases` are genuinely being resumed, not silently dropped, so there is nothing to
  // disclose about them.
  const tookPhasesBranch = isPlainCheckpointObject(topLevelCheckpoints)
    && topLevelCheckpoints.phases !== undefined
    && isPlainCheckpointObject(topLevelCheckpoints.phases);
  const wrapperHasRecognizedKey = isPlainCheckpointObject(topLevelCheckpoints)
    && Object.keys(topLevelCheckpoints).some((k) => recognizedPhaseNames.includes(k));
  if (tookPhasesBranch && resolvedKeys.length === 0 && wrapperHasRecognizedKey) {
    return ['checkpoint-discarded: checkpoints.phases is empty and a value under a recognized phase name '
      + "at the wrapper's top level was ignored -- re-supply it as the .phases map, or as a bare phase "
      + 'map, to attempt resuming from it.'];
  }

  return [];
}

// --- Checkpoint shape gate (#248 + #250) -------------------------------------
//
// A REPLAYED checkpoint phase value skips dispatch entirely (runPhase reuses it as-is),
// so an unconditional downstream read against it -- rankKey's `finding.severity` on a
// null element being the named #250 crash -- sees exactly whatever shape a hand-edited
// or version-skewed checkpoint artifact carries. A non-object phase value degrades
// silently instead: `(challengeOut.findings || [])` over a primitive yields an empty,
// ok:true review with no disclosure at all (the named #248 defect), and the belt-free
// phases do the same (measured: `checkpoints: {merge: 'not-an-object'}` returned
// ok:true, merged 0). checkpointShapeErrors is the fix: a pure, exported check run
// on the RESOLVED map readCheckpoints() returns, immediately after that call and before
// any phase is attempted, so a malformed value is refused loud instead of silently
// degrading somewhere downstream.
//
// One row per phase runPhase() names, ALL EIGHT. 'strict' means every array element
// must also be a plain object; 'tolerant' means the array container is checked but its
// elements are not. `gaps` is 'tolerant' on every row: runWith spreads `...(out.gaps ||
// [])` unconditionally (issue #175), so ABSENT passes but a truthy non-array (5, {},
// 'abc') either raw-TypeErrors on the spread or silently iterates per-character garbage --
// container-only is enough to close that. discover also gets `dispatched`/`degraded` as
// 'tolerant': both are unconditionally `.join`-ed or iterated (allActiveDimensionsDegraded,
// the dimensions summary table), so a string there raw-TypeErrors the same way. Element
// tolerance is otherwise reserved for challenge.unverified, whose null-element tolerance is
// a pinned, correct, fully-delivering degradation (stages_delivery.test.js:514-542: the
// belt's `{raw: el}` positions and dimensionsSummaryTable are all null-safe for that one
// field). challenge.eliminated is deliberately ABSENT from
// this table -- it never reaches rankFindings, and the belt owns its own malformed
// shapes with a disclosed drop path (`stats.replay_belt_dropped`, the `replay-filter:`
// gap) -- so it is wholly ungated here, by omission, not by an explicit skip.
const CHECKPOINT_ARRAY_STRICT = 'strict';
const CHECKPOINT_ARRAY_TOLERANT = 'tolerant';
// Exported for checkpoint_shape_gate.test.js, which derives the strict rows from it so a
// row flipped to strict gets an element-level null/primitive test for free, with no second
// edit to keep in sync (the export costs nothing in the bundle -- the table is consumed
// below by checkpointShapeErrors either way).
const CHECKPOINT_PHASE_SHAPE_TABLE = {
  summarize: { gaps: CHECKPOINT_ARRAY_TOLERANT },
  discover: {
    findings: CHECKPOINT_ARRAY_STRICT,
    gaps: CHECKPOINT_ARRAY_TOLERANT,
    dispatched: CHECKPOINT_ARRAY_TOLERANT,
    degraded: CHECKPOINT_ARRAY_TOLERANT,
  },
  merge: { findings: CHECKPOINT_ARRAY_STRICT, gaps: CHECKPOINT_ARRAY_TOLERANT },
  verify: { findings: CHECKPOINT_ARRAY_STRICT, gaps: CHECKPOINT_ARRAY_TOLERANT },
  validate: { findings: CHECKPOINT_ARRAY_STRICT, gaps: CHECKPOINT_ARRAY_TOLERANT },
  filter: { filtered: CHECKPOINT_ARRAY_STRICT, gaps: CHECKPOINT_ARRAY_TOLERANT },
  challenge: {
    findings: CHECKPOINT_ARRAY_STRICT,
    unverified: CHECKPOINT_ARRAY_TOLERANT,
    gaps: CHECKPOINT_ARRAY_TOLERANT,
  },
  report: { gaps: CHECKPOINT_ARRAY_TOLERANT },
};

// CHECKPOINT_REQUIRED_CONTENT_FIELD: phase -> the one field REQUIRED whenever the phase key
// itself is present in a replayed checkpoint (issue #248's silent-empty). No legitimate
// producer ever omits it -- every stage always emits it, and persistPlan empties
// challenge.findings to `[]`, never to absent -- so a MISSING content field only ever means
// a hand-edited or version-skewed checkpoint. Left absent, `challenge: {}` returns ok:true
// with an empty review AND disarms the #178 all-degraded guard, whose third conjunct is
// `checkpoints.challenge !== undefined` (this file, runWith, the all-degraded gap). Content
// phases only: summarize/report have no required field, and challenge.unverified plus every
// phase's gaps/dispatched/degraded stay OPTIONAL through the table above.
const CHECKPOINT_REQUIRED_CONTENT_FIELD = {
  discover: 'findings',
  merge: 'findings',
  verify: 'findings',
  validate: 'findings',
  filter: 'filtered',
  challenge: 'findings',
};

function isPlainCheckpointObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function describeCheckpointShape(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

const CHECKPOINT_FINDING_FIELDS = new Set(['findings', 'filtered', 'unverified']);
const CHECKPOINT_FINDING_STRING_FIELDS = ['severity', 'title', 'file'];
const CHECKPOINT_FINDING_INTEGER_FIELDS = ['line', 'line_start', 'line_end', 'end_line'];

function checkpointFindingShapeErrors(finding, path) {
  const violations = [];
  for (const field of CHECKPOINT_FINDING_STRING_FIELDS) {
    if (typeof finding[field] !== 'string') {
      violations.push(`checkpoint-shape: ${path}.${field} must be a string, got ${describeCheckpointShape(finding[field])}`);
    }
  }

  const hasDescription = finding.description !== undefined;
  const hasBody = finding.body !== undefined;
  if (!hasDescription && !hasBody) {
    violations.push(`checkpoint-shape: ${path} must contain a string description or body`);
  }
  for (const field of ['description', 'body']) {
    if (finding[field] !== undefined && typeof finding[field] !== 'string') {
      violations.push(`checkpoint-shape: ${path}.${field} must be a string, got ${describeCheckpointShape(finding[field])}`);
    }
  }

  for (const field of CHECKPOINT_FINDING_INTEGER_FIELDS) {
    if (finding[field] !== undefined && !Number.isInteger(finding[field])) {
      violations.push(`checkpoint-shape: ${path}.${field} must be an integer, got ${describeCheckpointShape(finding[field])}`);
    }
  }
  if (finding.confidence !== undefined && (typeof finding.confidence !== 'number' || !Number.isFinite(finding.confidence))) {
    violations.push(`checkpoint-shape: ${path}.confidence must be a number, got ${describeCheckpointShape(finding.confidence)}`);
  }

  if (finding.corroborations !== undefined) {
    if (!Array.isArray(finding.corroborations)) {
      violations.push(`checkpoint-shape: ${path}.corroborations must be an array, got ${describeCheckpointShape(finding.corroborations)}`);
    } else {
      finding.corroborations.forEach((corroboration, idx) => {
        if (!isPlainCheckpointObject(corroboration)) {
          violations.push(`checkpoint-shape: ${path}.corroborations[${idx}] must be a plain object, got ${describeCheckpointShape(corroboration)}`);
        }
      });
    }
  }
  return violations;
}

// checkpointShapeErrors(resolvedCheckpoints) -> string[] of `checkpoint-shape:`-prefixed
// violations (registered in docs/machine-parsed-strings.md). Takes the OUTPUT of
// readCheckpoints -- already `.phases`-unwrapped, already defaulted to {} for a
// non-object top-level `checkpoints` (that top-level shape stays inert BY that earlier
// default, never asserted on here). An absent OPTIONAL field always passes, so a
// version-delta replay (an older checkpoint predating a newer field) keeps working -- the
// one exception is CHECKPOINT_REQUIRED_CONTENT_FIELD, whose absence IS itself a violation
// (see that table's own comment). Unknown checkpoint keys (not one of the eight phase
// names) are still unvalidated here -- this function never inspects them -- but they are
// no longer silent when they are the ONLY keys present: checkpointDiscardGap (issue #270,
// computed by runWith from the top-level `args.checkpoints` before this function ever
// runs) discloses that case as a no-op resume. Collects every violation rather than
// stopping at the first, so a caller sees the whole shape of the damage in one refusal
// instead of fixing it one field at a time.
function checkpointShapeErrors(resolvedCheckpoints) {
  const cp = isPlainCheckpointObject(resolvedCheckpoints) ? resolvedCheckpoints : {};
  const violations = [];
  for (const phase of Object.keys(CHECKPOINT_PHASE_SHAPE_TABLE)) {
    const value = cp[phase];
    if (value === undefined) continue;
    if (!isPlainCheckpointObject(value)) {
      violations.push(`checkpoint-shape: phases.${phase} must be a plain object, got ${describeCheckpointShape(value)}`);
      continue; // container failed -- no field inside it can be checked
    }
    const requiredField = CHECKPOINT_REQUIRED_CONTENT_FIELD[phase];
    if (requiredField && value[requiredField] === undefined) {
      violations.push(`checkpoint-shape: phases.${phase} is missing required field ${requiredField}`);
    }
    const fields = CHECKPOINT_PHASE_SHAPE_TABLE[phase];
    for (const field of Object.keys(fields)) {
      const arrVal = value[field];
      if (arrVal === undefined) continue;
      if (!Array.isArray(arrVal)) {
        violations.push(`checkpoint-shape: phases.${phase}.${field} must be an array, got ${describeCheckpointShape(arrVal)}`);
        continue;
      }
      arrVal.forEach((el, idx) => {
        if (!isPlainCheckpointObject(el)) {
          if (fields[field] === CHECKPOINT_ARRAY_STRICT) {
            violations.push(`checkpoint-shape: phases.${phase}.${field}[${idx}] must be a plain object, got ${describeCheckpointShape(el)}`);
          }
          return;
        }
        if (CHECKPOINT_FINDING_FIELDS.has(field)) {
          violations.push(...checkpointFindingShapeErrors(el, `phases.${phase}.${field}[${idx}]`));
        }
      });
    }
  }
  return violations;
}

// The checkpoint-shape refusal's own recovery sentence. SKILL_RECOVERY_LINE (args.js) is
// wrong for this arm -- its advice is "run the skill instead", but the skill's own
// Phase 1-2 assembly does not construct a malformed checkpoint value in the first place,
// so telling the operator to re-run the skill would just replay the same corrupt
// artifact. The actionable fix is the checkpoint artifact itself.
const CHECKPOINT_SHAPE_RECOVERY_LINE = 'Repair or delete the corrupt checkpoint artifact, or re-run without the '
  + '`checkpoints` argument to start the review fresh.';

// makeCheckpointShapeRejectEnvelope(violations, nullArgGaps, contextSizeGap, discardGap) ->
// the dedicated pre-dispatch refusal for a #248/#250 shape violation. A SIBLING of
// makeArgsRejectEnvelope (args.js), not a reuse of it: this failure is not an args-shape
// failure (validateArgs already accepted `A`), so failingPhase/phaseReached name the
// pseudo-phase 'checkpoints' rather than 'args'. `checkpoints: { completed: [] }` is
// present -- SKILL.md documents every ok:false envelope as ALWAYS carrying `checkpoints`
// -- but carries NO `.phases` map, so headless auto-resume (which fires only when
// `.phases` is present) cannot replay the same still-malformed checkpoint straight back in.
//
// `nullArgGaps` (the caller's already-computed nullToleranceRejectedKeys disclosures, same
// value the args-reject exit above threads into ITS gaps) rides on this exit too, exactly
// as stages.js's tolerated-null invariant promises ("rides on BOTH exits" -- runWith's own
// comment on that computation). Before this parameter existed, a run that both mis-stamped
// a nullable top-level field AND replayed a malformed checkpoint lost the null disclosure
// entirely: the checkpoint gate returns before the null-tolerant success exit even runs, so
// nullArgGaps had nowhere else to surface. `contextSizeGap` (the caller's already-computed
// context_unmeasured/context_unplannable disclosure, always an array of 0 or 1 strings)
// rides here for the identical reason -- it is computed above the gate too, and this was
// the one exit that dropped it silently on the floor.
//
// `discardGap` (issue #268; also computed above the gate, alongside contextSizeGap) is the
// same shape as contextSizeGap -- a 0-or-1-element `checkpoint-discarded:` array -- and
// rides here for the identical reason. Unreachable in production today (a garbage
// `args.checkpoints` alone resolves inert with zero shape violations, so this exit is never
// taken on that path alone; reaching both a discard AND a violation needs a garbage
// `args.checkpoints` PLUS a malformed `ctx.checkpoints` fallback seam), but one line buys
// consistency with this envelope's own nullArgGaps/contextSizeGap rationale rather than a
// silent gap-channel gap should that combination ever become reachable. The #270 arms
// specifically (checkpointDiscardGap's zero-recognized and empty-.phases-masking cases,
// as opposed to #268's unwrap-rejection case) can never co-occur with a shape violation at
// all: both #270 arms require unwrapCheckpointMap to have SUCCEEDED to a resolved map whose
// keys checkpointShapeErrors -- which runs immediately after, on that same resolved map --
// never inspects (unrecognized names, or nothing at the top level of `.phases`), so a #270
// disclosure and a shape violation are always mutually exclusive on the SAME resolved map.
function makeCheckpointShapeRejectEnvelope(violations, nullArgGaps = [], contextSizeGap = [], discardGap = []) {
  const extra = violations.length - 1;
  const error = extra > 0
    ? `${violations[0]} (and ${extra} more checkpoint-shape violation${extra === 1 ? '' : 's'}). ${CHECKPOINT_SHAPE_RECOVERY_LINE}`
    : `${violations[0]}. ${CHECKPOINT_SHAPE_RECOVERY_LINE}`;
  return {
    ok: false,
    error,
    failingPhase: 'checkpoints',
    phaseReached: 'checkpoints',
    artifactPaths: {},
    stats: {},
    gaps: [...nullArgGaps, ...contextSizeGap, ...discardGap, ...violations],
    checkpoints: { completed: [] },
  };
}

// buildResumeCheckpoints(phaseOutputs) -> resume state for a FAILURE-path return.
// Carries the full per-phase outputs map ({ phases, completed }) so the skill can resume
// from the compact return when nothing was persisted — UNLESS that map would exceed the
// RETURN char budget, in which case only the completed-phase NAMES are returned with
// truncated:true (resume then falls back to re-running from scratch).
// readCheckpoints unwraps the .phases form directly.
//
// The budget here is RETURN_CHAR_BUDGET, not the prompt-segmentation one. This is the
// only thing the map has to survive — the harness serializes the return to
// `tasks/<taskid>.output` and no model retypes it — and the prompt budget it used to
// share was sized for a WRITER'S CONTEXT, a limit that does not apply to this channel at
// all. Three recorded runs tripped the 100,000-char ceiling and threw away resume state
// that would have crossed the real one (measured byte-exact to 4 MB) untouched.
function buildResumeCheckpoints(phaseOutputs) {
  const completed = Object.keys(phaseOutputs);
  const withPhases = { phases: phaseOutputs, completed };
  if (JSON.stringify(withPhases).length <= RETURN_CHAR_BUDGET) return withPhases;
  return { completed, truncated: true };
}

// Phases whose FULL output a resume from the PERSISTED (successful-run) checkpoint actually
// consumes. Exactly ONE qualifies: `challenge` carries the delivered high-confidence findings
// and the `unverified` bucket that selectDelivery, the report input, and writeArtifacts read
// BY VALUE — replaying it is what makes the delivered set on a resume verbatim-identical.
//
// `filter` is deliberately NOT persisted (issue #38, P1). On a resume from the persisted
// checkpoint, summarize/discover/verify/validate/filter re-run, while challenge carries the
// delivered findings and unverified bucket by value. Filter is a PURE agent-free JS function,
// so it re-runs at ZERO dispatch cost and its fresh stats feed the report input and envelope.
// Persisting it bought nothing and cost 35% of the checkpoint artifact's bytes in the profiled
// run. Every other phase contributes only a count/stat on resume, never its findings bulk.
const PERSISTED_RESUME_PHASES = ['challenge'];

// phaseFindingCount(out) -> the count summarizing one phase's output for the slim checkpoint
// (findings-bearing stages carry `findings`; the filter stage carries `filtered`).
function phaseFindingCount(out) {
  if (!out || typeof out !== 'object') return 0;
  if (Array.isArray(out.findings)) return out.findings.length;
  if (Array.isArray(out.filtered)) return out.filtered.length;
  return 0;
}

// slimPersistedCheckpoints(phaseOutputs, completed, phaseReached) -> the checkpoint artifact
// the writer persists at the end of a successful run. Only the resume-consumed phases
// (PERSISTED_RESUME_PHASES) keep their FULL output; every phase additionally records a bare
// count. This drops the by-value duplication where the OLD persisted checkpoint carried every
// phase's full findings array (discover/merge/verify/validate each ~a full findings set) inside
// the single artifact-writer prompt. readCheckpoints unwraps `.phases`, so a resume from this
// artifact skips exactly the preserved phases (reusing the delivered findings verbatim) and
// re-runs the rest. The in-memory failure-path resume (buildResumeCheckpoints) is intentionally
// NOT slimmed — a crash-recovery resume still carries every phase's full output for a fast skip.
function slimPersistedCheckpoints(phaseOutputs, completed, phaseReached) {
  const outputs = phaseOutputs || {};
  const phases = {};
  for (const name of PERSISTED_RESUME_PHASES) {
    if (outputs[name] !== undefined) phases[name] = outputs[name];
  }
  const counts = {};
  for (const [name, out] of Object.entries(outputs)) counts[name] = phaseFindingCount(out);
  return { phases, completed, phaseReached, counts };
}

// resolvedPolicyEnvelope(policy) -> the envelope's resolvedPolicy field, shared by the
// success return and the all-degraded failure return so the two report the identical
// resolution and a change to either fallback costs one edit.
// 'firstParty' when the waist omitted provider — the omission and the explicit value
// resolve identically in resolvePolicy, and the envelope reports the resolution.
//
// `gateway`/`conditionalSchema` (issue #218): a provider that would 400 on the conditional
// per-dimension construct must be self-diagnosing from the envelope alone, the same reason
// `provider` itself rides here — an operator staring at an all-degraded conventions-and-intent
// dispatch should not have to re-derive conditionalSchemaActive by hand. `conditionalSchema`
// is the SAME predicate the dispatch gate used (not re-derived by a parallel computation that
// could drift from it), so the envelope can never claim a resolution the dispatch disagrees
// with.
function resolvedPolicyEnvelope(policy) {
  return {
    subagentModel: policy.subagentModel || null,
    provider: policy.provider || 'firstParty',
    gateway: !!policy.gateway,
    conditionalSchema: conditionalSchemaActive(policy),
  };
}

// --- #253 replay filtering belt: helpers -------------------------------

// Marker key used ONLY to re-splice applyReplayInjectionScan's kept/eliminated
// output back into the ORIGINAL list order. Heuristic 10 (duplicate signature)
// is stateful over scan order, so object elements must be handed to the scan
// as ONE ordered list, not pre-partitioned by kind (kept vs. eliminated) --
// this key is how each element's original position survives that round trip;
// it never survives into a returned finding (stripped below on both paths).
const REPLAY_BELT_INDEX_KEY = '__replayBeltIndex';

// beltPartitionList(list) -> { list, eliminated }. The #253 belt's per-list
// worker for challengeOut.findings / .unverified:
//   - a non-array `list` (or an empty one) is returned untouched, `eliminated`
//     empty -- mirrors the #213 tolerance this belt replaces
//     (stages_delivery.test.js:488-512 is the sibling oracle for that same
//     tolerance, on .eliminated);
//   - a non-object element (null, a primitive -- stages_delivery.test.js:
//     514-542 is the oracle) keeps its exact position in the output, never
//     touched, never handed to the scan;
//   - every object element is normalized (normalizeFieldNames, idempotent --
//     a precondition of the scan, not pre-challenge semantics: a hand-built
//     or v2-era checkpoint can carry `body`/`line`/`blame_tag` instead of the
//     canonical names the scan reads) and then scanned as ONE ordered list
//     via applyReplayInjectionScan (heuristic 4 structurally excluded -- see
//     that function's doc comment in filterFindings.js). Survivors are
//     re-spliced back into their original relative position among the other
//     surviving elements; eliminated elements are removed from `list` and
//     returned separately, stamped with a `replay_belt: true` marker on top
//     of the scan's own eliminated_by/elimination_reason.
function beltPartitionList(list) {
  if (!Array.isArray(list) || list.length === 0) return { list, eliminated: [] };

  const positions = [];
  const objectElements = [];
  for (const el of list) {
    if (el && typeof el === 'object') {
      const idx = objectElements.length;
      objectElements.push({ ...el, [REPLAY_BELT_INDEX_KEY]: idx });
      positions.push({ objIdx: idx });
    } else {
      positions.push({ raw: el });
    }
  }
  if (objectElements.length === 0) return { list, eliminated: [] };

  normalizeFieldNames(objectElements);
  const { kept, eliminated } = applyReplayInjectionScan(objectElements);

  const survivorByIdx = new Map();
  for (const f of kept) {
    const { [REPLAY_BELT_INDEX_KEY]: idx, ...clean } = f;
    survivorByIdx.set(idx, clean);
  }
  const eliminatedOut = eliminated.map((f) => {
    const { [REPLAY_BELT_INDEX_KEY]: _idx, ...clean } = f;
    return { ...clean, replay_belt: true };
  });

  const splicedList = [];
  for (const p of positions) {
    if ('raw' in p) { splicedList.push(p.raw); continue; }
    if (survivorByIdx.has(p.objIdx)) splicedList.push(survivorByIdx.get(p.objIdx));
    // else: eliminated -- omitted from the spliced list, present in eliminatedOut.
  }

  return { list: splicedList, eliminated: eliminatedOut };
}

// stripEliminatedList(list) -> the #213-established element tolerance,
// reused by the #253 belt for the FINAL .eliminated strip (see the
// append-then-strip ordering at the call site, D2): a non-array `list`
// passes through untouched, a non-object element passes through untouched,
// every other element is run through applyInjectedProseStrip (idempotent --
// a no-op on an already-stripped finding, so a resume-of-a-resume is safe).
function stripEliminatedList(list) {
  return Array.isArray(list)
    ? list.map((f) => ((f && typeof f === 'object') ? applyInjectedProseStrip(f) : f))
    : list;
}

// #181: merge()'s per-agent channel/dedup/validation-warning granularity — the only
// place it exists — reaches a consumer on the compact return. Count fields ride as-is; free-text
// warning ARRAYS ride as lengths, so the compact-return principle (names/counts, never bulk)
// holds. Adding a methodology COUNT field is one edit in mergeFindings.js; adding a
// FREE-TEXT one is two — that entry plus one name here. Stated plainly rather than made
// clever: a heuristic that guessed at array-of-strings would silently truncate a future
// count array.
const METHODOLOGY_COUNT_ONLY_FIELDS = ['truncation_warnings', 'validation_warnings'];
function compactMethodology(m) {
  if (!m || typeof m !== 'object' || Array.isArray(m)) return {};
  const out = {};
  for (const [k, v] of Object.entries(m)) {
    out[k] = METHODOLOGY_COUNT_ONLY_FIELDS.includes(k) && Array.isArray(v) ? v.length : v;
  }
  return out;
}

// --- Full orchestration: runWith --------------------------------------------

// runWith(ctx, rawArgs) -> compact envelope.
// The single testable orchestration seam (pipeline_entry.js's run() just builds the
// real-globals ctx and delegates here). Validates the args waist up front (reject ->
// ok:false, no dispatch), then threads summarize -> discover -> merge -> verify ->
// validate -> filter -> challenge -> report inside ONE top-level try/catch, checking
// checkpoints before each phase and persisting via writeArtifacts at the end. Every
// stage's gaps aggregate into the final envelope. writeArtifacts catches its own agent
// throws (degrading to a partial-artifacts gap), so the top-level catch is the last
// resort for unexpected throws in the deterministic glue — it returns
// { ok:false, error, phaseReached } and NEVER lets a throw escape.
// The return is compact by design: counts + artifact paths + gaps, never the raw
// findings bulk.
async function runWith(ctx, rawArgs) {
  // Two seams into args handling, one message (issue #27). pipeline_entry.js's
  // parseEntryArgs is the live naked-call path and THROWS on a refusal — a throw is the
  // only signal the platform renders as a failure (a returned ok:false reports as
  // <status>completed</status>, identical to success; see args.js's parseEntryArgs
  // comment). This arm exists because runWith's OWN contract is throw-free (this doc
  // comment already promised it "NEVER lets a throw escape") and empirically was not:
  // normalizeArgsReport's JSON.parse below used to sit outside any try/catch, so
  // `runWith(undefined, 'PR 310')` escaped as an uncaught native SyntaxError. So a refusal
  // here RETURNS the same entryArgs(rawArgs) refusal instead of throwing — same
  // refusalFrom wording as the entry, wrapped in makeArgsRejectEnvelope, so the wording
  // cannot drift between the two signals (pinned by a test). This arm is defensive, not
  // the primary guard: in production the entry throws first, so a live naked call never
  // reaches here. It is still worth fixing — runWith is exported, directly unit-tested,
  // and documented as throw-free.
  const entry = entryArgs(rawArgs);
  if (!entry.ok) return entry.envelope;
  // Normalization is TOLERANT of a stamped null for the narrow NULLABLE_TOP_LEVEL allowlist
  // (issue #38 A1 — a rejected dispatch cost a 21.3s round trip). Tolerance without
  // disclosure would be a silent config substitution, though: a mis-stamped
  // `reviewConfig: null` reviews on the Filter stage's built-in 55/70 instead of the
  // operator's REVIEW.md thresholds, changing the DELIVERED set. So every drop that actually
  // tolerated something becomes an operator-actionable gap here — the one place that owns the
  // returned envelope — and it rides on BOTH exits below (the reject envelope and the success
  // envelope). Drops validateArgs would have ACCEPTED anyway (`checkpoints`, which has no
  // shape check at all) are filtered out by nullToleranceRejectedKeys: nothing was tolerated,
  // so claiming a degradation would be gap-channel noise on a previously valid, silent run.
  // Normalize from entry.waist, not rawArgs: entryArgs has already unwrapped every JSON
  // layer, and normalizeArgsReport peels exactly one — re-normalizing the raw value would
  // hand validateArgs a string for any waist encoded more than once.
  const { args: A, dropped: droppedNulls } = normalizeArgsReport(entry.waist);
  const nullArgGaps = nullToleranceRejectedKeys(A, droppedNulls).map(nullToleranceGap);
  const check = validateArgs(A);
  if (!check.ok) {
    // The field list says WHAT is wrong; SKILL_RECOVERY_LINE says where the fields come
    // from. A naked caller that hand-built an object reads only this string (the platform
    // reports the run as completed either way), so it has to carry both. Shape comes from
    // makeArgsRejectEnvelope — same factory entryArgs uses for its refusal arm.
    return makeArgsRejectEnvelope(
      `invalid args: ${check.errors.join('; ')}. ${SKILL_RECOVERY_LINE}`,
      [...nullArgGaps, ...check.errors],
    );
  }

  const c = ctx || defaultCtx();
  // Agent-count guard: coarsenLimits is applied at the two points its inputs exist.
  // The changed-file count is known at entry (bounds the summarize term); the finding
  // count exists only after merge, where the verify/validate/challenge terms get
  // re-coarsened. At or below benchmark scale the worst case sits far under the guard,
  // so both calls return the limits values unchanged.
  const nChangedFiles = (A.changedFiles || []).length;
  let limits = coarsenLimits(A.limits || {}, nChangedFiles, 0);
  const policy = A.policy || {};
  const contextPath = `${A.outputDir}/code-gauntlet-context-${A.headShaShort}.md`;
  // The context file's own size, measured by the skill right after it writes the file
  // (the workflow has no disk and cannot measure it). Feeds contextReadPlan, which turns
  // it into the exact Read calls the prompt enumerates — issue #48. Both are OPTIONAL
  // because Phase 2 is model-executed and can skip the stamp; hard-failing there would
  // trade a partial read for a dead review. Absent (or unplannable) measurement falls
  // back to the count-free read-to-end wording — disclosed via a gap below, never silent.
  // Built ONCE, here, and threaded to the stages as a plain string. The stages are given
  // no path and no size, so none of them CAN name the shared context file without the read
  // plan — the invariant is structural, not asserted over this file's source text.
  const contextPlan = contextReadPlan(A.contextLines, A.contextChars);
  const contextLine = sharedContextLine({
    contextPath, contextLines: A.contextLines, contextChars: A.contextChars,
  });
  // DEGRADED IS NOT SILENT. Falling back to the count-free wording is legal (hard-failing
  // would trade a partial read for a dead run — a worse deal), but it drops the pipeline
  // back to the agent's own judgment about when it has read enough, which is exactly the
  // judgment that failed in #48. Two producers of that fallback must both disclose:
  //   1. contextLines absent — Phase 2 skipped the stamp (live; model-executed).
  //   2. contextLines stamped but contextReadPlan returns [] — the size clears the waist
  //      ceiling (5M lines) yet exceeds READ_PLAN_MAX_CHUNKS (~1.5M at the line cap). Checking
  //      only `=== undefined` left that second path silent: same fallback wording, zero gaps.
  // Same contract args.js states for a tolerated null: what was lost, and what to do about it.
  const contextSizeGap = A.contextLines === undefined
    ? ['context_unmeasured: args.contextLines was not stamped, so the shared-context read plan could not be computed — '
      + 'every agent got the count-free "read until a Read returns no further content" wording instead of the exact '
      + 'Read calls covering the file. That restores the failure mode of issue #48: a Read returns part of a large file '
      + 'with no truncation notice, and an agent that stops there reviews only what it saw. Stamp contextLines '
      + '(and contextChars) from the Phase 2 step that writes the context file.']
    : (contextPlan.length === 0
      ? ['context_unplannable: args.contextLines was stamped (' + A.contextLines + ') but exceeds the read-plan chunk '
        + 'ceiling, so the shared-context read plan could not be built — every agent got the count-free '
        + '"read until a Read returns no further content" wording instead of the exact Read calls covering the file. '
        + 'That restores the failure mode of issue #48 for an oversized context. Shrink the shared context '
        + '(or raise READ_PLAN_MAX_CHUNKS with a matching prompt-size budget) so a plan can be computed.']
      : []);
  // checkpoint-discarded (#268): computed EARLY, alongside contextSizeGap and before
  // readCheckpoints/the shape gate below, from the TOP-LEVEL `A.checkpoints` the operator
  // actually stamped -- not from the resolved map, which has already thrown the distinction
  // away by the time readCheckpoints returns. Disclose-not-abort, the same class as
  // contextSizeGap: readCheckpoints's existing fallback to {} on an unusable value is
  // correct behavior (never abort a review over a bad resume input), it was just silent.
  const discardGap = checkpointDiscardGap(A.checkpoints);
  const checkpoints = readCheckpoints(c, A);
  // Pre-dispatch, outside the try block: a malformed replayed checkpoint value is
  // refused loud instead of reaching a phase's unconditional downstream read (#248 +
  // #250). Nothing has dispatched yet -- the earliest phase promise is created below,
  // inside the try -- so this can never abandon in-flight work. nullArgGaps is already
  // computed above (before validateArgs) and threaded through so a tolerated-null
  // disclosure still rides on THIS exit too, not just the args-reject and success exits.
  const checkpointShapeViolations = checkpointShapeErrors(checkpoints);
  if (checkpointShapeViolations.length) {
    return makeCheckpointShapeRejectEnvelope(checkpointShapeViolations, nullArgGaps, contextSizeGap, discardGap);
  }

  const gaps = [...nullArgGaps, ...contextSizeGap, ...discardGap];
  const completed = [];
  const phaseOutputs = {}; // per-phase output map — persisted as the checkpoint artifact
  let phaseReached = 'start';
  // The phase currently being ATTEMPTED — distinct from phaseReached (last COMPLETED).
  // On a throw, phaseReached names the phase BEFORE the one that blew up; narrating the
  // crash from it misattributes the failure (live run: a Filter throw reported as
  // "failed during Validate"). The catch envelope carries both.
  let phaseAttempting = null;

  // Resume: a phase whose checkpoint is present reuses that output instead of
  // dispatching. Either way the phase counts as reached, and its output is recorded
  // into phaseOutputs so the persisted checkpoint artifact is a producible resume map.
  const runPhase = async (name, thunk) => {
    phaseAttempting = name;
    const out = checkpoints[name] !== undefined ? checkpoints[name] : await thunk();
    phaseOutputs[name] = out;
    completed.push(name);
    phaseReached = name;
    return out;
  };

  // Summarize and Discover have NO data dependency: summarize's output is first read at
  // reportInput, and discover's input is built only from the derived scope flags / limits /
  // policy / contextPath — `limits` being coarsenLimits(A.limits, nChangedFiles, 0), computed above,
  // before either. So both are STARTED here and awaited in order below. Four properties are
  // load-bearing and each is pinned by a test in stages_latency.test.js:
  //   1. Checkpoint semantics: a phase whose checkpoint is present must NOT dispatch, so the
  //      promise is only created when checkpoints[name] === undefined (null = replay it).
  //   2. Record ORDER: summarize is still awaited (and so recorded into phaseOutputs /
  //      completed / counts) BEFORE discover — both are consumer-visible in the artifact.
  //   3. No unhandled rejection: `settle` attaches its handlers the instant the promise is
  //      created, so a discover rejection arriving while summarize is still being awaited is
  //      captured, never floating. It is re-thrown at the point the phase is awaited.
  //   4. Error attribution: because the re-throw happens inside runPhase's thunk, a discover
  //      failure is still attributed to failingPhase 'discover', never 'summarize'.
  // settle(p) -> Promise<thunk>: the thunk returns the value or re-throws the error.
  const settle = (p) => p.then((value) => () => value, (error) => () => { throw error; });
  const replay = (name) => checkpoints[name] !== undefined;

  try {
    const summarizeSettled = replay('summarize') ? null : settle(summarize(c, {
      changedFiles: A.changedFiles || [], changedLines: A.changedLines || 0, limits, policy, contextLine,
    }));
    // Issue #24 req 1/4/5 (PR3): the scope-gating map is DERIVED here, deterministically,
    // from the waist's riskTable/changedLines/scopeAnswer — never read from a caller-stamped
    // agentFlags (validateArgs above hard-rejects one). Single call, echoed below in
    // stats.scope so the resolved decision is verifiable post-hoc.
    const derivedAgentFlags = deriveAgentFlags(A.riskTable, A.changedLines, A.scopeAnswer);
    const discoverSettled = replay('discover') ? null : settle(discover(c, {
      agentFlags: derivedAgentFlags, limits, policy, contextLine,
    }));

    const summaryOut = await runPhase('summarize', async () => (await summarizeSettled)());
    gaps.push(...(summaryOut.gaps || []));

    const discoverOut = await runPhase('discover', async () => (await discoverSettled)());
    gaps.push(...(discoverOut.gaps || []));

    // All-degraded guard (issue #178, live Bedrock incident 2026-08-11: invalid model ID,
    // 2s run, 0 findings, ok:true). Fail loud here rather than degraded-but-disclosed: an
    // all-degraded discover output means NOTHING was reviewed, so letting the pipeline run
    // on to a report is not a partial review with a gap attached, it is an EMPTY report
    // dressed as ok:true — the exact silent-success class the gap channel exists to
    // prevent. Partial degradation (some but not all active dimensions failing) is
    // unaffected: this only fires when the intersection of dispatched and degraded is total.
    //
    // Placed AFTER the gap merge above, not before: this guard fires whether discoverOut
    // came from a fresh dispatch or a REPLAYED checkpoint (the `runPhase` resume branch
    // returns the same shape either way), so a stale checkpoint that recorded an
    // all-degraded discover never gets to replay its emptiness into another ok:true run.
    // The per-agent 'agent returned null' gaps pushed just above still ride the returned
    // envelope, so the operator sees exactly which agents failed, not just that they did.
    //
    // The discover phase is dropped from the returned resume checkpoints (never from
    // phaseOutputs, which the catch-path/failure envelope still needs whole): a checkpoint
    // that resumes straight into a replay of this same degraded-to-nothing output would
    // reproduce the failure forever. Dropping it forces a retry to re-dispatch discovery —
    // the one phase a corrected model/provider policy can actually fix.
    //
    // stats.degraded and resolvedPolicy ride this failure envelope even though the
    // top-level catch below carries neither: they are the operator's diagnosis. degraded
    // names which dimensions came back empty and resolvedPolicy names the model/provider
    // this run actually resolved to, so "why did discovery fail" is answerable from the
    // envelope alone — a mismatch between resolvedPolicy and the intended model is the
    // most common root cause (this guard's own incident was exactly that).
    //
    // Two more conjuncts guard this trip, both added after the helper's fail-closed arm
    // above (issue #178 follow-up):
    //   (a) `(discoverOut.findings || []).length === 0` — on a SAME-VERSION discover
    //       output this is vacuously true (a degraded agent contributes no findings by
    //       construction), so it changes nothing there. It exists solely so the helper's
    //       fail-closed arm never aborts a VERSION-SKEW replay (a renamed/unresolvable
    //       agentType in `dispatched`) that still carries real findings from before the
    //       rename — those findings are real work product, not the silent emptiness this
    //       guard exists to catch.
    //   (b) `checkpoints.challenge === undefined` — a replayable challenge checkpoint
    //       (PERSISTED_RESUME_PHASES) means a PRIOR attempt already reviewed and its
    //       delivered set is sitting in `checkpoints.challenge`. Aborting here would drop
    //       that checkpoint from the returned resume map (this branch strips `discover`,
    //       not `challenge`, but returning early never reaches the phase that would carry
    //       it forward) and report "no review was performed" about a run that already
    //       delivered one. So a totally re-degraded fresh discovery on such a resume must
    //       NOT abort — it stays degraded-but-disclosed (the per-agent gaps and
    //       stats.degraded above still say so) and the run proceeds to replay and deliver
    //       the prior challenge output; the pure renderer below rebuilds the persisted report
    //       from that output, including the zero-finding case.
    if (allActiveDimensionsDegraded(discoverOut.dispatched, discoverOut.degraded)
      && (discoverOut.findings || []).length === 0
      && checkpoints.challenge === undefined) {
      gaps.push(`all-degraded: every active discovery dimension degraded (${(discoverOut.degraded || []).join(', ')}) — no discovery agent completed, so nothing was reviewed; failing loud instead of returning an empty clean review (see the per-agent gaps above; a model/provider mismatch is the most likely cause — the envelope's resolvedPolicy names the resolution)`);
      const resumable = { ...phaseOutputs };
      delete resumable.discover; // a degraded-to-nothing discover output must never replay on resume — a retry re-dispatches discovery under (possibly corrected) policy
      return {
        ok: false,
        error: 'all-degraded: every active discovery dimension degraded — no review was performed',
        phaseReached,
        failingPhase: 'discover',
        artifactPaths: {},
        stats: { discovered: 0, degraded: discoverOut.degraded || [] },
        resolvedPolicy: resolvedPolicyEnvelope(policy),
        checkpoints: buildResumeCheckpoints(resumable),
        gaps,
      };
    }

    const mergeOut = await runPhase('merge', () => mergeStage(discoverOut, {
      base_branch: A.baseBranch, head_sha: A.headShaShort,
    }));

    // The finding count now exists — re-coarsen so verify slices, validate batches,
    // and the challenge cap keep the remaining worst-case fan-out under the guard.
    limits = coarsenLimits(limits, nChangedFiles, (mergeOut.findings || []).length);

    const verifyOut = await runPhase('verify', () => verifyStage(c, {
      findings: mergeOut.findings || [], limits, policy, nonce: A.nonce, headShaShort: A.headShaShort,
      verify: { ...(A.verify || {}), baseBranch: A.baseBranch, diffPath: A.diffPath },
    }));
    gaps.push(...(verifyOut.gaps || []));

    const validateOut = await runPhase('validate', () => validateStage(c, {
      findings: verifyOut.findings || [], limits, policy, contextLine,
    }));
    gaps.push(...(validateOut.gaps || []));

    // resolveReviewConfig (issue #24 PR2): a strict superset of the old A.reviewConfig ||
    // {} / A.exclusionPatterns || [] passthrough — when A.reviewMd/A.exclusionsText are
    // absent this resolves to exactly that, unchanged. filterStage's own input shape
    // ({findings, reviewConfig, exclusionPatterns, generatedAt}) stays untouched (parity
    // seam, issue #24 req 9).
    const resolvedReview = resolveReviewConfig(A);
    const filterOut = await runPhase('filter', () => filterStage({
      findings: validateOut.findings || [], reviewConfig: resolvedReview.reviewConfig,
      exclusionPatterns: resolvedReview.exclusionPatterns, generatedAt: A.generatedAt,
    }));

    const challengeOut = await runPhase('challenge', () => challengeStage(c, {
      // No context line: challengeStage never read one, and challengePrompt takes only the
      // finding — the challenger is structurally blind (it gets title/description/location
      // and opens the code itself). A dead contextPath was threaded here until issue #48;
      // passing context to a stage that must not use it invites a future edit to "use the
      // context we already have" and quietly break the blindness the round exists for.
      findings: filterOut.filtered || [], limits, policy, generatedAt: A.generatedAt,
    }));
    gaps.push(...(challengeOut.gaps || []));

    // #253 replay filtering belt (v2): rebuilds the #213 belt above on a sounder
    // callable unit. A red-team of the #213 shape (redteam253.md) found that
    // straight-generalizing it to applyInjectionFilter was unsound: heuristic 4
    // (short description + high confidence) reads finding.confidence, a field
    // detectDisagreement mutates IN PLACE (the +10 consensus boost) AFTER filterStage's
    // own scan runs, so re-running the FULL filter here would eliminate a
    // legitimately-corroborated finding on a fresh run, not just a replay. The fix is
    // structural, not caller discipline: applyReplayInjectionScan (filterFindings.js)
    // is the same 10-heuristic core with heuristic 4 excluded by construction, so this
    // belt cannot reintroduce that failure mode no matter how it is called.
    //
    // Rationale for running it at all: a REPLAYED checkpoint.challenge (runPhase reuses
    // checkpoints.challenge verbatim, never re-dispatching challengeStage) bypasses this
    // run's filterStage scan entirely, so an OLDER checkpoint's findings can carry a
    // content pattern the CURRENT injection filter (whatever #256/#254/a later PR added)
    // would have caught. Runs for BOTH fresh and replay (no replay('challenge') gate):
    // on a fresh run every surviving finding already passed this exact scan (minus
    // heuristic 4) at filter time THIS run, so it is a no-op by construction there.
    //
    // Position-preserving partition, single walk per list (findings, then unverified):
    // beltPartitionList normalizes and re-scans only the OBJECT elements as one ordered
    // list (heuristic 10's dedup state makes scan order load-bearing), then re-splices
    // survivors back into their original relative position; a non-object element (null,
    // a primitive) keeps its exact position, never touched (stages_delivery.test.js:
    // 514-542 is the oracle). beltPartitionList ALSO tolerates a non-array findings/
    // unverified (returned untouched, `eliminated` empty), but that tolerance can no
    // longer be reached from a REPLAYED checkpoint: the pre-dispatch checkpoint-shape gate
    // (checkpointShapeErrors + makeCheckpointShapeRejectEnvelope, above runWith's try
    // block) already refuses a non-array phases.challenge.findings/.unverified before any
    // phase runs. It stays live only for a non-replay caller of beltPartitionList directly
    // -- stages_delivery.test.js:488-512's non-array `.eliminated` (wholly ungated by the
    // shape table, so still reachable via replay) is the closest surviving oracle for the
    // same code shape. See beltPartitionList's own doc comment for the splice mechanics
    // and stripEliminatedList's for the #213 element tolerance it reuses.
    //
    // .eliminated: newly-belt-eliminated entries APPEND first, then the WHOLE resulting
    // array runs through stripEliminatedList (order is the defence, D2): appending
    // eliminated findings straight from the scan carries their claude_md_rule/
    // suggestion/spec_text RAW (the scan's eliminated path never strips those -- only
    // its kept path does), and a finding can be eliminated by its description while
    // ALSO carrying an unrelated payload in one of those three fields; stripping the
    // whole array only after the append is what keeps that second payload out of
    // checkpoint-all.json. undefined/null .eliminated becomes a fresh array only when
    // there is something to put in it; any OTHER non-array (a malformed checkpoint) is
    // left untouched -- the append cannot happen, so the drop is disclosed on its own
    // gap line below instead of silently losing the eliminations.
    //
    // Rewrites challengeOut's OWN findings/unverified/eliminated/stats IN PLACE (not
    // threaded through locals): every existing downstream reader (selectDelivery/
    // reportInput below, writeArtifacts's `findings:` param, phaseOutputs.challenge ===
    // challengeOut already recorded by runPhase above) is automatically correct with no
    // second call site to keep in sync, and slimPersistedCheckpoints persists the
    // partitioned set so a future resume-of-a-resume replays an already-partitioned
    // checkpoint. Sharper invariant than the #213 `.map()` (same length, same order):
    // this REPLACES the three arrays wholesale, so a future reader inserted between
    // runPhase('challenge') and this belt would silently see the pre-partition arrays --
    // nothing today holds such a reference, but a later edit must not add one without
    // moving it below this block.
    //
    // Guard: `challengeOut && typeof challengeOut === 'object'` below. A MALFORMED
    // replayed checkpoint (checkpoints.challenge a non-object -- string/number/boolean)
    // can no longer reach this belt at all: the pre-dispatch checkpoint-shape gate
    // (checkpointShapeErrors + makeCheckpointShapeRejectEnvelope, above runWith's try
    // block) already refuses any non-object phases.challenge before any phase is
    // attempted, so runPhase('challenge') never hands this function a primitive on a
    // replay. This guard is retained as DEFENSE-IN-DEPTH only, for a source the gate does
    // not cover -- a fresh (non-replayed) challengeStage() call returning something other
    // than an object, or a future caller of this belt outside runWith's replay path.
    // Every challengeOut.PROPERTY *read* below already returns undefined on a primitive
    // (JS property access, not assignment), and the `|| []` fallbacks downstream turn that
    // into an empty, ok:true review. Property ASSIGNMENT on a primitive throws in strict
    // mode (this file is an ES module), which the belt would otherwise introduce as the
    // FIRST write ever made to challengeOut, turning a tolerated malformed value into an
    // uncaught throw -- so the belt still guards itself to a no-op when challengeOut is
    // not an object, exactly as before.
    //
    // The belt may remove replayed findings while preserving their disclosure in the
    // replay-filter gap and eliminated bucket. If it removes the whole delivered set, the
    // pure renderer still produces the canonical zero-finding report; no second report
    // decision is needed here.
    if (challengeOut && typeof challengeOut === 'object') {
      const findingsResult = beltPartitionList(challengeOut.findings);
      const unverifiedResult = beltPartitionList(challengeOut.unverified);
      challengeOut.findings = findingsResult.list;
      challengeOut.unverified = unverifiedResult.list;
      const newlyEliminated = [...findingsResult.eliminated, ...unverifiedResult.eliminated];

      let droppedCount = 0;
      if (Array.isArray(challengeOut.eliminated)) {
        challengeOut.eliminated = [...challengeOut.eliminated, ...newlyEliminated];
      } else if ((challengeOut.eliminated === undefined || challengeOut.eliminated === null) && newlyEliminated.length) {
        challengeOut.eliminated = newlyEliminated;
      } else if (newlyEliminated.length) {
        // A malformed .eliminated that is truthy and non-array (e.g. the string
        // 'not-an-array', per the #213 tolerance test) cannot receive an append --
        // these eliminations are dropped, not delivered and not persisted anywhere,
        // and disclosed on their own gap line below (there is nothing to append to).
        droppedCount = newlyEliminated.length;
      }
      challengeOut.eliminated = stripEliminatedList(challengeOut.eliminated);

      // stats: final_count/skipped are the two numeric keys whose value IS the length
      // of an array this belt just rewrote (challengeOut.findings / .unverified), so
      // they are set BY ASSIGNMENT from those arrays' actual post-belt lengths -- never
      // by subtracting this call's elimination count from whatever the replayed
      // checkpoint claimed, which would only preserve (and on a stale/hand-edited
      // checkpoint, compound) a pre-existing drift instead of correcting it. This makes
      // the #192 principle ("a stale challengeOut.stats never claims more survivors
      // than are actually in the arrays it sits next to") structural rather than
      // arithmetic. NOT exhaustive, and not claimed to be: challenge_survived/
      // challenge_contested/challenge_downgraded/unchallenged are untouched here --
      // they are applyChallenges' PRE-belt per-outcome counts of what the challenge
      // stage itself decided, and this belt's elimination is a LATER, separate cut over
      // the same .findings/.unverified arrays, so after a belt elimination those
      // buckets no longer sum to final_count. A reader of stats.challenge must treat
      // them as pre-belt context, not a live survivor breakdown. reportInput and the
      // envelope both read challengeOut.stats BY REFERENCE (this same object, further
      // down in this function), so this mutation is visible to both for free.
      // replay_belt_eliminated is this CALL's own total (not a cross-resume running
      // total -- the gap line below is the resume-safe signal for that, and
      // replay_belt_dropped just below is its cross-resume counterpart for the drop
      // path); it is always stamped, even at 0, so a reader never has to distinguish
      // "zero eliminations" from "key absent".
      if (challengeOut.stats && typeof challengeOut.stats === 'object') {
        const k1 = findingsResult.eliminated.length;
        const k2 = unverifiedResult.eliminated.length;
        if (typeof challengeOut.stats.final_count === 'number' && Array.isArray(challengeOut.findings)) {
          challengeOut.stats.final_count = challengeOut.findings.length;
        }
        if (typeof challengeOut.stats.skipped === 'number' && Array.isArray(challengeOut.unverified)) {
          challengeOut.stats.skipped = challengeOut.unverified.length;
        }
        challengeOut.stats.replay_belt_eliminated = k1 + k2;

        // Durable drop-disclosure counter: the sibling accumulation to markedCount's
        // DERIVATION below, for the case markedCount cannot cover -- a malformed
        // (truthy, non-array) .eliminated means the drop is recorded NOWHERE in the
        // checkpoint, so there is nothing to re-derive from on a later resume. Carrying
        // a running total here (only ever increased) is what lets a resume-of-a-resume
        // still disclose a drop this call's own droppedCount (0) would otherwise hide.
        // Only accumulated when stats is a plain object; when it is not, the per-call
        // gap line below is the only disclosure there is for this run.
        const priorDropped = (typeof challengeOut.stats.replay_belt_dropped === 'number'
          && Number.isFinite(challengeOut.stats.replay_belt_dropped))
          ? challengeOut.stats.replay_belt_dropped
          : 0;
        challengeOut.stats.replay_belt_dropped = priorDropped + droppedCount;
      }

      // Disclosure -- idempotent BY DERIVATION, not by counting this call's own
      // eliminations: counts replay_belt-marked entries actually sitting in
      // .eliminated right now, newly appended this run PLUS any carried over from a
      // PRIOR resume's belt run (persisted verbatim in the checkpoint). A
      // resume-of-a-resume that eliminates nothing NEW still discloses the full
      // loss this way, rather than the gap silently vanishing on the second resume.
      // Pushed to runWith's own top-level `gaps` (below), never `challengeOut.gaps`
      // (which rides into the persisted checkpoint and would double-count on the
      // NEXT resume's re-derivation of this same count).
      const markedCount = Array.isArray(challengeOut.eliminated)
        ? challengeOut.eliminated.filter((f) => f && typeof f === 'object' && f.replay_belt === true).length
        : 0;
      if (markedCount > 0) {
        gaps.push(`replay-filter: ${markedCount} finding(s) recorded by an earlier pipeline pass matched this run's injection filter and were removed — disclosed per-finding in the eliminated set (eliminated_by:'injection', replay_belt:true), not counted in stats.filter`);
      }

      // Drop-gap count: the DURABLE accumulated value (stats.replay_belt_dropped) when
      // challengeOut.stats is a plain object, so the disclosure survives a
      // resume-of-a-resume where this call's own droppedCount is 0 because the belt
      // already shrank the arrays on a prior pass and there was never an array to leave
      // a residue in; otherwise this call's own droppedCount is the only disclosure
      // there is.
      const dropGapCount = (challengeOut.stats && typeof challengeOut.stats === 'object'
        && typeof challengeOut.stats.replay_belt_dropped === 'number')
        ? challengeOut.stats.replay_belt_dropped
        : droppedCount;
      if (dropGapCount > 0) {
        gaps.push(`replay-filter: ${dropGapCount} finding(s) recorded by an earlier pipeline pass matched this run's injection filter, but the malformed (non-array) eliminated bucket on this checkpoint could not record them — dropped, not delivered, not persisted`);
      }
    }

    // Deterministic delivery selection: the challenge-survivors filtered by the user-chosen
    // delivery TIER (args.delivery.tier — 'all' by default, 'main_only' to withhold
    // suggestions), rank-ordered and capped at limits.deliveryCap (fed from
    // CODE_GAUNTLET_PR_COMMENT_CAP by the skill). Persisted so Phase 8 posts it verbatim — the
    // live agent never re-filters or re-ranks. Challenge-removed (challengeOut.eliminated) and
    // challenge-skipped (challengeOut.unverified) are already absent here, so they stay excluded.
    const deliveryTier = A.delivery && A.delivery.tier;
    // selectDelivery ranks through the renderer-owned tolerant projection, while retaining
    // the original finding objects for persistence. renderReport applies the projection again
    // to its own input, so malformed replay findings cannot reach a raw rankKey.
    const postReview = selectDelivery(challengeOut.findings, limits.deliveryCap, deliveryTier);

    const reportInput = {
      summary: summaryOut.summary,
      findings: challengeOut.findings,
      unverified: challengeOut.unverified,
      stats: {
        discovered: (discoverOut.findings || []).length,
        validate: validateOut.stats,
        filter: filterOut.stats,
        challenge: challengeOut.stats,
      },
      // discover()'s own fan-out list and degraded-dimensions list (issue #89) — feeds
      // dimensionsSummaryTable inside renderReport. `dispatched` already excludes any
      // agent scope-gated out via agentFlags (agentSpecs().filter(agentActive) runs
      // before discover() builds its spec list), so a light-scope run's skipped agents
      // are absent from `dispatched`, not merely present-but-empty.
      dimensions: { dispatched: discoverOut.dispatched || [], degraded: discoverOut.degraded || [] },
      headShaShort: A.headShaShort,
      generatedAt: A.generatedAt,
      prIdentity: (A.delivery || {}).prIdentity || null,
    };
    // Phase 8's report is a PURE FUNCTION of the pipeline's own output (issue #36) — no
    // agent, no prompt, no schema, no segmentation, no fallback. Four measured failure
    // modes died with the dispatch: a title that was never twice the same (0 of 115
    // persisted reports matched the documented format, 66 distinct first lines), a
    // markdown document returned JSON-wrapped, fields the contract named rendered
    // stochastically (evidence 9-13%), and headline counts the model computed wrong
    // (2 of 6). The renderer's section list is pinned to references/report-format.md by
    // a generated fence.
    //
    // It deliberately renders NO Review Methodology section and NO `Headless config:`
    // block: the orchestrator composes those at delivery (issue #182 owns that seam).
    let reportOut = await runPhase('report', () => ({ report: renderReport(reportInput), gaps: [] }));
    const reportGaps = reportOut.gaps || [];
    gaps.push(...reportGaps);
    // A replayed report checkpoint is legacy input, never a substitute for rendering.
    // Rebuild the persisted bytes from the current pipeline data while carrying forward
    // any gaps the checkpoint disclosed. Fresh reports are rebuilt too, keeping the
    // phaseOutputs invariant explicit at this seam.
    reportOut = { report: renderReport(reportInput), gaps: reportGaps };
    phaseOutputs.report = reportOut;

    // Persistence is a post-phase step: writeArtifacts owns its try/catch, so a
    // writer failure degrades to a partial-artifacts gap rather than the top-level catch.
    const writeOut = await writeArtifacts(c, {
      findings: challengeOut.findings,
      postReview,
      prIdentity: (A.delivery || {}).prIdentity, // L3: writer emits the post_review-ready wrapper when present
      report: reportOut.report,
      // Persist a SLIM checkpoint: only the resume-consumed phase (challenge) carries full
      // output; every other phase is reduced to a count, so the single artifact-writer
      // prompt no longer duplicates every phase's findings bulk by value. readCheckpoints
      // unwraps .phases, so a resume skips exactly the preserved phase and re-runs the rest.
      // The in-memory failure-path return below still carries the full phaseOutputs map.
      checkpoints: slimPersistedCheckpoints(phaseOutputs, completed, phaseReached),
      outputDir: A.outputDir,
      headShaShort: A.headShaShort,
      generatedAt: A.generatedAt,
      // The run's own id, echoed in persistReturn so the materializer can find this
      // run's task output file by content when no task id is in hand.
      nonce: A.nonce,
      // Optional (issue #38, D3.4): with an assembleScriptPath the writer persists only
      // the unique content and the executor derives the two projections on disk. Absent
      // (bench, older callers) -> the legacy full by-value path, no gap.
      persist: A.persist,
      policy,
    });
    gaps.push(...(writeOut.gaps || []));

    return {
      ok: true,
      phaseReached,
      stats: {
        discovered: (discoverOut.findings || []).length,
        merged: (mergeOut.findings || []).length,
        merge: compactMethodology(mergeOut.methodology),
        verified: verifyOut.verified,
        // The slice-input proof ledger (issue #69 / #25 req 4-6). `verified` is one
        // boolean about the whole stage; this says how many slices were PROVEN to have
        // been verified against the document this run dispatched, and how many were not.
        // `recovered` counts only PROVEN-and-recovered slices: a slice that is both
        // unprovable and recovered lands in `unprovable`, not here (the counters are
        // disjoint by construction — see emptyInputProof's comment).
        inputProof: verifyOut.inputProof,
        highConfidence: (challengeOut.findings || []).length,
        unverified: (challengeOut.unverified || []).length,
        degraded: discoverOut.degraded || [],
        validate: validateOut.stats,
        filter: filterOut.stats,
        // Compact provenance echo (issue #24 PR2): names/counts only, never bulk content —
        // no raw REVIEW.md text, no full config object. Two independent per-axis signals,
        // each 'reviewMd'/'exclusionsText' | 'preParsed' | 'none'; see resolveReviewConfig's
        // doc comment (args.js) for the full contract.
        reviewConfigSource: resolvedReview.reviewConfigSource,
        exclusionsSource: resolvedReview.exclusionsSource,
        reviewMdEntryCount: resolvedReview.reviewMdEntryCount,
        // Compact scope-decision echo (issue #24 req 3, PR3): names/bools only, so adherence
        // to the derived scope decision is verifiable post-hoc without re-deriving it from
        // riskTable. scopeAnswer is null (never omitted) when the gate was not asked, mirroring
        // how riskTable/reviewConfigSource echo "no signal" as an explicit value, not a hole.
        scope: {
          lightEligible: computeLightEligible(A.riskTable, A.changedLines),
          scopeAnswer: A.scopeAnswer !== undefined ? A.scopeAnswer : null,
          deep: derivedAgentFlags.deep !== false,
        },
        challenge: challengeOut.stats,
      },
      artifactPaths: writeOut.artifactPaths,
      resolvedPolicy: resolvedPolicyEnvelope(policy),
      // On persist success the resume state lives in artifactPaths.checkpoints — the
      // compact return carries only phase NAMES (never the findings bulk). If the writer
      // FAILED nothing was persisted, so carry the in-memory resume state (phases, or
      // names+truncated when it would exceed the budget) so the skill can still resume.
      checkpoints: writeOut.partial ? buildResumeCheckpoints(phaseOutputs) : { completed },
      gaps,
      // The RETURN persist channel's payload — the three primaries, verbatim, for Phase 8
      // to materialize (absent on every other path). It rides LAST on purpose: it is the
      // one field measured in tens of KB, and a reader that truncates gets the counts,
      // paths and gaps before it rather than after. scripts/await_workflow.py elides its
      // `entries[].text` so the bulk never enters the orchestrator's context at all.
      ...(writeOut.persistReturn ? { persistReturn: writeOut.persistReturn } : {}),
    };
  } catch (e) {
    // Nothing was persisted on the throw path either — carry the in-memory resume state
    // (bounded by the char budget) in the compact return so the skill can resume the
    // failed run rather than restarting from scratch.
    return {
      ok: false,
      error: (e && e.message) || String(e),
      phaseReached,
      failingPhase: phaseAttempting,
      artifactPaths: {},
      stats: {},
      checkpoints: buildResumeCheckpoints(phaseOutputs),
      gaps,
    };
  }
}

// --- pipeline_entry.js ---
// pipeline_entry.js — bundle entry. Emitted LAST by build.js; its `export const meta`
// literal and plain `const PIPELINE_VERSION` are hoisted to the top of the bundle.
// This file is import-free IN THE BUNDLE (build.js strips the source-only imports and
// relies on concat order — stages.js/args.js are emitted above). The workflow runtime
// rejects every `export` keyword except the meta literal (confirmed empirically:
// `export default` raises "SyntaxError: Unexpected keyword 'export'") and executes the
// bundle body as a wrapped async function — top-level `await`/`return` are the entry
// contract, and args arrive via the runtime-injected `args` global, not a parameter.

// meta.name MUST NOT equal the skill's name (`code-gauntlet`). Both are registered by
// this plugin, so an identical name made `/code-gauntlet:code-gauntlet` resolve to the
// WORKFLOW rather than the skill — and the workflow, invoked by name, receives the raw
// user string ("PR 87") where it requires the Phases 1-2 args waist. Measured 2026-07-30:
// the first task of that session failed by construction, and recovering from it the model
// went hunting for the plugin root with `find /` and ran an OLD cached version. The name
// is otherwise cosmetic here — the skill invokes this bundle by `scriptPath`, never by
// name — so it is free to disambiguate. `whenToUse` says the same thing to whoever reads
// the workflow list instead of this comment.

// run(rawArgs) — the thin public entry. Builds the real-globals ctx and delegates to
// runWith (in stages.js), which owns arg validation, the top-level try/catch, the full
// stage sequence, checkpoint resume, and the compact return. Kept minimal so the
// orchestration is exercised through the importable, test-driven runWith seam.
async function run(rawArgs) {
  return runWith(undefined, rawArgs);
}

// parseEntryArgs THROWS on a refusal (absent args, a review-target reference like a bare
// PR number/URL, or any other non-waist shape) rather than returning — the only signal
// this platform renders as a visible failure (issue #27; see the doc comment on
// parseEntryArgs in args.js for the verified reasoning). runWith carries the identical
// wording for its own, throw-free seam, so a naked Workflow call and a programmatic
// runWith() caller see the same message either way.
const __args = parseEntryArgs(typeof args === 'undefined' ? undefined : args);
return await run(__args);
